// Otomatik üretildi (eng/build.js). Elle düzenleme; metinler eng/content içinde.
export const LESSONS = [{"id":0,"lv":"A1","n":1,"title":"Hello, I am Deniz","tr":"Merhaba, ben Deniz","text":"Hello! My name is Deniz. I am a student. I am 19 years old. I am from Turkey. I live in Ankara. Ankara is a big city. I like my city. This is my first day at university. I am happy.","words":["hello","my","name","be","i","a","student","year","old","from","live","in","big","city","like","this","first","day","at","university","happy"],"ex":{"hello":"Hello!","my":"My name is Deniz.","name":"My name is Deniz.","be":"My name is Deniz.","i":"I am a student.","a":"I am a student.","student":"I am a student.","year":"I am 19 years old.","old":"I am 19 years old.","from":"I am from Turkey.","live":"I live in Ankara.","in":"I live in Ankara.","big":"Ankara is a big city.","city":"Ankara is a big city.","like":"I like my city.","this":"This is my first day at university.","first":"This is my first day at university.","day":"This is my first day at university.","at":"This is my first day at university.","university":"This is my first day at university.","happy":"I am happy."},"fm":{"be":"is","year":"years"}},{"id":1,"lv":"A1","n":2,"title":"My Family","tr":"Ailem","text":"This is my family. My father is Ahmet. He is a teacher. My mother is Zeynep. She is a doctor. I have a sister and a brother. My sister is Ayşe. She is 15. My brother is Mert. He is 10. We live in a small house. I love my family.","words":["family","father","he","teacher","mother","she","doctor","have","sister","and","brother","we","small","house","love"],"ex":{"family":"This is my family.","father":"My father is Ahmet.","he":"He is a teacher.","teacher":"He is a teacher.","mother":"My mother is Zeynep.","she":"She is a doctor.","doctor":"She is a doctor.","have":"I have a sister and a brother.","sister":"I have a sister and a brother.","and":"I have a sister and a brother.","brother":"I have a sister and a brother.","we":"We live in a small house.","small":"We live in a small house.","house":"We live in a small house.","love":"I love my family."},"fm":{}},{"id":2,"lv":"A1","n":3,"title":"Our House","tr":"Evimiz","text":"Our house is small, but it is nice. It has two bedrooms, a kitchen and a living room. My room is small too. In my room, there is a bed, a desk and a chair. There is a window. I can see a tree from my window. I like my room.","words":["our","but","it","nice","two","bedroom","kitchen","living","room","too","there","bed","desk","chair","window","can","see","tree"],"ex":{"our":"Our house is small, but it is nice.","but":"Our house is small, but it is nice.","it":"Our house is small, but it is nice.","nice":"Our house is small, but it is nice.","two":"It has two bedrooms, a kitchen and a living room.","bedroom":"It has two bedrooms, a kitchen and a living room.","kitchen":"It has two bedrooms, a kitchen and a living room.","living":"It has two bedrooms, a kitchen and a living room.","room":"It has two bedrooms, a kitchen and a living room.","too":"My room is small too.","there":"In my room, there is a bed, a desk and a chair.","bed":"In my room, there is a bed, a desk and a chair.","desk":"In my room, there is a bed, a desk and a chair.","chair":"In my room, there is a bed, a desk and a chair.","window":"There is a window.","can":"I can see a tree from my window.","see":"I can see a tree from my window.","tree":"I can see a tree from my window."},"fm":{"bedroom":"bedrooms"}},{"id":3,"lv":"A1","n":4,"title":"My Morning","tr":"Sabahım","text":"I get up at 7:00 every day. I wash my face and I brush my teeth. Then I eat breakfast with my family. I eat bread, cheese and eggs. I drink tea. My mother drinks coffee. At 8:00, I go to university by bus.","words":["get","up","every","wash","face","brush","tooth","then","eat","breakfast","with","bread","cheese","egg","drink","tea","coffee","go","to","by","bus"],"ex":{"get":"I get up at 7:00 every day.","up":"I get up at 7:00 every day.","every":"I get up at 7:00 every day.","wash":"I wash my face and I brush my teeth.","face":"I wash my face and I brush my teeth.","brush":"I wash my face and I brush my teeth.","tooth":"I wash my face and I brush my teeth.","then":"Then I eat breakfast with my family.","eat":"Then I eat breakfast with my family.","breakfast":"Then I eat breakfast with my family.","with":"Then I eat breakfast with my family.","bread":"I eat bread, cheese and eggs.","cheese":"I eat bread, cheese and eggs.","egg":"I eat bread, cheese and eggs.","drink":"I drink tea.","tea":"I drink tea.","coffee":"My mother drinks coffee.","go":"At 8:00, I go to university by bus.","to":"At 8:00, I go to university by bus.","by":"At 8:00, I go to university by bus.","bus":"At 8:00, I go to university by bus."},"fm":{"tooth":"teeth","egg":"eggs"}},{"id":4,"lv":"A1","n":5,"title":"At the University","tr":"Üniversitede","text":"My university is big. There are many students. I study engineering. My classes start at 9:00. Today I have two classes: math and physics. Math is easy for me, but physics is difficult. My teacher is very good. Her name is Ms Kaya.","words":["many","study","engineering","class","start","today","math","physics","easy","for","me","difficult","very","good","her"],"ex":{"many":"There are many students.","study":"I study engineering.","engineering":"I study engineering.","class":"My classes start at 9:00.","start":"My classes start at 9:00.","today":"Today I have two classes: math and physics.","math":"Today I have two classes: math and physics.","physics":"Today I have two classes: math and physics.","easy":"Math is easy for me, but physics is difficult.","for":"Math is easy for me, but physics is difficult.","me":"Math is easy for me, but physics is difficult.","difficult":"Math is easy for me, but physics is difficult.","very":"My teacher is very good.","good":"My teacher is very good.","her":"Her name is Ms Kaya."},"fm":{"class":"classes"}},{"id":5,"lv":"A1","n":6,"title":"A New Friend","tr":"Yeni bir arkadaş","text":"In the physics class, I meet a new friend. His name is Can. He is from Istanbul. He studies engineering too. Can is tall and funny. We sit together in class. After class, we drink tea in the garden. Can likes football. I like football too!","words":["the","meet","new","friend","his","tall","funny","sit","together","after","garden","football"],"ex":{"the":"In the physics class, I meet a new friend.","meet":"In the physics class, I meet a new friend.","new":"In the physics class, I meet a new friend.","friend":"In the physics class, I meet a new friend.","his":"His name is Can.","tall":"Can is tall and funny.","funny":"Can is tall and funny.","sit":"We sit together in class.","together":"We sit together in class.","after":"After class, we drink tea in the garden.","garden":"After class, we drink tea in the garden.","football":"Can likes football."},"fm":{}},{"id":6,"lv":"A1","n":7,"title":"Days of the Week","tr":"Haftanın günleri","text":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday. I go to university from Monday to Friday. On Saturday, I play football with Can. On Sunday, I stay at home. I read books and watch films. Sunday is my favourite day.","words":["seven","week","monday","tuesday","wednesday","thursday","friday","saturday","sunday","on","play","stay","home","read","book","watch","film","favourite"],"ex":{"seven":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","week":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","monday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","tuesday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","wednesday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","thursday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","friday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","saturday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","sunday":"There are seven days in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.","on":"On Saturday, I play football with Can.","play":"On Saturday, I play football with Can.","stay":"On Sunday, I stay at home.","home":"On Sunday, I stay at home.","read":"I read books and watch films.","book":"I read books and watch films.","watch":"I read books and watch films.","film":"I read books and watch films.","favourite":"Sunday is my favourite day."},"fm":{"book":"books","film":"films"}},{"id":7,"lv":"A1","n":8,"title":"What Time Is It?","tr":"Saat kaç?","text":"What time is it? It is 10:30. Now I am in the library. The library is quiet. I study math here for two hours. At 12:30, I have lunch with Can. We eat soup and rice. Lunch is not expensive at the university. Then we go back to class.","words":["what","time","now","library","quiet","here","hour","lunch","soup","rice","not","expensive","back"],"ex":{"what":"What time is it?","time":"What time is it?","now":"Now I am in the library.","library":"Now I am in the library.","quiet":"The library is quiet.","here":"I study math here for two hours.","hour":"I study math here for two hours.","lunch":"At 12:30, I have lunch with Can.","soup":"We eat soup and rice.","rice":"We eat soup and rice.","not":"Lunch is not expensive at the university.","expensive":"Lunch is not expensive at the university.","back":"Then we go back to class."},"fm":{"hour":"hours"}},{"id":8,"lv":"A1","n":9,"title":"Colours","tr":"Renkler","text":"I love colours. My favourite colour is blue. The sky is blue and the sea is blue. My bag is black. My shoes are white. Can's favourite colour is red. His car is red too. My sister Ayşe likes pink and purple. What is your favourite colour?","words":["colour","blue","sky","sea","bag","black","shoe","white","red","car","pink","purple","your"],"ex":{"colour":"I love colours.","blue":"My favourite colour is blue.","sky":"The sky is blue and the sea is blue.","sea":"The sky is blue and the sea is blue.","bag":"My bag is black.","black":"My bag is black.","shoe":"My shoes are white.","white":"My shoes are white.","red":"Can's favourite colour is red.","car":"His car is red too.","pink":"My sister Ayşe likes pink and purple.","purple":"My sister Ayşe likes pink and purple.","your":"What is your favourite colour?"},"fm":{"colour":"colours","shoe":"shoes"}},{"id":9,"lv":"A1","n":10,"title":"Clothes","tr":"Kıyafetler","text":"Today it is cold. I wear a warm coat, a sweater and jeans. I also wear a hat. In summer, I wear a shirt and shorts. My mother buys clothes for me. She says: \"Deniz, these shoes are old. You need new shoes.\" I want brown shoes.","words":["cold","wear","warm","coat","sweater","jeans","also","hat","summer","shirt","shorts","buy","clothes","say","these","you","need","want","brown"],"ex":{"cold":"Today it is cold.","wear":"I wear a warm coat, a sweater and jeans.","warm":"I wear a warm coat, a sweater and jeans.","coat":"I wear a warm coat, a sweater and jeans.","sweater":"I wear a warm coat, a sweater and jeans.","jeans":"I wear a warm coat, a sweater and jeans.","also":"I also wear a hat.","hat":"I also wear a hat.","summer":"In summer, I wear a shirt and shorts.","shirt":"In summer, I wear a shirt and shorts.","shorts":"In summer, I wear a shirt and shorts.","buy":"My mother buys clothes for me.","clothes":"My mother buys clothes for me.","say":"She says: \"Deniz, these shoes are old.","these":"She says: \"Deniz, these shoes are old.","you":"You need new shoes.\"","need":"You need new shoes.\"","want":"I want brown shoes.","brown":"I want brown shoes."},"fm":{"buy":"buys","say":"says"}},{"id":10,"lv":"A1","n":11,"title":"The Weather","tr":"Hava durumu","text":"What is the weather like today? In Ankara, winter is cold and snowy. Summer is hot and dry. Today it is sunny but windy. I take my umbrella because it often rains in spring. I like autumn. The trees are yellow and orange.","words":["weather","winter","snowy","hot","dry","sunny","windy","take","umbrella","because","often","rain","spring","autumn","yellow","orange"],"ex":{"weather":"What is the weather like today?","winter":"In Ankara, winter is cold and snowy.","snowy":"In Ankara, winter is cold and snowy.","hot":"Summer is hot and dry.","dry":"Summer is hot and dry.","sunny":"Today it is sunny but windy.","windy":"Today it is sunny but windy.","take":"I take my umbrella because it often rains in spring.","umbrella":"I take my umbrella because it often rains in spring.","because":"I take my umbrella because it often rains in spring.","often":"I take my umbrella because it often rains in spring.","rain":"I take my umbrella because it often rains in spring.","spring":"I take my umbrella because it often rains in spring.","autumn":"I like autumn.","yellow":"The trees are yellow and orange.","orange":"The trees are yellow and orange."},"fm":{"rain":"rains"}},{"id":11,"lv":"A1","n":12,"title":"Shopping","tr":"Alışveriş","text":"On Saturday morning, I go to the market with my mother. We buy fruit and vegetables. Apples are cheap today. We buy two kilos of apples, some tomatoes and potatoes. My mother asks: \"How much is it?\" The man says: \"Forty lira.\" We pay and go home.","words":["morning","market","fruit","vegetable","apple","cheap","kilo","of","some","tomato","potato","ask","how","much","man","forty","lira","pay"],"ex":{"morning":"On Saturday morning, I go to the market with my mother.","market":"On Saturday morning, I go to the market with my mother.","fruit":"We buy fruit and vegetables.","vegetable":"We buy fruit and vegetables.","apple":"Apples are cheap today.","cheap":"Apples are cheap today.","kilo":"We buy two kilos of apples, some tomatoes and potatoes.","of":"We buy two kilos of apples, some tomatoes and potatoes.","some":"We buy two kilos of apples, some tomatoes and potatoes.","tomato":"We buy two kilos of apples, some tomatoes and potatoes.","potato":"We buy two kilos of apples, some tomatoes and potatoes.","ask":"My mother asks: \"How much is it?\"","how":"My mother asks: \"How much is it?\"","much":"My mother asks: \"How much is it?\"","man":"The man says: \"Forty lira.\"","forty":"The man says: \"Forty lira.\"","lira":"The man says: \"Forty lira.\"","pay":"We pay and go home."},"fm":{"vegetable":"vegetables","apple":"apples","kilo":"kilos","tomato":"tomatoes","potato":"potatoes","ask":"asks"}},{"id":12,"lv":"A1","n":13,"title":"In the Kitchen","tr":"Mutfakta","text":"I can cook a little. Today I make pasta for my family. First, I boil water. Then I put the pasta in the water. I make a tomato sauce with oil, salt and garlic. My brother Mert helps me. Dinner is ready! Everyone likes my pasta.","words":["cook","little","make","pasta","boil","water","put","sauce","oil","salt","garlic","help","dinner","ready","everyone"],"ex":{"cook":"I can cook a little.","little":"I can cook a little.","make":"Today I make pasta for my family.","pasta":"Today I make pasta for my family.","boil":"First, I boil water.","water":"First, I boil water.","put":"Then I put the pasta in the water.","sauce":"I make a tomato sauce with oil, salt and garlic.","oil":"I make a tomato sauce with oil, salt and garlic.","salt":"I make a tomato sauce with oil, salt and garlic.","garlic":"I make a tomato sauce with oil, salt and garlic.","help":"My brother Mert helps me.","dinner":"Dinner is ready!","ready":"Dinner is ready!","everyone":"Everyone likes my pasta."},"fm":{"help":"helps"}},{"id":13,"lv":"A1","n":14,"title":"My Hobbies","tr":"Hobilerim","text":"I have three hobbies. First, I like reading. I read a book every month. Second, I love music. I play the guitar. Third, I like drawing. I draw pictures of buildings and machines. Can's hobby is photography. He takes photos of the city.","words":["three","hobby","month","second","music","guitar","third","drawing","draw","picture","building","machine","photography","photo"],"ex":{"three":"I have three hobbies.","hobby":"I have three hobbies.","month":"I read a book every month.","second":"Second, I love music.","music":"Second, I love music.","guitar":"I play the guitar.","third":"Third, I like drawing.","drawing":"Third, I like drawing.","draw":"I draw pictures of buildings and machines.","picture":"I draw pictures of buildings and machines.","building":"I draw pictures of buildings and machines.","machine":"I draw pictures of buildings and machines.","photography":"Can's hobby is photography.","photo":"He takes photos of the city."},"fm":{"hobby":"hobbies","picture":"pictures","building":"buildings","machine":"machines","photo":"photos"}},{"id":14,"lv":"A1","n":15,"title":"Sports","tr":"Spor","text":"Sport is important for me. I play football on Saturdays and I run in the park on Wednesdays. Can plays basketball too. He is a good player. My sister Ayşe swims. She goes to the swimming pool twice a week. My father walks every evening. Sport makes us healthy.","words":["sport","important","run","park","basketball","player","swim","swimming","pool","twice","walk","evening","us","healthy"],"ex":{"sport":"Sport is important for me.","important":"Sport is important for me.","run":"I play football on Saturdays and I run in the park on Wednesdays.","park":"I play football on Saturdays and I run in the park on Wednesdays.","basketball":"Can plays basketball too.","player":"He is a good player.","swim":"My sister Ayşe swims.","swimming":"She goes to the swimming pool twice a week.","pool":"She goes to the swimming pool twice a week.","twice":"She goes to the swimming pool twice a week.","walk":"My father walks every evening.","evening":"My father walks every evening.","us":"Sport makes us healthy.","healthy":"Sport makes us healthy."},"fm":{"swim":"swims","walk":"walks"}},{"id":15,"lv":"A1","n":16,"title":"At the Doctor","tr":"Doktorda","text":"Today I feel bad. My head hurts and my throat hurts too. I go to the doctor. The doctor asks some questions. \"Do you have a fever?\" \"Yes, a little.\" She says: \"You have a cold. Drink a lot of water and rest. Stay in bed for two days.\"","words":["feel","bad","head","hurt","throat","question","do","fever","yes","lot","rest"],"ex":{"feel":"Today I feel bad.","bad":"Today I feel bad.","head":"My head hurts and my throat hurts too.","hurt":"My head hurts and my throat hurts too.","throat":"My head hurts and my throat hurts too.","question":"The doctor asks some questions.","do":"\"Do you have a fever?\"","fever":"\"Do you have a fever?\"","yes":"\"Yes, a little.\"","lot":"Drink a lot of water and rest.","rest":"Drink a lot of water and rest."},"fm":{"hurt":"hurts","question":"questions"}},{"id":16,"lv":"A1","n":17,"title":"Animals","tr":"Hayvanlar","text":"My grandmother lives in a village. She has a farm. There are many animals on the farm: cows, sheep, chickens and a horse. She also has a dog and two cats. The dog's name is Karabaş. I visit my grandmother in summer. I help her with the animals. I feed the chickens.","words":["grandmother","life","village","farm","animal","cow","sheep","chicken","horse","dog","cat","visit","feed"],"ex":{"grandmother":"My grandmother lives in a village.","life":"My grandmother lives in a village.","village":"My grandmother lives in a village.","farm":"She has a farm.","animal":"There are many animals on the farm: cows, sheep, chickens and a horse.","cow":"There are many animals on the farm: cows, sheep, chickens and a horse.","sheep":"There are many animals on the farm: cows, sheep, chickens and a horse.","chicken":"There are many animals on the farm: cows, sheep, chickens and a horse.","horse":"There are many animals on the farm: cows, sheep, chickens and a horse.","dog":"She also has a dog and two cats.","cat":"She also has a dog and two cats.","visit":"I visit my grandmother in summer.","feed":"I feed the chickens."},"fm":{"life":"lives","animal":"animals","cow":"cows","chicken":"chickens","cat":"cats"}},{"id":17,"lv":"A1","n":18,"title":"Money","tr":"Para","text":"I have a small job. I help children with math on Tuesday evenings. I earn 500 lira a week. I spend 200 lira on food and 100 lira on transport. I save the rest of the money. I want to buy a new computer. A good computer costs a lot of money.","words":["job","child","earn","spend","food","transport","save","money","computer","cost"],"ex":{"job":"I have a small job.","child":"I help children with math on Tuesday evenings.","earn":"I earn 500 lira a week.","spend":"I spend 200 lira on food and 100 lira on transport.","food":"I spend 200 lira on food and 100 lira on transport.","transport":"I spend 200 lira on food and 100 lira on transport.","save":"I save the rest of the money.","money":"I save the rest of the money.","computer":"I want to buy a new computer.","cost":"A good computer costs a lot of money."},"fm":{"child":"children","cost":"costs"}},{"id":18,"lv":"A1","n":19,"title":"My Best Friend","tr":"En iyi arkadaşım","text":"My best friend is Elif. We are friends from high school. She is short and she has long black hair. She is very kind and clever. Elif studies medicine in Istanbul. We do not see each other often, but we talk on the phone every Sunday. I miss her.","words":["best","high","school","short","long","hair","kind","clever","medicine","each","other","talk","phone","miss"],"ex":{"best":"My best friend is Elif.","high":"We are friends from high school.","school":"We are friends from high school.","short":"She is short and she has long black hair.","long":"She is short and she has long black hair.","hair":"She is short and she has long black hair.","kind":"She is very kind and clever.","clever":"She is very kind and clever.","medicine":"Elif studies medicine in Istanbul.","each":"We do not see each other often, but we talk on the phone every Sunday.","other":"We do not see each other often, but we talk on the phone every Sunday.","talk":"We do not see each other often, but we talk on the phone every Sunday.","phone":"We do not see each other often, but we talk on the phone every Sunday.","miss":"I miss her."},"fm":{}},{"id":19,"lv":"A1","n":20,"title":"A Birthday","tr":"Bir doğum günü","text":"Today is my sister's birthday. She is 16 years old. We have a party at home. My mother makes a big chocolate cake. Ayşe's friends come to the party. They sing \"Happy Birthday\". I give her a present: a book and a pen. She is very happy. It is a great day.","words":["birthday","party","chocolate","cake","come","they","sing","give","present","pen","great"],"ex":{"birthday":"Today is my sister's birthday.","party":"We have a party at home.","chocolate":"My mother makes a big chocolate cake.","cake":"My mother makes a big chocolate cake.","come":"Ayşe's friends come to the party.","they":"They sing \"Happy Birthday\".","sing":"They sing \"Happy Birthday\".","give":"I give her a present: a book and a pen.","present":"I give her a present: a book and a pen.","pen":"I give her a present: a book and a pen.","great":"It is a great day."},"fm":{}},{"id":20,"lv":"A1","n":21,"title":"The Months","tr":"Aylar","text":"There are twelve months in a year. My birthday is in March. March is in spring. In June, the university closes and the summer holiday starts. In July and August, it is very hot. In September, classes start again. In December, it snows in Ankara. What month is your birthday?","words":["twelve","march","june","close","holiday","july","august","september","again","december","snow"],"ex":{"twelve":"There are twelve months in a year.","march":"My birthday is in March.","june":"In June, the university closes and the summer holiday starts.","close":"In June, the university closes and the summer holiday starts.","holiday":"In June, the university closes and the summer holiday starts.","july":"In July and August, it is very hot.","august":"In July and August, it is very hot.","september":"In September, classes start again.","again":"In September, classes start again.","december":"In December, it snows in Ankara.","snow":"In December, it snows in Ankara."},"fm":{"close":"closes","snow":"snows"}},{"id":21,"lv":"A1","n":22,"title":"Transport","tr":"Ulaşım","text":"Ankara has buses, a metro and taxis. I usually take the metro to university. It is fast and cheap. Sometimes I walk. Walking is slow, but it is good for me. My father drives a car to work. The roads are busy in the morning. Taxis are expensive.","words":["metro","taxi","usually","fast","sometimes","slow","drive","work","road","busy"],"ex":{"metro":"Ankara has buses, a metro and taxis.","taxi":"Ankara has buses, a metro and taxis.","usually":"I usually take the metro to university.","fast":"It is fast and cheap.","sometimes":"Sometimes I walk.","slow":"Walking is slow, but it is good for me.","drive":"My father drives a car to work.","work":"My father drives a car to work.","road":"The roads are busy in the morning.","busy":"The roads are busy in the morning."},"fm":{"taxi":"taxis","drive":"drives","road":"roads"}},{"id":22,"lv":"A1","n":23,"title":"Before the Exam","tr":"Sınava hazırlık","text":"Next week, I have a math exam. I study every day. I go to the library after class. I read my notes and I solve problems. Can studies with me. When we do not understand something, we ask Ms Kaya. She always helps us. I am a little nervous, but I am ready.","words":["next","exam","note","solve","problem","when","understand","something","always","nervous"],"ex":{"next":"Next week, I have a math exam.","exam":"Next week, I have a math exam.","note":"I read my notes and I solve problems.","solve":"I read my notes and I solve problems.","problem":"I read my notes and I solve problems.","when":"When we do not understand something, we ask Ms Kaya.","understand":"When we do not understand something, we ask Ms Kaya.","something":"When we do not understand something, we ask Ms Kaya.","always":"She always helps us.","nervous":"I am a little nervous, but I am ready."},"fm":{"note":"notes","problem":"problems"}},{"id":23,"lv":"A1","n":24,"title":"The Exam","tr":"Sınav günü","text":"Today is the exam day. I get up early. I eat a good breakfast. The exam starts at 10:00. There are ten questions. Some questions are easy and some are difficult. I answer all the questions. After the exam, I feel tired but happy. I think my exam is good.","words":["early","ten","answer","all","tired","think"],"ex":{"early":"I get up early.","ten":"There are ten questions.","answer":"I answer all the questions.","all":"I answer all the questions.","tired":"After the exam, I feel tired but happy.","think":"I think my exam is good."},"fm":{}},{"id":24,"lv":"A1","n":25,"title":"The Results","tr":"Sonuçlar","text":"One week later, Ms Kaya gives the results. I get 85 out of 100! Can gets 90. We are very happy. We call our families. My father says: \"Well done, Deniz!\" In the evening, we eat pizza with our friends. We celebrate.","words":["one","later","result","out","call","well","pizza","celebrate"],"ex":{"one":"One week later, Ms Kaya gives the results.","later":"One week later, Ms Kaya gives the results.","result":"One week later, Ms Kaya gives the results.","out":"I get 85 out of 100!","call":"We call our families.","well":"My father says: \"Well done, Deniz!\"","pizza":"In the evening, we eat pizza with our friends.","celebrate":"We celebrate."},"fm":{"result":"results"}},{"id":25,"lv":"A1","n":26,"title":"My Neighbourhood","tr":"Mahallem","text":"I live in a quiet neighbourhood. Near my house, there is a bakery, a pharmacy and a small supermarket. There is also a mosque and a park. Every morning, I buy fresh bread from the bakery. The baker is an old man. He is always friendly. He knows my name.","words":["neighbourhood","near","bakery","pharmacy","supermarket","mosque","fresh","baker","an","friendly","know"],"ex":{"neighbourhood":"I live in a quiet neighbourhood.","near":"Near my house, there is a bakery, a pharmacy and a small supermarket.","bakery":"Near my house, there is a bakery, a pharmacy and a small supermarket.","pharmacy":"Near my house, there is a bakery, a pharmacy and a small supermarket.","supermarket":"Near my house, there is a bakery, a pharmacy and a small supermarket.","mosque":"There is also a mosque and a park.","fresh":"Every morning, I buy fresh bread from the bakery.","baker":"The baker is an old man.","an":"The baker is an old man.","friendly":"He is always friendly.","know":"He knows my name."},"fm":{"know":"knows"}},{"id":26,"lv":"A1","n":27,"title":"Asking the Way","tr":"Yol sormak","text":"A tourist stops me in the street. \"Excuse me, where is the museum?\" he asks. \"Go straight on and turn left at the bank. The museum is next to the post office,\" I say. \"Is it far?\" \"No, it is near. It is five minutes on foot.\" He says: \"Thank you very much!\"","words":["tourist","stop","street","excuse","where","museum","straight","turn","left","bank","post","office","far","no","five","minute","foot","thank"],"ex":{"tourist":"A tourist stops me in the street.","stop":"A tourist stops me in the street.","street":"A tourist stops me in the street.","excuse":"\"Excuse me, where is the museum?\"","where":"\"Excuse me, where is the museum?\"","museum":"\"Excuse me, where is the museum?\"","straight":"\"Go straight on and turn left at the bank.","turn":"\"Go straight on and turn left at the bank.","left":"\"Go straight on and turn left at the bank.","bank":"\"Go straight on and turn left at the bank.","post":"The museum is next to the post office,\" I say.","office":"The museum is next to the post office,\" I say.","far":"\"Is it far?\"","no":"\"No, it is near.","five":"It is five minutes on foot.\"","minute":"It is five minutes on foot.\"","foot":"It is five minutes on foot.\"","thank":"He says: \"Thank you very much!\""},"fm":{"stop":"stops","minute":"minutes"}},{"id":27,"lv":"A1","n":28,"title":"A Phone Call","tr":"Bir telefon","text":"My phone rings. It is my grandmother. \"Hello, Deniz! How are you?\" \"I am fine, thank you. How are you, Grandma?\" \"I am well. When do you come to the village?\" \"I come in June, after my exams.\" \"Good! I want to see you. Study well!\"","words":["ring","fine","grandma"],"ex":{"ring":"My phone rings.","fine":"\"I am fine, thank you.","grandma":"How are you, Grandma?\""},"fm":{"ring":"rings"}},{"id":28,"lv":"A1","n":29,"title":"Cleaning the House","tr":"Ev temizliği","text":"On Saturday, we clean the house together. My father cleans the kitchen. My mother washes the clothes. Ayşe cleans the windows and Mert puts his toys in a box. I clean my room and the bathroom. It takes two hours. Then the house is clean and we drink tea.","words":["clean","toy","box","bathroom"],"ex":{"clean":"On Saturday, we clean the house together.","toy":"Ayşe cleans the windows and Mert puts his toys in a box.","box":"Ayşe cleans the windows and Mert puts his toys in a box.","bathroom":"I clean my room and the bathroom."},"fm":{"toy":"toys"}},{"id":29,"lv":"A1","n":30,"title":"A Film Night","tr":"Film gecesi","text":"On Friday evening, Can and Elif come to my house. Elif is in Ankara for the weekend. We watch a film together. It is a science fiction film about robots. We eat popcorn and drink juice. The film is long but very interesting. After the film, we talk about robots and engineering.","words":["weekend","science","fiction","about","robot","popcorn","juice","interesting"],"ex":{"weekend":"Elif is in Ankara for the weekend.","science":"It is a science fiction film about robots.","fiction":"It is a science fiction film about robots.","about":"It is a science fiction film about robots.","robot":"It is a science fiction film about robots.","popcorn":"We eat popcorn and drink juice.","juice":"We eat popcorn and drink juice.","interesting":"The film is long but very interesting."},"fm":{"robot":"robots"}},{"id":30,"lv":"A1","n":31,"title":"My Plans","tr":"Planlarım","text":"I have many plans. This summer, I want to learn English well. I am going to take a course. Next year, I want to find a summer job in a factory. In the future, I want to be a good engineer. I want to design machines and cars.","words":["plan","learn","english","going","course","find","factory","future","engineer","design"],"ex":{"plan":"I have many plans.","learn":"This summer, I want to learn English well.","english":"This summer, I want to learn English well.","going":"I am going to take a course.","course":"I am going to take a course.","find":"Next year, I want to find a summer job in a factory.","factory":"Next year, I want to find a summer job in a factory.","future":"In the future, I want to be a good engineer.","engineer":"In the future, I want to be a good engineer.","design":"I want to design machines and cars."},"fm":{"plan":"plans"}},{"id":31,"lv":"A1","n":32,"title":"The English Course","tr":"İngilizce kursu","text":"The English course is on Monday and Thursday evenings. There are twelve students in my class. Our teacher is Mr Brown. He is from London. He speaks a little Turkish. In class, we read, write, listen and speak. I like listening to songs in English. It helps me.","words":["speak","turkish","write","listen","song"],"ex":{"speak":"He speaks a little Turkish.","turkish":"He speaks a little Turkish.","write":"In class, we read, write, listen and speak.","listen":"In class, we read, write, listen and speak.","song":"I like listening to songs in English."},"fm":{"speak":"speaks","song":"songs"}},{"id":32,"lv":"A1","n":33,"title":"A Message to Elif","tr":"Elif'e bir mesaj","text":"Dear Elif, how are you? I am very busy these days. I have classes at university and an English course in the evening. English is difficult, but I like it. Mr Brown is a good teacher. Can says hello to you. Please write to me soon. Love, Deniz","words":["dear","please","soon"],"ex":{"dear":"Dear Elif, how are you?","please":"Please write to me soon.","soon":"Please write to me soon."},"fm":{}},{"id":33,"lv":"A1","n":34,"title":"Two Breakfasts","tr":"İki kahvaltı","text":"Mr Brown asks us about Turkish breakfast. I say: \"We eat bread, cheese, olives, tomatoes, cucumbers, eggs and honey. We drink black tea.\" Mr Brown laughs. \"In England, we eat eggs, sausages, beans and toast. We drink tea with milk.\" Tea with milk? That is strange for me!","words":["olive","cucumber","honey","laugh","sausage","bean","toast","milk","that","strange"],"ex":{"olive":"I say: \"We eat bread, cheese, olives, tomatoes, cucumbers, eggs and honey.","cucumber":"I say: \"We eat bread, cheese, olives, tomatoes, cucumbers, eggs and honey.","honey":"I say: \"We eat bread, cheese, olives, tomatoes, cucumbers, eggs and honey.","laugh":"Mr Brown laughs.","sausage":"\"In England, we eat eggs, sausages, beans and toast.","bean":"\"In England, we eat eggs, sausages, beans and toast.","toast":"\"In England, we eat eggs, sausages, beans and toast.","milk":"We drink tea with milk.\"","that":"That is strange for me!","strange":"That is strange for me!"},"fm":{"olive":"olives","cucumber":"cucumbers","laugh":"laughs","sausage":"sausages","bean":"beans"}},{"id":34,"lv":"A1","n":35,"title":"Can's Family","tr":"Can'ın ailesi","text":"On Sunday, I visit Can's family. They live in a flat in the city centre. Can's mother is a nurse and his father is a taxi driver. Can has a little brother, Emre. Emre is 6. He loves cars and trains. Can's mother makes delicious food for us. I eat a lot!","words":["flat","centre","nurse","driver","train","delicious"],"ex":{"flat":"They live in a flat in the city centre.","centre":"They live in a flat in the city centre.","nurse":"Can's mother is a nurse and his father is a taxi driver.","driver":"Can's mother is a nurse and his father is a taxi driver.","train":"He loves cars and trains.","delicious":"Can's mother makes delicious food for us."},"fm":{"train":"trains"}},{"id":35,"lv":"A1","n":36,"title":"A Trip to the Lake","tr":"Göle gezi","text":"In May, the weather is warm. Our class goes on a trip to a lake near Ankara. We go by bus. At the lake, we walk, take photos and have a picnic. Some students swim, but the water is cold. In the afternoon, we play volleyball. It is a beautiful day.","words":["may","trip","lake","picnic","afternoon","volleyball","beautiful"],"ex":{"may":"In May, the weather is warm.","trip":"Our class goes on a trip to a lake near Ankara.","lake":"Our class goes on a trip to a lake near Ankara.","picnic":"At the lake, we walk, take photos and have a picnic.","afternoon":"In the afternoon, we play volleyball.","volleyball":"In the afternoon, we play volleyball.","beautiful":"It is a beautiful day."},"fm":{}},{"id":36,"lv":"A1","n":37,"title":"My Dream Car","tr":"Hayalimdeki araba","text":"I love cars. My dream car is an electric car. It is fast, quiet and clean. It does not use petrol. It uses electricity. Its battery is very big. I want to design cars like this in the future. Can's dream car is old: a red Mustang from 1965!","words":["dream","electric","use","petrol","electricity","its","battery"],"ex":{"dream":"My dream car is an electric car.","electric":"My dream car is an electric car.","use":"It does not use petrol.","petrol":"It does not use petrol.","electricity":"It uses electricity.","its":"Its battery is very big.","battery":"Its battery is very big."},"fm":{}},{"id":37,"lv":"A1","n":38,"title":"The End of the Year","tr":"Yılın sonu","text":"It is June. The exams are finished. This year is difficult but good. I learn a lot. I have new friends, and my English is better now. Tomorrow, I go to my grandmother's village. I am going to stay there for two weeks. I want to rest, read and help on the farm.","words":["finish","better","tomorrow"],"ex":{"finish":"The exams are finished.","better":"I have new friends, and my English is better now.","tomorrow":"Tomorrow, I go to my grandmother's village."},"fm":{"finish":"finished"}},{"id":38,"lv":"A1","n":39,"title":"Summer in the Village","tr":"Köyde yaz","text":"The village is very quiet. I get up early with the chickens! Every morning, I drink milk from my grandmother's cows. I help her in the garden. We grow tomatoes, peppers and beans. In the evening, we sit outside and look at the stars. There are many stars here. It is not like the city.","words":["grow","pepper","outside","look","star"],"ex":{"grow":"We grow tomatoes, peppers and beans.","pepper":"We grow tomatoes, peppers and beans.","outside":"In the evening, we sit outside and look at the stars.","look":"In the evening, we sit outside and look at the stars.","star":"In the evening, we sit outside and look at the stars."},"fm":{"pepper":"peppers","star":"stars"}},{"id":39,"lv":"A1","n":40,"title":"A New Start","tr":"Yeni bir başlangıç","text":"My summer is over. I am back in Ankara. I am ready for a new year at university. Now I can talk about my family, my home, my day and my plans in English. I know many words. Next, I want to travel and use my English. Maybe I can go to London!","words":["over","word","travel","maybe"],"ex":{"over":"My summer is over.","word":"I know many words.","travel":"Next, I want to travel and use my English.","maybe":"Maybe I can go to London!"},"fm":{"word":"words"}},{"id":40,"lv":"A2","n":1,"title":"Big News","tr":"Büyük haber","text":"Last week, Mr Brown gave us some big news. There is a summer English course in London for students. It is four weeks long, and the university pays for half of the price. I was very excited. I talked to my parents in the evening. My father said: \"It is a great chance. You should go.\" I decided to apply.","words":["last","news","four","half","price","excited","parent","chance","should","decide","apply"],"ex":{"last":"Last week, Mr Brown gave us some big news.","news":"Last week, Mr Brown gave us some big news.","four":"It is four weeks long, and the university pays for half of the price.","half":"It is four weeks long, and the university pays for half of the price.","price":"It is four weeks long, and the university pays for half of the price.","excited":"I was very excited.","parent":"I talked to my parents in the evening.","chance":"My father said: \"It is a great chance.","should":"You should go.\"","decide":"I decided to apply.","apply":"I decided to apply."},"fm":{"parent":"parents","decide":"decided"}},{"id":41,"lv":"A2","n":2,"title":"The Application Form","tr":"Başvuru formu","text":"Yesterday I filled in the application form. It asked for my name, my address, my date of birth and my phone number. I also wrote a short letter. In the letter, I explained why I wanted to go to London. I wrote about my love for engineering and my dream of working abroad. Then I sent the form by email.","words":["yesterday","fill","application","form","address","date","birth","number","letter","explain","why","abroad","send","email"],"ex":{"yesterday":"Yesterday I filled in the application form.","fill":"Yesterday I filled in the application form.","application":"Yesterday I filled in the application form.","form":"Yesterday I filled in the application form.","address":"It asked for my name, my address, my date of birth and my phone number.","date":"It asked for my name, my address, my date of birth and my phone number.","birth":"It asked for my name, my address, my date of birth and my phone number.","number":"It asked for my name, my address, my date of birth and my phone number.","letter":"I also wrote a short letter.","explain":"In the letter, I explained why I wanted to go to London.","why":"In the letter, I explained why I wanted to go to London.","abroad":"I wrote about my love for engineering and my dream of working abroad.","send":"Then I sent the form by email.","email":"Then I sent the form by email."},"fm":{"fill":"filled","explain":"explained","send":"sent"}},{"id":42,"lv":"A2","n":3,"title":"Waiting","tr":"Bekleyiş","text":"For two weeks, I waited for an answer. Every morning I checked my email. Nothing! I started to worry. Can said: \"Do not worry. They received many forms, so they need time.\" He was right. On a Tuesday afternoon, an email arrived: \"Dear Deniz, we are happy to tell you that you have a place on the course.\" I shouted with joy.","words":["wait","check","nothing","worry","receive","so","right","arrive","tell","place","shout","joy"],"ex":{"wait":"For two weeks, I waited for an answer.","check":"Every morning I checked my email.","nothing":"Nothing!","worry":"I started to worry.","receive":"They received many forms, so they need time.\"","so":"They received many forms, so they need time.\"","right":"He was right.","arrive":"On a Tuesday afternoon, an email arrived: \"Dear Deniz, we are happy to tell you that you have a place on the course.\"","tell":"On a Tuesday afternoon, an email arrived: \"Dear Deniz, we are happy to tell you that you have a place on the course.\"","place":"On a Tuesday afternoon, an email arrived: \"Dear Deniz, we are happy to tell you that you have a place on the course.\"","shout":"I shouted with joy.","joy":"I shouted with joy."},"fm":{"wait":"waited","check":"checked","receive":"received","arrive":"arrived","shout":"shouted"}},{"id":43,"lv":"A2","n":4,"title":"Passport and Visa","tr":"Pasaport ve vize","text":"Before the trip, I needed a passport and a visa. First, I went to the passport office with my father. We waited in a long queue for an hour. Then I prepared the visa documents: a letter from the university, my bank information and a photo. It was a lot of paperwork, but finally everything was ready.","words":["before","passport","visa","queue","prepare","document","information","paperwork","finally","everything"],"ex":{"before":"Before the trip, I needed a passport and a visa.","passport":"Before the trip, I needed a passport and a visa.","visa":"Before the trip, I needed a passport and a visa.","queue":"We waited in a long queue for an hour.","prepare":"Then I prepared the visa documents: a letter from the university, my bank information and a photo.","document":"Then I prepared the visa documents: a letter from the university, my bank information and a photo.","information":"Then I prepared the visa documents: a letter from the university, my bank information and a photo.","paperwork":"It was a lot of paperwork, but finally everything was ready.","finally":"It was a lot of paperwork, but finally everything was ready.","everything":"It was a lot of paperwork, but finally everything was ready."},"fm":{"prepare":"prepared","document":"documents"}},{"id":44,"lv":"A2","n":5,"title":"Buying a Ticket","tr":"Bilet almak","text":"Next, I bought a plane ticket online. There were many flights from Ankara to London. Some flights were cheap, but they stopped in another city. I chose a direct flight. It was more expensive, but it was faster and easier. The flight was on the first of July, at 6:00 in the morning. I printed the ticket and put it in my bag.","words":["plane","ticket","online","flight","another","choose","direct","more","print"],"ex":{"plane":"Next, I bought a plane ticket online.","ticket":"Next, I bought a plane ticket online.","online":"Next, I bought a plane ticket online.","flight":"There were many flights from Ankara to London.","another":"Some flights were cheap, but they stopped in another city.","choose":"I chose a direct flight.","direct":"I chose a direct flight.","more":"It was more expensive, but it was faster and easier.","print":"I printed the ticket and put it in my bag."},"fm":{"flight":"flights","choose":"chose","print":"printed"}},{"id":45,"lv":"A2","n":6,"title":"Packing","tr":"Bavul hazırlamak","text":"The night before the trip, I packed my suitcase. My mother helped me. She said: \"London is often rainy, even in summer. Take a raincoat!\" I packed clothes for four weeks, a pair of comfortable shoes, my laptop, a dictionary and some Turkish tea for my host family. My suitcase was very heavy. I could not close it!","words":["night","pack","suitcase","rainy","even","raincoat","pair","comfortable","laptop","dictionary","host","heavy","could"],"ex":{"night":"The night before the trip, I packed my suitcase.","pack":"The night before the trip, I packed my suitcase.","suitcase":"The night before the trip, I packed my suitcase.","rainy":"She said: \"London is often rainy, even in summer.","even":"She said: \"London is often rainy, even in summer.","raincoat":"Take a raincoat!\"","pair":"I packed clothes for four weeks, a pair of comfortable shoes, my laptop, a dictionary and some Turkish tea for my host family.","comfortable":"I packed clothes for four weeks, a pair of comfortable shoes, my laptop, a dictionary and some Turkish tea for my host family.","laptop":"I packed clothes for four weeks, a pair of comfortable shoes, my laptop, a dictionary and some Turkish tea for my host family.","dictionary":"I packed clothes for four weeks, a pair of comfortable shoes, my laptop, a dictionary and some Turkish tea for my host family.","host":"I packed clothes for four weeks, a pair of comfortable shoes, my laptop, a dictionary and some Turkish tea for my host family.","heavy":"My suitcase was very heavy.","could":"I could not close it!"},"fm":{"pack":"packed"}},{"id":46,"lv":"A2","n":7,"title":"At the Airport","tr":"Havalimanında","text":"My family took me to the airport early in the morning. At the airport, I checked in and left my suitcase. Then I said goodbye to my family. My mother cried a little, and Ayşe hugged me. I walked through security and waited at the gate. I was nervous because it was my first flight.","words":["airport","goodbye","cry","hug","through","security","gate"],"ex":{"airport":"My family took me to the airport early in the morning.","goodbye":"Then I said goodbye to my family.","cry":"My mother cried a little, and Ayşe hugged me.","hug":"My mother cried a little, and Ayşe hugged me.","through":"I walked through security and waited at the gate.","security":"I walked through security and waited at the gate.","gate":"I walked through security and waited at the gate."},"fm":{"cry":"cried","hug":"hugged"}},{"id":47,"lv":"A2","n":8,"title":"The Flight","tr":"Uçuş","text":"The plane took off at 6:15. At first, I was afraid, but soon I relaxed. I sat next to the window. Below me, I saw clouds, mountains and the sea. The flight attendant brought breakfast and a cup of coffee. I watched a film and studied some English words. After four hours, the pilot said: \"We are landing in London.\"","words":["off","afraid","relax","below","cloud","mountain","attendant","bring","cup","pilot","landing"],"ex":{"off":"The plane took off at 6:15.","afraid":"At first, I was afraid, but soon I relaxed.","relax":"At first, I was afraid, but soon I relaxed.","below":"Below me, I saw clouds, mountains and the sea.","cloud":"Below me, I saw clouds, mountains and the sea.","mountain":"Below me, I saw clouds, mountains and the sea.","attendant":"The flight attendant brought breakfast and a cup of coffee.","bring":"The flight attendant brought breakfast and a cup of coffee.","cup":"The flight attendant brought breakfast and a cup of coffee.","pilot":"After four hours, the pilot said: \"We are landing in London.\"","landing":"After four hours, the pilot said: \"We are landing in London.\""},"fm":{"relax":"relaxed","cloud":"clouds","mountain":"mountains","bring":"brought"}},{"id":48,"lv":"A2","n":9,"title":"Arriving in London","tr":"Londra'ya varış","text":"At London Heathrow, I showed my passport and my visa. The officer asked: \"What is the reason for your visit?\" I answered: \"I am here for an English course.\" He smiled and said: \"Welcome to the United Kingdom.\" Then I took my suitcase and found the exit. It was grey and cloudy outside, just like my mother said.","words":["show","officer","reason","smile","welcome","united","kingdom","exit","grey","cloudy","just"],"ex":{"show":"At London Heathrow, I showed my passport and my visa.","officer":"The officer asked: \"What is the reason for your visit?\"","reason":"The officer asked: \"What is the reason for your visit?\"","smile":"He smiled and said: \"Welcome to the United Kingdom.\"","welcome":"He smiled and said: \"Welcome to the United Kingdom.\"","united":"He smiled and said: \"Welcome to the United Kingdom.\"","kingdom":"He smiled and said: \"Welcome to the United Kingdom.\"","exit":"Then I took my suitcase and found the exit.","grey":"It was grey and cloudy outside, just like my mother said.","cloudy":"It was grey and cloudy outside, just like my mother said.","just":"It was grey and cloudy outside, just like my mother said."},"fm":{"show":"showed","smile":"smiled"}},{"id":49,"lv":"A2","n":10,"title":"The Host Family","tr":"Ev sahibi aile","text":"I stayed with a host family, the Wilsons. Mrs Wilson met me at the station. She was a friendly woman of about fifty. She had two children: Lucy, who was twelve, and Jack, who was eight. Their house was in a quiet street with small gardens. My room was upstairs. It was simple but comfortable. I gave them the Turkish tea, and they loved it.","words":["station","woman","fifty","who","eight","their","upstairs","simple","them"],"ex":{"station":"Mrs Wilson met me at the station.","woman":"She was a friendly woman of about fifty.","fifty":"She was a friendly woman of about fifty.","who":"She had two children: Lucy, who was twelve, and Jack, who was eight.","eight":"She had two children: Lucy, who was twelve, and Jack, who was eight.","their":"Their house was in a quiet street with small gardens.","upstairs":"My room was upstairs.","simple":"It was simple but comfortable.","them":"I gave them the Turkish tea, and they loved it."},"fm":{}},{"id":50,"lv":"A2","n":11,"title":"The First Dinner","tr":"İlk akşam yemeği","text":"At seven o'clock, we had dinner together. Mrs Wilson cooked roast chicken with potatoes and carrots. Mr Wilson asked me many questions about Turkey. I tried to answer in English. Sometimes I did not know a word, so I used my hands. Everybody laughed, but it was a friendly laugh. After dinner, I was very tired, and I went to bed early.","words":["o'clock","roast","carrot","try","hand","everybody"],"ex":{"o'clock":"At seven o'clock, we had dinner together.","roast":"Mrs Wilson cooked roast chicken with potatoes and carrots.","carrot":"Mrs Wilson cooked roast chicken with potatoes and carrots.","try":"I tried to answer in English.","hand":"Sometimes I did not know a word, so I used my hands.","everybody":"Everybody laughed, but it was a friendly laugh."},"fm":{"carrot":"carrots","try":"tried","hand":"hands"}},{"id":51,"lv":"A2","n":12,"title":"The First Day of the Course","tr":"Kursun ilk günü","text":"The next morning, I took the underground to the language school. The school was in the centre of London, near a big park. There were students from many countries in my class. The teacher, Sarah, asked us to introduce ourselves. I was shy, but I said: \"My name is Deniz. I am an engineering student from Turkey.\"","words":["underground","language","country","introduce","ourselves","shy"],"ex":{"underground":"The next morning, I took the underground to the language school.","language":"The next morning, I took the underground to the language school.","country":"There were students from many countries in my class.","introduce":"The teacher, Sarah, asked us to introduce ourselves.","ourselves":"The teacher, Sarah, asked us to introduce ourselves.","shy":"I was shy, but I said: \"My name is Deniz."},"fm":{"country":"countries"}},{"id":52,"lv":"A2","n":13,"title":"My Classmates","tr":"Sınıf arkadaşlarım","text":"I made two good friends in the first week. Maria was from Spain. She studied architecture, and she loved old buildings. Kenji was from Japan. He was a computer science student, and he was very good at games. We always sat together in class. At lunchtime, we ate sandwiches in the park and practised English.","words":["architecture","game","lunchtime","sandwich","practise"],"ex":{"architecture":"She studied architecture, and she loved old buildings.","game":"He was a computer science student, and he was very good at games.","lunchtime":"At lunchtime, we ate sandwiches in the park and practised English.","sandwich":"At lunchtime, we ate sandwiches in the park and practised English.","practise":"At lunchtime, we ate sandwiches in the park and practised English."},"fm":{"game":"games","sandwich":"sandwiches","practise":"practised"}},{"id":53,"lv":"A2","n":14,"title":"On the Underground","tr":"Metroda","text":"The London underground is very old. It opened in 1863. People call it \"the Tube\". There are many lines, and each line has a different colour. On my first day, I took the wrong line and arrived late. After that, I used a map on my phone. I also bought a travel card. It was cheaper than buying a single ticket every day.","words":["open","people","tube","line","different","wrong","late","map","card","than","single"],"ex":{"open":"It opened in 1863.","people":"People call it \"the Tube\".","tube":"People call it \"the Tube\".","line":"There are many lines, and each line has a different colour.","different":"There are many lines, and each line has a different colour.","wrong":"On my first day, I took the wrong line and arrived late.","late":"On my first day, I took the wrong line and arrived late.","map":"After that, I used a map on my phone.","card":"I also bought a travel card.","than":"It was cheaper than buying a single ticket every day.","single":"It was cheaper than buying a single ticket every day."},"fm":{"open":"opened","line":"lines"}},{"id":54,"lv":"A2","n":15,"title":"A Museum Visit","tr":"Müze ziyareti","text":"On Saturday, Maria, Kenji and I visited the Science Museum. It was free! I saw old steam engines, the first cars and even real space rockets. I spent two hours in the engineering hall. Maria preferred the history section, and Kenji played with the computer games. In the museum shop, I bought a small model of a steam engine for my brother.","words":["free","steam","engine","real","space","rocket","hall","prefer","history","section","shop","model"],"ex":{"free":"It was free!","steam":"I saw old steam engines, the first cars and even real space rockets.","engine":"I saw old steam engines, the first cars and even real space rockets.","real":"I saw old steam engines, the first cars and even real space rockets.","space":"I saw old steam engines, the first cars and even real space rockets.","rocket":"I saw old steam engines, the first cars and even real space rockets.","hall":"I spent two hours in the engineering hall.","prefer":"Maria preferred the history section, and Kenji played with the computer games.","history":"Maria preferred the history section, and Kenji played with the computer games.","section":"Maria preferred the history section, and Kenji played with the computer games.","shop":"In the museum shop, I bought a small model of a steam engine for my brother.","model":"In the museum shop, I bought a small model of a steam engine for my brother."},"fm":{"engine":"engines","rocket":"rockets","prefer":"preferred"}},{"id":55,"lv":"A2","n":16,"title":"The Lost Umbrella","tr":"Şemsiye kayboldu","text":"On Monday, it rained all day. I left my umbrella on the bus, so I got very wet. When I arrived at school, my clothes and my hair were wet. Sarah gave me a towel and a hot drink. \"Welcome to London,\" she said, and she laughed. After class, I went to a shop and bought a new umbrella. This time, I was careful.","words":["wet","towel","careful"],"ex":{"wet":"I left my umbrella on the bus, so I got very wet.","towel":"Sarah gave me a towel and a hot drink.","careful":"This time, I was careful."},"fm":{}},{"id":56,"lv":"A2","n":17,"title":"British Food","tr":"İngiliz yemeği","text":"Many people say that British food is not good, but I did not agree. I tried fish and chips, and it was delicious. On Sunday, the Wilsons made a traditional roast dinner. I also liked the pies and the cakes. However, I did not enjoy one thing: beans on toast for breakfast! I missed Turkish breakfast with cheese, olives and fresh bread.","words":["british","agree","fish","chip","traditional","pie","however","enjoy","thing"],"ex":{"british":"Many people say that British food is not good, but I did not agree.","agree":"Many people say that British food is not good, but I did not agree.","fish":"I tried fish and chips, and it was delicious.","chip":"I tried fish and chips, and it was delicious.","traditional":"On Sunday, the Wilsons made a traditional roast dinner.","pie":"I also liked the pies and the cakes.","however":"However, I did not enjoy one thing: beans on toast for breakfast!","enjoy":"However, I did not enjoy one thing: beans on toast for breakfast!","thing":"However, I did not enjoy one thing: beans on toast for breakfast!"},"fm":{"chip":"chips","pie":"pies"}},{"id":57,"lv":"A2","n":18,"title":"Getting Lost","tr":"Kayboldum","text":"One evening, I wanted to walk home from the station. I thought I knew the way, but I turned into the wrong street. Soon all the streets looked the same. My phone battery was empty. I felt worried. Finally, I asked an old woman for help. She was very kind and walked with me to the end of the road. From there, I recognised our house.","words":["way","into","same","empty","worried","end","recognise"],"ex":{"way":"I thought I knew the way, but I turned into the wrong street.","into":"I thought I knew the way, but I turned into the wrong street.","same":"Soon all the streets looked the same.","empty":"My phone battery was empty.","worried":"I felt worried.","end":"She was very kind and walked with me to the end of the road.","recognise":"From there, I recognised our house."},"fm":{"recognise":"recognised"}},{"id":58,"lv":"A2","n":19,"title":"Shopping at the Market","tr":"Pazar alışverişi","text":"On Sunday, I went to a famous market in Camden with Maria. There were hundreds of small shops and food stalls. People sold clothes, old records, jewellery and art. I bought a T-shirt with a picture of the Tube map. Maria bought earrings for her sister. The prices were not low, but we enjoyed looking at everything.","words":["famous","hundred","stall","sell","record","jewellery","art","t-shirt","earring","low"],"ex":{"famous":"On Sunday, I went to a famous market in Camden with Maria.","hundred":"There were hundreds of small shops and food stalls.","stall":"There were hundreds of small shops and food stalls.","sell":"People sold clothes, old records, jewellery and art.","record":"People sold clothes, old records, jewellery and art.","jewellery":"People sold clothes, old records, jewellery and art.","art":"People sold clothes, old records, jewellery and art.","t-shirt":"I bought a T-shirt with a picture of the Tube map.","earring":"Maria bought earrings for her sister.","low":"The prices were not low, but we enjoyed looking at everything."},"fm":{"hundred":"hundreds","stall":"stalls","sell":"sold","record":"records","earring":"earrings"}},{"id":59,"lv":"A2","n":20,"title":"A Letter Home","tr":"Bir mektup","text":"Dear Mum and Dad, I am fine and happy. London is a big and exciting city. My English is getting better every day. The Wilsons are very nice to me. Yesterday I helped Mr Wilson in the garden, and Lucy taught me some English songs. I miss your cooking, though! Say hello to Ayşe and Mert. Love, Deniz","words":["mum","dad","exciting","teach","though"],"ex":{"mum":"Dear Mum and Dad, I am fine and happy.","dad":"Dear Mum and Dad, I am fine and happy.","exciting":"London is a big and exciting city.","teach":"Yesterday I helped Mr Wilson in the garden, and Lucy taught me some English songs.","though":"I miss your cooking, though!"},"fm":{"teach":"taught"}},{"id":60,"lv":"A2","n":21,"title":"A Football Match","tr":"Futbol maçı","text":"Mr Wilson was a big football fan. One evening, he took me and Jack to a football match. The stadium was huge, and it was full of people. Everybody sang and shouted. Our team lost the first half, but then they scored two goals. In the end, they won 2–1. Jack jumped up and down with joy. It was a fantastic night.","words":["fan","match","stadium","huge","full","team","lose","score","goal","win","jump","down","fantastic"],"ex":{"fan":"Mr Wilson was a big football fan.","match":"One evening, he took me and Jack to a football match.","stadium":"The stadium was huge, and it was full of people.","huge":"The stadium was huge, and it was full of people.","full":"The stadium was huge, and it was full of people.","team":"Our team lost the first half, but then they scored two goals.","lose":"Our team lost the first half, but then they scored two goals.","score":"Our team lost the first half, but then they scored two goals.","goal":"Our team lost the first half, but then they scored two goals.","win":"In the end, they won 2–1.","jump":"Jack jumped up and down with joy.","down":"Jack jumped up and down with joy.","fantastic":"It was a fantastic night."},"fm":{"lose":"lost","score":"scored","goal":"goals","win":"won","jump":"jumped"}},{"id":61,"lv":"A2","n":22,"title":"In the Library","tr":"Kütüphanede","text":"In the second week, we had a project. Each group had to give a presentation about a famous British engineer. My group chose Isambard Kingdom Brunel. We went to a big public library to do research. Brunel built bridges, tunnels and ships in the nineteenth century. I was surprised that one person did so many things. We worked hard on our presentation.","words":["project","group","presentation","public","research","build","bridge","tunnel","ship","nineteenth","century","surprised","person","hard"],"ex":{"project":"In the second week, we had a project.","group":"Each group had to give a presentation about a famous British engineer.","presentation":"Each group had to give a presentation about a famous British engineer.","public":"We went to a big public library to do research.","research":"We went to a big public library to do research.","build":"Brunel built bridges, tunnels and ships in the nineteenth century.","bridge":"Brunel built bridges, tunnels and ships in the nineteenth century.","tunnel":"Brunel built bridges, tunnels and ships in the nineteenth century.","ship":"Brunel built bridges, tunnels and ships in the nineteenth century.","nineteenth":"Brunel built bridges, tunnels and ships in the nineteenth century.","century":"Brunel built bridges, tunnels and ships in the nineteenth century.","surprised":"I was surprised that one person did so many things.","person":"I was surprised that one person did so many things.","hard":"We worked hard on our presentation."},"fm":{"build":"built","bridge":"bridges","tunnel":"tunnels","ship":"ships"}},{"id":62,"lv":"A2","n":23,"title":"The Presentation","tr":"Sunum","text":"On Friday, we gave our presentation. I spoke about Brunel's bridges, Maria spoke about his life, and Kenji showed the pictures. At the beginning, my hands were shaking, but then I felt more confident. When we finished, the other students clapped. Sarah said: \"Very good work, and your pronunciation is much clearer now.\" I was proud of our group.","words":["beginning","shake","confident","clap","pronunciation","clear","proud"],"ex":{"beginning":"At the beginning, my hands were shaking, but then I felt more confident.","shake":"At the beginning, my hands were shaking, but then I felt more confident.","confident":"At the beginning, my hands were shaking, but then I felt more confident.","clap":"When we finished, the other students clapped.","pronunciation":"Sarah said: \"Very good work, and your pronunciation is much clearer now.\"","clear":"Sarah said: \"Very good work, and your pronunciation is much clearer now.\"","proud":"I was proud of our group."},"fm":{"shake":"shaking","clap":"clapped","clear":"clearer"}},{"id":63,"lv":"A2","n":24,"title":"I Got Ill","tr":"Hasta oldum","text":"In the third week, I caught a cold. I had a sore throat and a high temperature. I stayed in bed for two days. Mrs Wilson was very kind. She made me soup and gave me some medicine. She also called the school to explain. Maria and Kenji sent me messages with the homework. On the third day, I felt much better.","words":["catch","sore","temperature","message","homework"],"ex":{"catch":"In the third week, I caught a cold.","sore":"I had a sore throat and a high temperature.","temperature":"I had a sore throat and a high temperature.","message":"Maria and Kenji sent me messages with the homework.","homework":"Maria and Kenji sent me messages with the homework."},"fm":{"catch":"caught","message":"messages"}},{"id":64,"lv":"A2","n":25,"title":"A Trip to Cambridge","tr":"Cambridge gezisi","text":"At the weekend, our school organised a trip to Cambridge. We travelled by train. It took about one hour. Cambridge is a small city with a very old university. We visited some of the colleges and walked along the river. Then we went punting. That means you sit in a flat boat and a person pushes it with a long stick. It was relaxing and fun.","words":["organise","college","along","river","punt","mean","boat","push","stick","relaxing","fun"],"ex":{"organise":"At the weekend, our school organised a trip to Cambridge.","college":"We visited some of the colleges and walked along the river.","along":"We visited some of the colleges and walked along the river.","river":"We visited some of the colleges and walked along the river.","punt":"Then we went punting.","mean":"That means you sit in a flat boat and a person pushes it with a long stick.","boat":"That means you sit in a flat boat and a person pushes it with a long stick.","push":"That means you sit in a flat boat and a person pushes it with a long stick.","stick":"That means you sit in a flat boat and a person pushes it with a long stick.","relaxing":"It was relaxing and fun.","fun":"It was relaxing and fun."},"fm":{"organise":"organised","college":"colleges","punt":"punting","mean":"means","push":"pushes"}},{"id":65,"lv":"A2","n":26,"title":"A Concert","tr":"Konser","text":"On Thursday evening, Kenji had two tickets for a concert in a park. A famous band was playing. We sat on the grass with thousands of other people. The music was loud and the lights were beautiful. I did not know the songs, but I danced anyway. We came home very late, so I tried to be quiet when I opened the door.","words":["concert","band","grass","thousand","loud","light","dance","anyway","door"],"ex":{"concert":"On Thursday evening, Kenji had two tickets for a concert in a park.","band":"A famous band was playing.","grass":"We sat on the grass with thousands of other people.","thousand":"We sat on the grass with thousands of other people.","loud":"The music was loud and the lights were beautiful.","light":"The music was loud and the lights were beautiful.","dance":"I did not know the songs, but I danced anyway.","anyway":"I did not know the songs, but I danced anyway.","door":"We came home very late, so I tried to be quiet when I opened the door."},"fm":{"thousand":"thousands","light":"lights","dance":"danced"}},{"id":66,"lv":"A2","n":27,"title":"My Wallet","tr":"Cüzdanım","text":"One morning, I could not find my wallet. I looked everywhere: in my room, in my bag and in my jacket. My bank card and some money were inside. I was very worried. I called my bank and stopped the card. Then I went to the police station. Two days later, a man found it on the bus and gave it to the police. Nothing was missing!","words":["wallet","everywhere","jacket","inside","police","missing"],"ex":{"wallet":"One morning, I could not find my wallet.","everywhere":"I looked everywhere: in my room, in my bag and in my jacket.","jacket":"I looked everywhere: in my room, in my bag and in my jacket.","inside":"My bank card and some money were inside.","police":"Then I went to the police station.","missing":"Nothing was missing!"},"fm":{}},{"id":67,"lv":"A2","n":28,"title":"Comparing Countries","tr":"Ülkeleri karşılaştırmak","text":"In class, we compared our countries. Maria said that Spain is sunnier and warmer than Britain. Kenji said that Tokyo is bigger than London, and the trains are faster. I said that Turkish people are very hospitable and that our food is the best in the world. Everybody laughed. We agreed that every country has good and bad sides.","words":["compare","hospitable","world","side"],"ex":{"compare":"In class, we compared our countries.","hospitable":"I said that Turkish people are very hospitable and that our food is the best in the world.","world":"I said that Turkish people are very hospitable and that our food is the best in the world.","side":"We agreed that every country has good and bad sides."},"fm":{"compare":"compared","side":"sides"}},{"id":68,"lv":"A2","n":29,"title":"Future Plans","tr":"Gelecek planları","text":"One evening, Maria, Kenji and I talked about our future. Maria wants to design museums. Kenji hopes to work for a game company in Tokyo. I said that I want to work on electric cars, maybe in another country first and then in Turkey. We promised to visit each other one day. I hope we keep our promise.","words":["hope","company","promise","keep"],"ex":{"hope":"Kenji hopes to work for a game company in Tokyo.","company":"Kenji hopes to work for a game company in Tokyo.","promise":"We promised to visit each other one day.","keep":"I hope we keep our promise."},"fm":{"hope":"hopes","promise":"promised"}},{"id":69,"lv":"A2","n":30,"title":"My English Is Improving","tr":"İngilizcem gelişiyor","text":"I noticed that my English was improving. In the first week, I needed to think for a long time before I spoke. Now, I can understand most conversations, and I can answer quickly. I still make mistakes, especially with grammar, but I am not afraid any more. Sarah says that the best way to learn is to use the language every day.","words":["notice","improve","most","conversation","quickly","still","mistake","especially","grammar","any"],"ex":{"notice":"I noticed that my English was improving.","improve":"I noticed that my English was improving.","most":"Now, I can understand most conversations, and I can answer quickly.","conversation":"Now, I can understand most conversations, and I can answer quickly.","quickly":"Now, I can understand most conversations, and I can answer quickly.","still":"I still make mistakes, especially with grammar, but I am not afraid any more.","mistake":"I still make mistakes, especially with grammar, but I am not afraid any more.","especially":"I still make mistakes, especially with grammar, but I am not afraid any more.","grammar":"I still make mistakes, especially with grammar, but I am not afraid any more.","any":"I still make mistakes, especially with grammar, but I am not afraid any more."},"fm":{"notice":"noticed","improve":"improving","conversation":"conversations","mistake":"mistakes"}},{"id":70,"lv":"A2","n":31,"title":"A Job Interview","tr":"Bir iş görüşmesi","text":"On the last Friday, Sarah organised a practice job interview. I had to apply for a job in an engineering company. I wore a shirt and a tie. The \"manager\" asked: \"What are your strengths?\" I said that I am hardworking and that I like solving problems. It was only practice, but I learned useful phrases for my future.","words":["practice","interview","tie","manager","strength","hardworking","only","useful","phrase"],"ex":{"practice":"On the last Friday, Sarah organised a practice job interview.","interview":"On the last Friday, Sarah organised a practice job interview.","tie":"I wore a shirt and a tie.","manager":"The \"manager\" asked: \"What are your strengths?\"","strength":"The \"manager\" asked: \"What are your strengths?\"","hardworking":"I said that I am hardworking and that I like solving problems.","only":"It was only practice, but I learned useful phrases for my future.","useful":"It was only practice, but I learned useful phrases for my future.","phrase":"It was only practice, but I learned useful phrases for my future."},"fm":{"strength":"strengths","phrase":"phrases"}},{"id":71,"lv":"A2","n":32,"title":"The Goodbye Party","tr":"Veda partisi","text":"On our last day, the school had a goodbye party. Every student brought food from their country. I made a big tray of börek. Maria brought tortilla, and Kenji made sushi. We ate, danced and took many photos. Sarah gave us our certificates. I felt happy and sad at the same time. I did not want to leave.","words":["tray","börek","tortilla","sushi","certificate","sad","leave"],"ex":{"tray":"I made a big tray of börek.","börek":"I made a big tray of börek.","tortilla":"Maria brought tortilla, and Kenji made sushi.","sushi":"Maria brought tortilla, and Kenji made sushi.","certificate":"Sarah gave us our certificates.","sad":"I felt happy and sad at the same time.","leave":"I did not want to leave."},"fm":{"certificate":"certificates"}},{"id":72,"lv":"A2","n":33,"title":"A Gift for the Wilsons","tr":"Wilsonlara hediye","text":"Before I left, I wanted to thank the Wilsons. I bought flowers for Mrs Wilson and a book about Istanbul for Mr Wilson. I gave Lucy and Jack Turkish delight. Mrs Wilson hugged me and said: \"You are part of our family now. Please come back.\" Jack asked if he could visit me in Ankara. I said: \"Of course!\"","words":["flower","delight","part","if"],"ex":{"flower":"I bought flowers for Mrs Wilson and a book about Istanbul for Mr Wilson.","delight":"I gave Lucy and Jack Turkish delight.","part":"Mrs Wilson hugged me and said: \"You are part of our family now.","if":"Jack asked if he could visit me in Ankara."},"fm":{"flower":"flowers"}},{"id":73,"lv":"A2","n":34,"title":"Coming Home","tr":"Eve dönüş","text":"The flight home was quiet. I looked out of the window and remembered everything: the Tube, the rain, the museum, my friends. When I arrived in Ankara, my whole family was waiting for me. Mert ran to me, and I gave him the model steam engine. That night, my mother cooked my favourite dishes. It was good to be home.","words":["remember","whole","him","dish"],"ex":{"remember":"I looked out of the window and remembered everything: the Tube, the rain, the museum, my friends.","whole":"When I arrived in Ankara, my whole family was waiting for me.","him":"Mert ran to me, and I gave him the model steam engine.","dish":"That night, my mother cooked my favourite dishes."},"fm":{"remember":"remembered","dish":"dishes"}},{"id":74,"lv":"A2","n":35,"title":"So Much to Tell","tr":"Anlatacak çok şey","text":"For days, I told everyone about London. I showed my photos to Can. He was a little jealous. \"Next summer, I want to go too,\" he said. I told him about the language school and the course prices. I also gave him a tip: \"Speak English all the time, even with other foreign students. That is the secret.\"","words":["jealous","tip","foreign","secret"],"ex":{"jealous":"He was a little jealous.","tip":"I also gave him a tip: \"Speak English all the time, even with other foreign students.","foreign":"I also gave him a tip: \"Speak English all the time, even with other foreign students.","secret":"That is the secret.\""},"fm":{}},{"id":75,"lv":"A2","n":36,"title":"The Second Year Begins","tr":"İkinci yıl başlıyor","text":"In September, my second year at university started. This year, the classes were more difficult: mechanics, materials and computer programming. But I felt more confident. My English helped me a lot, because many of our books are in English. Now I can read technical texts without a dictionary, or almost without one.","words":["mechanics","material","programming","technical","text","without","or","almost"],"ex":{"mechanics":"This year, the classes were more difficult: mechanics, materials and computer programming.","material":"This year, the classes were more difficult: mechanics, materials and computer programming.","programming":"This year, the classes were more difficult: mechanics, materials and computer programming.","technical":"Now I can read technical texts without a dictionary, or almost without one.","text":"Now I can read technical texts without a dictionary, or almost without one.","without":"Now I can read technical texts without a dictionary, or almost without one.","or":"Now I can read technical texts without a dictionary, or almost without one.","almost":"Now I can read technical texts without a dictionary, or almost without one."},"fm":{"material":"materials","text":"texts"}},{"id":76,"lv":"A2","n":37,"title":"Joining a Club","tr":"Bir kulübe katılmak","text":"I joined the university robotics club. The club meets every Wednesday in a small workshop. We build simple robots and take part in competitions. The members are friendly, and some of them are in their final year. They know a lot. In my first meeting, I learned how to use a soldering iron. I burned my finger, but only a little!","words":["join","robotics","club","workshop","competition","member","final","meeting","solder","iron","burn","finger"],"ex":{"join":"I joined the university robotics club.","robotics":"I joined the university robotics club.","club":"I joined the university robotics club.","workshop":"The club meets every Wednesday in a small workshop.","competition":"We build simple robots and take part in competitions.","member":"The members are friendly, and some of them are in their final year.","final":"The members are friendly, and some of them are in their final year.","meeting":"In my first meeting, I learned how to use a soldering iron.","solder":"In my first meeting, I learned how to use a soldering iron.","iron":"In my first meeting, I learned how to use a soldering iron.","burn":"I burned my finger, but only a little!","finger":"I burned my finger, but only a little!"},"fm":{"join":"joined","competition":"competitions","member":"members","solder":"soldering","burn":"burned"}},{"id":77,"lv":"A2","n":38,"title":"My First Robot","tr":"İlk robotum","text":"With two other members, I built my first robot. It was a small car that could follow a black line on the floor. We used two motors, a battery, some sensors and a cheap computer board. At first, the robot went in circles. We changed the program many times. Finally, it followed the line perfectly. We were delighted.","words":["follow","floor","motor","sensor","board","circle","change","program","perfectly","delighted"],"ex":{"follow":"It was a small car that could follow a black line on the floor.","floor":"It was a small car that could follow a black line on the floor.","motor":"We used two motors, a battery, some sensors and a cheap computer board.","sensor":"We used two motors, a battery, some sensors and a cheap computer board.","board":"We used two motors, a battery, some sensors and a cheap computer board.","circle":"At first, the robot went in circles.","change":"We changed the program many times.","program":"We changed the program many times.","perfectly":"Finally, it followed the line perfectly.","delighted":"We were delighted."},"fm":{"motor":"motors","sensor":"sensors","circle":"circles","change":"changed"}},{"id":78,"lv":"A2","n":39,"title":"Emails to Friends","tr":"Arkadaşlara e-posta","text":"I often write emails to Maria and Kenji. Maria started a new project about old bridges in Seville. Kenji got a summer job at a game company, and he loved it. I told them about the robotics club and my robot. Writing to them helps me practise my English, and it keeps our friendship alive even though we are far away.","words":["friendship","alive","away"],"ex":{"friendship":"Writing to them helps me practise my English, and it keeps our friendship alive even though we are far away.","alive":"Writing to them helps me practise my English, and it keeps our friendship alive even though we are far away.","away":"Writing to them helps me practise my English, and it keeps our friendship alive even though we are far away."},"fm":{}},{"id":79,"lv":"A2","n":40,"title":"One Year Later","tr":"Bir yıl sonra","text":"A year ago, I could only say simple sentences in English. Now, I can travel alone, make friends, give a presentation and write emails. I know that I still have a lot to learn. Next, I want to use English in my studies and in my future job. My new goal is clear: an internship in an international engineering company.","words":["ago","sentence","alone","internship","international"],"ex":{"ago":"A year ago, I could only say simple sentences in English.","sentence":"A year ago, I could only say simple sentences in English.","alone":"Now, I can travel alone, make friends, give a presentation and write emails.","internship":"My new goal is clear: an internship in an international engineering company.","international":"My new goal is clear: an internship in an international engineering company."},"fm":{"sentence":"sentences"}},{"id":80,"lv":"B1","n":1,"title":"Looking for an Internship","tr":"Staj aramak","text":"In my third year, I started looking for an internship. Our department told us that a summer internship is compulsory for engineering students. However, finding a good one is not easy, because many students apply for the same positions. I made a list of companies that work on electric vehicles. Then I visited their websites and read about their projects. Most of them asked for a CV and a cover letter in English.","words":["department","compulsory","finding","position","list","vehicle","website","cv","cover"],"ex":{"department":"Our department told us that a summer internship is compulsory for engineering students.","compulsory":"Our department told us that a summer internship is compulsory for engineering students.","finding":"However, finding a good one is not easy, because many students apply for the same positions.","position":"However, finding a good one is not easy, because many students apply for the same positions.","list":"I made a list of companies that work on electric vehicles.","vehicle":"I made a list of companies that work on electric vehicles.","website":"Then I visited their websites and read about their projects.","cv":"Most of them asked for a CV and a cover letter in English.","cover":"Most of them asked for a CV and a cover letter in English."},"fm":{"position":"positions","vehicle":"vehicles","website":"websites"}},{"id":81,"lv":"B1","n":2,"title":"Writing a CV","tr":"Özgeçmiş yazmak","text":"Writing my CV took longer than I expected. I had to describe my education, my skills and my experience in a clear and short way. I did not have much work experience, so I wrote about the robotics club, the London course and my job teaching maths to children. My English teacher, Mr Brown, checked my CV and corrected a few mistakes. He also advised me to use active verbs like \"designed\", \"built\" and \"organised\".","words":["expect","describe","education","skill","experience","maths","correct","few","advise","active","verb"],"ex":{"expect":"Writing my CV took longer than I expected.","describe":"I had to describe my education, my skills and my experience in a clear and short way.","education":"I had to describe my education, my skills and my experience in a clear and short way.","skill":"I had to describe my education, my skills and my experience in a clear and short way.","experience":"I had to describe my education, my skills and my experience in a clear and short way.","maths":"I did not have much work experience, so I wrote about the robotics club, the London course and my job teaching maths to children.","correct":"My English teacher, Mr Brown, checked my CV and corrected a few mistakes.","few":"My English teacher, Mr Brown, checked my CV and corrected a few mistakes.","advise":"He also advised me to use active verbs like \"designed\", \"built\" and \"organised\".","active":"He also advised me to use active verbs like \"designed\", \"built\" and \"organised\".","verb":"He also advised me to use active verbs like \"designed\", \"built\" and \"organised\"."},"fm":{"expect":"expected","skill":"skills","correct":"corrected","advise":"advised","verb":"verbs"}},{"id":82,"lv":"B1","n":3,"title":"The Cover Letter","tr":"Ön yazı","text":"The cover letter was even harder. In the letter, I needed to explain why I was interested in the company and why I was a suitable candidate. I wrote three drafts. In the first draft, I talked too much about myself. In the second, my sentences were too long and complicated. Finally, I found the right balance. I sent applications to eight companies and hoped for the best.","words":["interested","suitable","candidate","draft","myself","complicated","balance"],"ex":{"interested":"In the letter, I needed to explain why I was interested in the company and why I was a suitable candidate.","suitable":"In the letter, I needed to explain why I was interested in the company and why I was a suitable candidate.","candidate":"In the letter, I needed to explain why I was interested in the company and why I was a suitable candidate.","draft":"I wrote three drafts.","myself":"In the first draft, I talked too much about myself.","complicated":"In the second, my sentences were too long and complicated.","balance":"Finally, I found the right balance."},"fm":{"draft":"drafts"}},{"id":83,"lv":"B1","n":4,"title":"Replies","tr":"Cevaplar","text":"Over the next month, I received several replies. Three companies said that they had already found interns. Two did not reply at all, which was disappointing. But one company, a manufacturer of electric buses near Bursa, invited me to an online interview. I was both excited and anxious. I knew that this was a real opportunity, so I began to prepare seriously.","words":["several","reply","already","intern","which","disappointing","manufacturer","invite","both","anxious","opportunity","begin","seriously"],"ex":{"several":"Over the next month, I received several replies.","reply":"Over the next month, I received several replies.","already":"Three companies said that they had already found interns.","intern":"Three companies said that they had already found interns.","which":"Two did not reply at all, which was disappointing.","disappointing":"Two did not reply at all, which was disappointing.","manufacturer":"But one company, a manufacturer of electric buses near Bursa, invited me to an online interview.","invite":"But one company, a manufacturer of electric buses near Bursa, invited me to an online interview.","both":"I was both excited and anxious.","anxious":"I was both excited and anxious.","opportunity":"I knew that this was a real opportunity, so I began to prepare seriously.","begin":"I knew that this was a real opportunity, so I began to prepare seriously.","seriously":"I knew that this was a real opportunity, so I began to prepare seriously."},"fm":{"reply":"replies","intern":"interns","invite":"invited","begin":"began"}},{"id":84,"lv":"B1","n":5,"title":"Preparing for the Interview","tr":"Mülakata hazırlık","text":"To prepare, I researched the company carefully. I learned that it was founded in 2010 and that it now exports buses to more than twenty countries. I also practised common interview questions with Can. He pretended to be a strict manager and asked me difficult questions. At first, my answers were too short. Can suggested that I give examples from my own experience to support what I said.","words":["carefully","founded","export","twenty","common","pretend","strict","suggest","example","own","support"],"ex":{"carefully":"To prepare, I researched the company carefully.","founded":"I learned that it was founded in 2010 and that it now exports buses to more than twenty countries.","export":"I learned that it was founded in 2010 and that it now exports buses to more than twenty countries.","twenty":"I learned that it was founded in 2010 and that it now exports buses to more than twenty countries.","common":"I also practised common interview questions with Can.","pretend":"He pretended to be a strict manager and asked me difficult questions.","strict":"He pretended to be a strict manager and asked me difficult questions.","suggest":"Can suggested that I give examples from my own experience to support what I said.","example":"Can suggested that I give examples from my own experience to support what I said.","own":"Can suggested that I give examples from my own experience to support what I said.","support":"Can suggested that I give examples from my own experience to support what I said."},"fm":{"export":"exports","pretend":"pretended","suggest":"suggested","example":"examples"}},{"id":85,"lv":"B1","n":6,"title":"The Online Interview","tr":"Çevrim içi mülakat","text":"The interview took place on a Thursday morning. Two engineers from the company joined the video call. One of them asked about my robotics project, and I described how we solved the problem with the line-following car. The other engineer asked a technical question about batteries. I did not know the full answer, so I explained what I knew and said that I was eager to learn more. They seemed satisfied with my honesty.","words":["video","eager","seem","satisfied","honesty"],"ex":{"video":"Two engineers from the company joined the video call.","eager":"I did not know the full answer, so I explained what I knew and said that I was eager to learn more.","seem":"They seemed satisfied with my honesty.","satisfied":"They seemed satisfied with my honesty.","honesty":"They seemed satisfied with my honesty."},"fm":{"seem":"seemed"}},{"id":86,"lv":"B1","n":7,"title":"I Got the Internship","tr":"Kabul edildim","text":"A week later, I received an email from the human resources department. They offered me a six-week internship in their engineering department, starting in July. I read the email three times to make sure it was true. Then I called my parents. My father was especially pleased, because he had always encouraged me to follow my interest in vehicles. That evening, my family celebrated with a special dinner.","words":["human","resource","offer","six","sure","true","pleased","encourage","interest","special"],"ex":{"human":"A week later, I received an email from the human resources department.","resource":"A week later, I received an email from the human resources department.","offer":"They offered me a six-week internship in their engineering department, starting in July.","six":"They offered me a six-week internship in their engineering department, starting in July.","sure":"I read the email three times to make sure it was true.","true":"I read the email three times to make sure it was true.","pleased":"My father was especially pleased, because he had always encouraged me to follow my interest in vehicles.","encourage":"My father was especially pleased, because he had always encouraged me to follow my interest in vehicles.","interest":"My father was especially pleased, because he had always encouraged me to follow my interest in vehicles.","special":"That evening, my family celebrated with a special dinner."},"fm":{"resource":"resources","offer":"offered","encourage":"encouraged"}},{"id":87,"lv":"B1","n":8,"title":"The Robot Competition","tr":"Robot yarışması","text":"Before the summer, our robotics club took part in a national competition in Istanbul. Teams had to build a robot that could find a path through a maze. We worked late every night for a month. On the day of the competition, our robot got stuck twice, but it still finished the maze. We came fifth out of thirty teams. It was not a prize, but we were proud, and we learned a great deal about teamwork.","words":["national","path","maze","fifth","thirty","prize","deal","teamwork"],"ex":{"national":"Before the summer, our robotics club took part in a national competition in Istanbul.","path":"Teams had to build a robot that could find a path through a maze.","maze":"Teams had to build a robot that could find a path through a maze.","fifth":"We came fifth out of thirty teams.","thirty":"We came fifth out of thirty teams.","prize":"It was not a prize, but we were proud, and we learned a great deal about teamwork.","deal":"It was not a prize, but we were proud, and we learned a great deal about teamwork.","teamwork":"It was not a prize, but we were proud, and we learned a great deal about teamwork."},"fm":{}},{"id":88,"lv":"B1","n":9,"title":"Moving to Bursa","tr":"Bursa'ya taşınmak","text":"At the beginning of July, I moved to Bursa for the internship. The company had arranged a room for me in a shared flat with two other interns. One was studying electrical engineering in Izmir, and the other was a software student from Eskişehir. The flat was simple, but it was close to the factory. On the first evening, we cooked together and talked about our expectations. We were all a bit nervous.","words":["move","arrange","share","electrical","software","expectation","bit"],"ex":{"move":"At the beginning of July, I moved to Bursa for the internship.","arrange":"The company had arranged a room for me in a shared flat with two other interns.","share":"The company had arranged a room for me in a shared flat with two other interns.","electrical":"One was studying electrical engineering in Izmir, and the other was a software student from Eskişehir.","software":"One was studying electrical engineering in Izmir, and the other was a software student from Eskişehir.","expectation":"On the first evening, we cooked together and talked about our expectations.","bit":"We were all a bit nervous."},"fm":{"move":"moved","arrange":"arranged","share":"shared","expectation":"expectations"}},{"id":89,"lv":"B1","n":10,"title":"The First Day at Work","tr":"İlk iş günü","text":"On my first day, a manager gave us a tour of the factory. It was enormous. There were separate areas for the bodies of the buses, the electrical systems and the final assembly. Everybody had to wear safety shoes, glasses and a helmet. After the tour, I met my supervisor, Selin. She was a senior engineer in the battery team. She explained that I would help with testing battery packs.","words":["tour","enormous","separate","area","body","system","assembly","safety","glass","helmet","supervisor","senior","would","test"],"ex":{"tour":"On my first day, a manager gave us a tour of the factory.","enormous":"It was enormous.","separate":"There were separate areas for the bodies of the buses, the electrical systems and the final assembly.","area":"There were separate areas for the bodies of the buses, the electrical systems and the final assembly.","body":"There were separate areas for the bodies of the buses, the electrical systems and the final assembly.","system":"There were separate areas for the bodies of the buses, the electrical systems and the final assembly.","assembly":"There were separate areas for the bodies of the buses, the electrical systems and the final assembly.","safety":"Everybody had to wear safety shoes, glasses and a helmet.","glass":"Everybody had to wear safety shoes, glasses and a helmet.","helmet":"Everybody had to wear safety shoes, glasses and a helmet.","supervisor":"After the tour, I met my supervisor, Selin.","senior":"She was a senior engineer in the battery team.","would":"She explained that I would help with testing battery packs.","test":"She explained that I would help with testing battery packs."},"fm":{"area":"areas","body":"bodies","system":"systems","glass":"glasses","test":"testing"}},{"id":90,"lv":"B1","n":11,"title":"Safety First","tr":"İş güvenliği","text":"Before we could work in the factory, all the interns had to attend a safety training course. The instructor explained that batteries can be dangerous if they are damaged or overheated. We learned what to do in case of a fire and where the emergency exits were. He also showed us the correct way to lift heavy objects. I realised that safety is not just a rule; it is part of good engineering.","words":["attend","training","instructor","dangerous","damage","overheat","case","fire","emergency","lift","object","realise","rule"],"ex":{"attend":"Before we could work in the factory, all the interns had to attend a safety training course.","training":"Before we could work in the factory, all the interns had to attend a safety training course.","instructor":"The instructor explained that batteries can be dangerous if they are damaged or overheated.","dangerous":"The instructor explained that batteries can be dangerous if they are damaged or overheated.","damage":"The instructor explained that batteries can be dangerous if they are damaged or overheated.","overheat":"The instructor explained that batteries can be dangerous if they are damaged or overheated.","case":"We learned what to do in case of a fire and where the emergency exits were.","fire":"We learned what to do in case of a fire and where the emergency exits were.","emergency":"We learned what to do in case of a fire and where the emergency exits were.","lift":"He also showed us the correct way to lift heavy objects.","object":"He also showed us the correct way to lift heavy objects.","realise":"I realised that safety is not just a rule; it is part of good engineering.","rule":"I realised that safety is not just a rule; it is part of good engineering."},"fm":{"damage":"damaged","overheat":"overheated","object":"objects","realise":"realised"}},{"id":91,"lv":"B1","n":12,"title":"Testing Batteries","tr":"Pil testleri","text":"My main task was to help test battery modules. Each module contains many small cells. We charged and discharged the modules many times and measured their temperature, voltage and capacity. The data went to a computer, and I had to check it for errors. At first, the numbers did not mean much to me. Selin patiently explained how to read the graphs and what a normal result looks like.","words":["main","task","module","contain","cell","charge","discharge","measure","voltage","capacity","data","error","patiently","graph","normal"],"ex":{"main":"My main task was to help test battery modules.","task":"My main task was to help test battery modules.","module":"My main task was to help test battery modules.","contain":"Each module contains many small cells.","cell":"Each module contains many small cells.","charge":"We charged and discharged the modules many times and measured their temperature, voltage and capacity.","discharge":"We charged and discharged the modules many times and measured their temperature, voltage and capacity.","measure":"We charged and discharged the modules many times and measured their temperature, voltage and capacity.","voltage":"We charged and discharged the modules many times and measured their temperature, voltage and capacity.","capacity":"We charged and discharged the modules many times and measured their temperature, voltage and capacity.","data":"The data went to a computer, and I had to check it for errors.","error":"The data went to a computer, and I had to check it for errors.","patiently":"Selin patiently explained how to read the graphs and what a normal result looks like.","graph":"Selin patiently explained how to read the graphs and what a normal result looks like.","normal":"Selin patiently explained how to read the graphs and what a normal result looks like."},"fm":{"module":"modules","contain":"contains","cell":"cells","charge":"charged","discharge":"discharged","measure":"measured","error":"errors","graph":"graphs"}},{"id":92,"lv":"B1","n":13,"title":"A Mistake","tr":"Bir hata","text":"In my second week, I made a mistake. I entered the wrong settings for a test, and the machine stopped after two hours. We lost a whole day of data. I felt terrible and expected Selin to be angry. Instead, she calmly asked me to explain what happened. Then she said: \"Everyone makes mistakes. The important thing is to understand why it happened and to prevent it next time.\" We wrote a short checklist together.","words":["enter","setting","terrible","angry","instead","calmly","happen","prevent","checklist"],"ex":{"enter":"I entered the wrong settings for a test, and the machine stopped after two hours.","setting":"I entered the wrong settings for a test, and the machine stopped after two hours.","terrible":"I felt terrible and expected Selin to be angry.","angry":"I felt terrible and expected Selin to be angry.","instead":"Instead, she calmly asked me to explain what happened.","calmly":"Instead, she calmly asked me to explain what happened.","happen":"Instead, she calmly asked me to explain what happened.","prevent":"The important thing is to understand why it happened and to prevent it next time.\"","checklist":"We wrote a short checklist together."},"fm":{"enter":"entered","setting":"settings","happen":"happened"}},{"id":93,"lv":"B1","n":14,"title":"The Checklist","tr":"Kontrol listesi","text":"The checklist turned out to be very useful. It included every step of the test, from checking the cables to saving the results. Other engineers in the team started using it as well. Selin even suggested that I present it at the weekly team meeting. Speaking in front of experienced engineers made me nervous, but they asked helpful questions and gave me positive feedback. My mistake had become something useful.","words":["include","step","cable","as","weekly","front","experienced","helpful","positive","feedback","become"],"ex":{"include":"It included every step of the test, from checking the cables to saving the results.","step":"It included every step of the test, from checking the cables to saving the results.","cable":"It included every step of the test, from checking the cables to saving the results.","as":"Other engineers in the team started using it as well.","weekly":"Selin even suggested that I present it at the weekly team meeting.","front":"Speaking in front of experienced engineers made me nervous, but they asked helpful questions and gave me positive feedback.","experienced":"Speaking in front of experienced engineers made me nervous, but they asked helpful questions and gave me positive feedback.","helpful":"Speaking in front of experienced engineers made me nervous, but they asked helpful questions and gave me positive feedback.","positive":"Speaking in front of experienced engineers made me nervous, but they asked helpful questions and gave me positive feedback.","feedback":"Speaking in front of experienced engineers made me nervous, but they asked helpful questions and gave me positive feedback.","become":"My mistake had become something useful."},"fm":{"include":"included","cable":"cables"}},{"id":94,"lv":"B1","n":15,"title":"The Weekly Meeting","tr":"Haftalık toplantı","text":"Every Monday morning, the battery team had a meeting. Each engineer reported on their progress and any problems. The meetings were in Turkish, but many technical words were in English, such as \"thermal management\" and \"state of charge\". I took notes and looked up new terms in the evening. I noticed that good engineers communicate clearly. They describe a problem briefly, explain the possible causes and suggest a solution.","words":["report","progress","such","thermal","management","state","term","communicate","clearly","briefly","possible","cause","solution"],"ex":{"report":"Each engineer reported on their progress and any problems.","progress":"Each engineer reported on their progress and any problems.","such":"The meetings were in Turkish, but many technical words were in English, such as \"thermal management\" and \"state of charge\".","thermal":"The meetings were in Turkish, but many technical words were in English, such as \"thermal management\" and \"state of charge\".","management":"The meetings were in Turkish, but many technical words were in English, such as \"thermal management\" and \"state of charge\".","state":"The meetings were in Turkish, but many technical words were in English, such as \"thermal management\" and \"state of charge\".","term":"I took notes and looked up new terms in the evening.","communicate":"I noticed that good engineers communicate clearly.","clearly":"I noticed that good engineers communicate clearly.","briefly":"They describe a problem briefly, explain the possible causes and suggest a solution.","possible":"They describe a problem briefly, explain the possible causes and suggest a solution.","cause":"They describe a problem briefly, explain the possible causes and suggest a solution.","solution":"They describe a problem briefly, explain the possible causes and suggest a solution."},"fm":{"report":"reported","term":"terms","cause":"causes"}},{"id":95,"lv":"B1","n":16,"title":"Lunch Break Conversations","tr":"Öğle arası sohbetleri","text":"I enjoyed lunch breaks in the company canteen. Engineers from different departments sat together and discussed everything from football to the future of transport. One designer told me that the company was developing a smaller bus for narrow city streets. A software engineer described how the buses send data to the company while they are driving. These conversations helped me see how the different parts of the company work together.","words":["break","canteen","discuss","designer","develop","narrow","while"],"ex":{"break":"I enjoyed lunch breaks in the company canteen.","canteen":"I enjoyed lunch breaks in the company canteen.","discuss":"Engineers from different departments sat together and discussed everything from football to the future of transport.","designer":"One designer told me that the company was developing a smaller bus for narrow city streets.","develop":"One designer told me that the company was developing a smaller bus for narrow city streets.","narrow":"One designer told me that the company was developing a smaller bus for narrow city streets.","while":"A software engineer described how the buses send data to the company while they are driving."},"fm":{"break":"breaks","discuss":"discussed","develop":"developing"}},{"id":96,"lv":"B1","n":17,"title":"Electric Buses","tr":"Elektrikli otobüsler","text":"I learned a lot about why cities are buying electric buses. They produce no exhaust gases on the street, so the air in city centres becomes cleaner. They are also much quieter than diesel buses. However, they are more expensive to buy, and cities need charging stations. Selin explained that the total cost over many years can be lower, because electricity is cheaper than fuel and electric motors need less maintenance.","words":["produce","exhaust","gas","air","diesel","total","fuel","less","maintenance"],"ex":{"produce":"They produce no exhaust gases on the street, so the air in city centres becomes cleaner.","exhaust":"They produce no exhaust gases on the street, so the air in city centres becomes cleaner.","gas":"They produce no exhaust gases on the street, so the air in city centres becomes cleaner.","air":"They produce no exhaust gases on the street, so the air in city centres becomes cleaner.","diesel":"They are also much quieter than diesel buses.","total":"Selin explained that the total cost over many years can be lower, because electricity is cheaper than fuel and electric motors need less maintenance.","fuel":"Selin explained that the total cost over many years can be lower, because electricity is cheaper than fuel and electric motors need less maintenance.","less":"Selin explained that the total cost over many years can be lower, because electricity is cheaper than fuel and electric motors need less maintenance.","maintenance":"Selin explained that the total cost over many years can be lower, because electricity is cheaper than fuel and electric motors need less maintenance."},"fm":{"gas":"gases"}},{"id":97,"lv":"B1","n":18,"title":"The Charging Station","tr":"Şarj istasyonu","text":"One day, I joined a team that was installing a fast charging station at a bus depot. The station could charge a bus in about three hours. The engineers had to make sure that the local electricity network could handle the extra demand. I was surprised by how much planning was necessary. A single bus seems simple, but it is part of a much larger system that includes energy, roads, drivers and timetables.","words":["install","depot","local","network","handle","extra","demand","necessary","large","energy","timetable"],"ex":{"install":"One day, I joined a team that was installing a fast charging station at a bus depot.","depot":"One day, I joined a team that was installing a fast charging station at a bus depot.","local":"The engineers had to make sure that the local electricity network could handle the extra demand.","network":"The engineers had to make sure that the local electricity network could handle the extra demand.","handle":"The engineers had to make sure that the local electricity network could handle the extra demand.","extra":"The engineers had to make sure that the local electricity network could handle the extra demand.","demand":"The engineers had to make sure that the local electricity network could handle the extra demand.","necessary":"I was surprised by how much planning was necessary.","large":"A single bus seems simple, but it is part of a much larger system that includes energy, roads, drivers and timetables.","energy":"A single bus seems simple, but it is part of a much larger system that includes energy, roads, drivers and timetables.","timetable":"A single bus seems simple, but it is part of a much larger system that includes energy, roads, drivers and timetables."},"fm":{"install":"installing","large":"larger","timetable":"timetables"}},{"id":98,"lv":"B1","n":19,"title":"A Weekend on Uludağ","tr":"Hafta sonu Uludağ","text":"At the weekend, the interns took a cable car up Uludağ, the mountain above Bursa. Even in July, the air at the top was fresh and cool. We walked through the pine forest and had a picnic near a stream. My flatmates and I talked about our studies and our plans. We discovered that we all wanted to work in sustainable energy. By the end of the day, we were not just colleagues but friends.","words":["above","top","cool","pine","forest","stream","flatmate","discover","sustainable","colleague"],"ex":{"above":"At the weekend, the interns took a cable car up Uludağ, the mountain above Bursa.","top":"Even in July, the air at the top was fresh and cool.","cool":"Even in July, the air at the top was fresh and cool.","pine":"We walked through the pine forest and had a picnic near a stream.","forest":"We walked through the pine forest and had a picnic near a stream.","stream":"We walked through the pine forest and had a picnic near a stream.","flatmate":"My flatmates and I talked about our studies and our plans.","discover":"We discovered that we all wanted to work in sustainable energy.","sustainable":"We discovered that we all wanted to work in sustainable energy.","colleague":"By the end of the day, we were not just colleagues but friends."},"fm":{"flatmate":"flatmates","discover":"discovered","colleague":"colleagues"}},{"id":99,"lv":"B1","n":20,"title":"News from Elif","tr":"Elif'ten haber","text":"On Sunday evening, Elif called me. She was doing her own summer training in a hospital in Istanbul. She told me that she had watched her first operation, and that she nearly fainted. We laughed about it. She asked about my internship, and I described the battery tests. We realised that both of us were learning to be responsible for other people's safety, in very different ways.","words":["hospital","operation","nearly","faint","responsible"],"ex":{"hospital":"She was doing her own summer training in a hospital in Istanbul.","operation":"She told me that she had watched her first operation, and that she nearly fainted.","nearly":"She told me that she had watched her first operation, and that she nearly fainted.","faint":"She told me that she had watched her first operation, and that she nearly fainted.","responsible":"We realised that both of us were learning to be responsible for other people's safety, in very different ways."},"fm":{"faint":"fainted"}},{"id":100,"lv":"B1","n":21,"title":"Writing a Report","tr":"Rapor yazmak","text":"Every intern had to write a report at the end of the internship. Selin advised me to write a little every week instead of leaving everything to the last moment. The report needed an introduction, a description of the company, a section on my tasks and a conclusion. I included graphs from the battery tests. Writing about my work in a formal style was difficult, but it helped me organise what I had learned.","words":["moment","introduction","description","conclusion","formal","style"],"ex":{"moment":"Selin advised me to write a little every week instead of leaving everything to the last moment.","introduction":"The report needed an introduction, a description of the company, a section on my tasks and a conclusion.","description":"The report needed an introduction, a description of the company, a section on my tasks and a conclusion.","conclusion":"The report needed an introduction, a description of the company, a section on my tasks and a conclusion.","formal":"Writing about my work in a formal style was difficult, but it helped me organise what I had learned.","style":"Writing about my work in a formal style was difficult, but it helped me organise what I had learned."},"fm":{}},{"id":101,"lv":"B1","n":22,"title":"A Problem Appears","tr":"Bir sorun ortaya çıkıyor","text":"In the fifth week, the team noticed that some modules were getting hotter than normal during fast charging. This was a serious concern, because high temperatures can shorten the life of a battery. Selin organised extra tests to find the cause. I helped by comparing the data from different modules. After three days, we found a pattern: all the hot modules came from the same production batch.","words":["during","serious","concern","shorten","pattern","production","batch"],"ex":{"during":"In the fifth week, the team noticed that some modules were getting hotter than normal during fast charging.","serious":"This was a serious concern, because high temperatures can shorten the life of a battery.","concern":"This was a serious concern, because high temperatures can shorten the life of a battery.","shorten":"This was a serious concern, because high temperatures can shorten the life of a battery.","pattern":"After three days, we found a pattern: all the hot modules came from the same production batch.","production":"After three days, we found a pattern: all the hot modules came from the same production batch.","batch":"After three days, we found a pattern: all the hot modules came from the same production batch."},"fm":{}},{"id":102,"lv":"B1","n":23,"title":"Finding the Cause","tr":"Sebebi bulmak","text":"The team contacted the supplier of the cooling plates. It turned out that a small change in their production process had made the plates slightly thinner. As a result, they removed less heat from the cells. The supplier agreed to replace the faulty plates. Selin thanked me for my careful work with the data. I was proud that I had helped, even though my part was small.","words":["contact","supplier","cooling","plate","process","slightly","thin","remove","heat","replace","faulty"],"ex":{"contact":"The team contacted the supplier of the cooling plates.","supplier":"The team contacted the supplier of the cooling plates.","cooling":"The team contacted the supplier of the cooling plates.","plate":"The team contacted the supplier of the cooling plates.","process":"It turned out that a small change in their production process had made the plates slightly thinner.","slightly":"It turned out that a small change in their production process had made the plates slightly thinner.","thin":"It turned out that a small change in their production process had made the plates slightly thinner.","remove":"As a result, they removed less heat from the cells.","heat":"As a result, they removed less heat from the cells.","replace":"The supplier agreed to replace the faulty plates.","faulty":"The supplier agreed to replace the faulty plates."},"fm":{"contact":"contacted","plate":"plates","thin":"thinner","remove":"removed"}},{"id":103,"lv":"B1","n":24,"title":"Saying Goodbye","tr":"Veda","text":"On my last day, the battery team organised a small farewell for the interns. Selin gave me a written reference and said that I could apply for a full-time job after I graduated. I thanked everyone for their patience and support. As I left the factory for the last time, I felt grateful. Six weeks earlier, I had arrived knowing almost nothing about batteries. Now I understood how a real engineering team works.","words":["farewell","reference","graduate","patience","grateful"],"ex":{"farewell":"On my last day, the battery team organised a small farewell for the interns.","reference":"Selin gave me a written reference and said that I could apply for a full-time job after I graduated.","graduate":"Selin gave me a written reference and said that I could apply for a full-time job after I graduated.","patience":"I thanked everyone for their patience and support.","grateful":"As I left the factory for the last time, I felt grateful."},"fm":{"graduate":"graduated"}},{"id":104,"lv":"B1","n":25,"title":"Back at University","tr":"Üniversiteye dönüş","text":"When I returned to university in September, I felt different. The theory in my lectures suddenly made more sense, because I had seen how it was used in practice. In thermodynamics, for example, I could connect the equations with the cooling problem in the battery modules. I also started to ask more questions in class. My lecturers noticed that I was more motivated than before.","words":["return","theory","lecture","suddenly","sense","thermodynamics","connect","equation","lecturer","motivated"],"ex":{"return":"When I returned to university in September, I felt different.","theory":"The theory in my lectures suddenly made more sense, because I had seen how it was used in practice.","lecture":"The theory in my lectures suddenly made more sense, because I had seen how it was used in practice.","suddenly":"The theory in my lectures suddenly made more sense, because I had seen how it was used in practice.","sense":"The theory in my lectures suddenly made more sense, because I had seen how it was used in practice.","thermodynamics":"In thermodynamics, for example, I could connect the equations with the cooling problem in the battery modules.","connect":"In thermodynamics, for example, I could connect the equations with the cooling problem in the battery modules.","equation":"In thermodynamics, for example, I could connect the equations with the cooling problem in the battery modules.","lecturer":"My lecturers noticed that I was more motivated than before.","motivated":"My lecturers noticed that I was more motivated than before."},"fm":{"return":"returned","lecture":"lectures","equation":"equations","lecturer":"lecturers"}},{"id":105,"lv":"B1","n":26,"title":"A Group Project","tr":"Grup projesi","text":"In our machine design course, we had to work in groups of four to design a small wind turbine. I worked with Can and two other students, Zehra and Burak. At first, we disagreed about almost everything. Zehra wanted a simple design, while Burak wanted to try something new. We finally agreed to make a list of requirements and to choose the design that met them best.","words":["wind","turbine","disagree","requirement"],"ex":{"wind":"In our machine design course, we had to work in groups of four to design a small wind turbine.","turbine":"In our machine design course, we had to work in groups of four to design a small wind turbine.","disagree":"At first, we disagreed about almost everything.","requirement":"We finally agreed to make a list of requirements and to choose the design that met them best."},"fm":{"disagree":"disagreed","requirement":"requirements"}},{"id":106,"lv":"B1","n":27,"title":"Dividing the Work","tr":"Görev dağılımı","text":"To work efficiently, we divided the tasks. Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox. We created a shared online document and a timetable with deadlines. Every Friday, we met in the library to check our progress. This system worked well, and we rarely missed a deadline.","words":["efficiently","divide","calculate","force","blade","frame","generator","gearbox","create","deadline","rarely"],"ex":{"efficiently":"To work efficiently, we divided the tasks.","divide":"To work efficiently, we divided the tasks.","calculate":"Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox.","force":"Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox.","blade":"Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox.","frame":"Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox.","generator":"Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox.","gearbox":"Zehra calculated the forces on the blades, Burak designed the frame on the computer, Can chose the generator, and I was responsible for the gearbox.","create":"We created a shared online document and a timetable with deadlines.","deadline":"We created a shared online document and a timetable with deadlines.","rarely":"This system worked well, and we rarely missed a deadline."},"fm":{"divide":"divided","calculate":"calculated","force":"forces","blade":"blades","create":"created","deadline":"deadlines"}},{"id":107,"lv":"B1","n":28,"title":"In the Workshop","tr":"Atölyede","text":"After the calculations, we built a prototype in the university workshop. The technician, Mr Hasan, taught us how to use the lathe and the drilling machine safely. Building the turbine took much longer than we had planned. Some parts did not fit together, and we had to make them again. I learned that a design that looks perfect on the screen can be difficult to produce in reality.","words":["calculation","prototype","technician","lathe","drill","safely","fit","perfect","screen","reality"],"ex":{"calculation":"After the calculations, we built a prototype in the university workshop.","prototype":"After the calculations, we built a prototype in the university workshop.","technician":"The technician, Mr Hasan, taught us how to use the lathe and the drilling machine safely.","lathe":"The technician, Mr Hasan, taught us how to use the lathe and the drilling machine safely.","drill":"The technician, Mr Hasan, taught us how to use the lathe and the drilling machine safely.","safely":"The technician, Mr Hasan, taught us how to use the lathe and the drilling machine safely.","fit":"Some parts did not fit together, and we had to make them again.","perfect":"I learned that a design that looks perfect on the screen can be difficult to produce in reality.","screen":"I learned that a design that looks perfect on the screen can be difficult to produce in reality.","reality":"I learned that a design that looks perfect on the screen can be difficult to produce in reality."},"fm":{"calculation":"calculations","drill":"drilling"}},{"id":108,"lv":"B1","n":29,"title":"Testing in the Wind Tunnel","tr":"Rüzgâr tünelinde test","text":"We tested our turbine in the department's small wind tunnel. We measured the speed of the blades and the electricity it produced at different wind speeds. The results were lower than our calculations. After some discussion, we realised that friction in the gearbox was higher than we had assumed. It was my part of the project, so I felt responsible. We decided to improve the gearbox before the final presentation.","words":["speed","discussion","friction","assume"],"ex":{"speed":"We measured the speed of the blades and the electricity it produced at different wind speeds.","discussion":"After some discussion, we realised that friction in the gearbox was higher than we had assumed.","friction":"After some discussion, we realised that friction in the gearbox was higher than we had assumed.","assume":"After some discussion, we realised that friction in the gearbox was higher than we had assumed."},"fm":{"assume":"assumed"}},{"id":109,"lv":"B1","n":30,"title":"Improving the Gearbox","tr":"Dişli kutusunu iyileştirmek","text":"I spent two weekends redesigning the gearbox. I replaced some plastic gears with metal ones and added better bearings. Mr Hasan helped me to make the new parts. When we tested the turbine again, the electricity output increased by almost thirty percent. The whole group was delighted. I learned that testing is not a failure when the results are bad; it shows you exactly what to improve.","words":["redesign","plastic","gear","metal","add","bearing","output","increase","percent","failure","exactly"],"ex":{"redesign":"I spent two weekends redesigning the gearbox.","plastic":"I replaced some plastic gears with metal ones and added better bearings.","gear":"I replaced some plastic gears with metal ones and added better bearings.","metal":"I replaced some plastic gears with metal ones and added better bearings.","add":"I replaced some plastic gears with metal ones and added better bearings.","bearing":"I replaced some plastic gears with metal ones and added better bearings.","output":"When we tested the turbine again, the electricity output increased by almost thirty percent.","increase":"When we tested the turbine again, the electricity output increased by almost thirty percent.","percent":"When we tested the turbine again, the electricity output increased by almost thirty percent.","failure":"I learned that testing is not a failure when the results are bad; it shows you exactly what to improve.","exactly":"I learned that testing is not a failure when the results are bad; it shows you exactly what to improve."},"fm":{"redesign":"redesigning","gear":"gears","add":"added","bearing":"bearings","increase":"increased"}},{"id":110,"lv":"B1","n":31,"title":"The Final Presentation","tr":"Final sunumu","text":"At the end of the term, each group presented its turbine to the professors and the other students. We explained our design choices, showed the test results and talked honestly about our problems. One professor asked why we had not chosen a vertical design. Zehra answered confidently, using the requirements list. We received one of the highest marks in the class, and the professor praised our teamwork.","words":["professor","choice","honestly","vertical","confidently","mark","praise"],"ex":{"professor":"At the end of the term, each group presented its turbine to the professors and the other students.","choice":"We explained our design choices, showed the test results and talked honestly about our problems.","honestly":"We explained our design choices, showed the test results and talked honestly about our problems.","vertical":"One professor asked why we had not chosen a vertical design.","confidently":"Zehra answered confidently, using the requirements list.","mark":"We received one of the highest marks in the class, and the professor praised our teamwork.","praise":"We received one of the highest marks in the class, and the professor praised our teamwork."},"fm":{"professor":"professors","choice":"choices","mark":"marks","praise":"praised"}},{"id":111,"lv":"B1","n":32,"title":"Exam Period","tr":"Sınav dönemi","text":"Then came the exam period. I had six exams in two weeks, including fluid mechanics, which was famous for being difficult. I made a study plan and stuck to it. I studied in the library from morning until evening, with short breaks every hour. Can and I tested each other with old exam questions. Although I was tired, I felt well prepared. Good planning, I realised, reduces stress.","words":["period","fluid","until","although","reduce","stress"],"ex":{"period":"Then came the exam period.","fluid":"I had six exams in two weeks, including fluid mechanics, which was famous for being difficult.","until":"I studied in the library from morning until evening, with short breaks every hour.","although":"Although I was tired, I felt well prepared.","reduce":"Good planning, I realised, reduces stress.","stress":"Good planning, I realised, reduces stress."},"fm":{"reduce":"reduces"}},{"id":112,"lv":"B1","n":33,"title":"Winter Holiday","tr":"Kış tatili","text":"After the exams, I went to my grandmother's village for a few days. It was covered in snow, and the roads were icy. My grandmother was getting older, and she needed help with heavy work. I chopped wood for the stove and repaired a broken door. In the evenings, we sat by the warm stove, and she told me stories about her childhood. I realised how much the world had changed in her lifetime.","words":["icy","chop","wood","stove","repair","story","childhood","lifetime"],"ex":{"icy":"It was covered in snow, and the roads were icy.","chop":"I chopped wood for the stove and repaired a broken door.","wood":"I chopped wood for the stove and repaired a broken door.","stove":"I chopped wood for the stove and repaired a broken door.","repair":"I chopped wood for the stove and repaired a broken door.","story":"In the evenings, we sat by the warm stove, and she told me stories about her childhood.","childhood":"In the evenings, we sat by the warm stove, and she told me stories about her childhood.","lifetime":"I realised how much the world had changed in her lifetime."},"fm":{"chop":"chopped","repair":"repaired","story":"stories"}},{"id":113,"lv":"B1","n":34,"title":"Energy in the Village","tr":"Köydeki enerji","text":"While I was in the village, I noticed how much energy my grandmother's house wasted. The windows let in cold air, and the old stove used a lot of wood. I started to think about simple solutions: better insulation, new windows and maybe solar panels for hot water. When I explained my ideas, my grandmother smiled and said: \"So all those years at university were useful after all!\"","words":["waste","let","insulation","solar","panel","idea","those"],"ex":{"waste":"While I was in the village, I noticed how much energy my grandmother's house wasted.","let":"The windows let in cold air, and the old stove used a lot of wood.","insulation":"I started to think about simple solutions: better insulation, new windows and maybe solar panels for hot water.","solar":"I started to think about simple solutions: better insulation, new windows and maybe solar panels for hot water.","panel":"I started to think about simple solutions: better insulation, new windows and maybe solar panels for hot water.","idea":"When I explained my ideas, my grandmother smiled and said: \"So all those years at university were useful after all!\"","those":"When I explained my ideas, my grandmother smiled and said: \"So all those years at university were useful after all!\""},"fm":{"waste":"wasted","panel":"panels","idea":"ideas"}},{"id":114,"lv":"B1","n":35,"title":"An Idea","tr":"Bir fikir","text":"Back in Ankara, I could not stop thinking about the village. Many old houses in rural areas have the same problems. I talked to Can and Zehra about it. Together, we came up with an idea for our final-year project: a low-cost system that combines insulation and solar heating for village houses. We wanted it to be cheap enough for families with low incomes.","words":["rural","combine","heating","enough","income"],"ex":{"rural":"Many old houses in rural areas have the same problems.","combine":"Together, we came up with an idea for our final-year project: a low-cost system that combines insulation and solar heating for village houses.","heating":"Together, we came up with an idea for our final-year project: a low-cost system that combines insulation and solar heating for village houses.","enough":"We wanted it to be cheap enough for families with low incomes.","income":"We wanted it to be cheap enough for families with low incomes."},"fm":{"combine":"combines","income":"incomes"}},{"id":115,"lv":"B1","n":36,"title":"Finding a Supervisor","tr":"Danışman bulmak","text":"We needed a professor to supervise our project. We wrote a short proposal and sent it to Professor Demir, who worked on renewable energy. She invited us to her office. She liked the idea, but she warned us that the project was ambitious. She asked us to focus on one part first: a solar water heater made from local materials. We agreed, and she became our supervisor.","words":["supervise","proposal","renewable","warn","ambitious","focus","heater"],"ex":{"supervise":"We needed a professor to supervise our project.","proposal":"We wrote a short proposal and sent it to Professor Demir, who worked on renewable energy.","renewable":"We wrote a short proposal and sent it to Professor Demir, who worked on renewable energy.","warn":"She liked the idea, but she warned us that the project was ambitious.","ambitious":"She liked the idea, but she warned us that the project was ambitious.","focus":"She asked us to focus on one part first: a solar water heater made from local materials.","heater":"She asked us to focus on one part first: a solar water heater made from local materials."},"fm":{"warn":"warned"}},{"id":116,"lv":"B1","n":37,"title":"A Field Visit","tr":"Saha ziyareti","text":"In the spring, we visited my grandmother's village to collect data. We measured the temperatures in several houses and asked families how much they spent on heating. Most people were friendly and curious. An old man showed us a water heater that he had built himself from an old barrel. It was not efficient, but the idea was clever. We took photos and notes to use in our design.","words":["collect","curious","himself","barrel","efficient"],"ex":{"collect":"In the spring, we visited my grandmother's village to collect data.","curious":"Most people were friendly and curious.","himself":"An old man showed us a water heater that he had built himself from an old barrel.","barrel":"An old man showed us a water heater that he had built himself from an old barrel.","efficient":"It was not efficient, but the idea was clever."},"fm":{}},{"id":117,"lv":"B1","n":38,"title":"A Budget Problem","tr":"Bütçe sorunu","text":"Our first design used high-quality copper pipes, but when we calculated the cost, it was far too expensive. Professor Demir reminded us that our goal was a cheap system. We searched for alternatives and found that some plastic pipes could survive the temperatures we needed. This reduced the cost by half. I learned that engineering is always about choices between performance and price.","words":["quality","copper","pipe","remind","search","alternative","survive","between","performance"],"ex":{"quality":"Our first design used high-quality copper pipes, but when we calculated the cost, it was far too expensive.","copper":"Our first design used high-quality copper pipes, but when we calculated the cost, it was far too expensive.","pipe":"Our first design used high-quality copper pipes, but when we calculated the cost, it was far too expensive.","remind":"Professor Demir reminded us that our goal was a cheap system.","search":"We searched for alternatives and found that some plastic pipes could survive the temperatures we needed.","alternative":"We searched for alternatives and found that some plastic pipes could survive the temperatures we needed.","survive":"We searched for alternatives and found that some plastic pipes could survive the temperatures we needed.","between":"I learned that engineering is always about choices between performance and price.","performance":"I learned that engineering is always about choices between performance and price."},"fm":{"pipe":"pipes","remind":"reminded","search":"searched","alternative":"alternatives"}},{"id":118,"lv":"B1","n":39,"title":"Can's News","tr":"Can'ın haberi","text":"In May, Can told me some exciting news. He had been accepted for a summer course in London, at the same school I went to. He was going to stay with the Wilsons! I gave him a long list of advice and a message for Lucy and Jack. Can laughed and said: \"You sound like my mother.\" Still, I was very happy for him.","words":["accept","advice","sound"],"ex":{"accept":"He had been accepted for a summer course in London, at the same school I went to.","advice":"I gave him a long list of advice and a message for Lucy and Jack.","sound":"Can laughed and said: \"You sound like my mother.\""},"fm":{"accept":"accepted"}},{"id":119,"lv":"B1","n":40,"title":"The End of the Third Year","tr":"Üçüncü yılın sonu","text":"At the end of my third year, I looked back at everything that had happened. I had completed an internship, built a turbine and started a real project. My English had become a tool that I used every day, not just a school subject. I also understood that engineering is not only about machines, but about people and their needs. I was ready for the next challenge.","words":["complete","tool","subject","challenge"],"ex":{"complete":"I had completed an internship, built a turbine and started a real project.","tool":"My English had become a tool that I used every day, not just a school subject.","subject":"My English had become a tool that I used every day, not just a school subject.","challenge":"I was ready for the next challenge."},"fm":{"complete":"completed"}},{"id":120,"lv":"B2","n":1,"title":"The Final Year","tr":"Son sınıf","text":"My final year at university began with a mixture of excitement and pressure. On the one hand, the end of my studies was finally in sight. On the other hand, I had to complete our graduation project, take several advanced courses and decide what to do after graduating. Professor Demir warned us that the final year passes surprisingly quickly. \"If you postpone things,\" she said, \"you will regret it in June.\"","words":["mixture","excitement","pressure","sight","graduation","advanced","pass","surprisingly","postpone","will","regret"],"ex":{"mixture":"My final year at university began with a mixture of excitement and pressure.","excitement":"My final year at university began with a mixture of excitement and pressure.","pressure":"My final year at university began with a mixture of excitement and pressure.","sight":"On the one hand, the end of my studies was finally in sight.","graduation":"On the other hand, I had to complete our graduation project, take several advanced courses and decide what to do after graduating.","advanced":"On the other hand, I had to complete our graduation project, take several advanced courses and decide what to do after graduating.","pass":"Professor Demir warned us that the final year passes surprisingly quickly.","surprisingly":"Professor Demir warned us that the final year passes surprisingly quickly.","postpone":"\"If you postpone things,\" she said, \"you will regret it in June.\"","will":"\"If you postpone things,\" she said, \"you will regret it in June.\"","regret":"\"If you postpone things,\" she said, \"you will regret it in June.\""},"fm":{"pass":"passes"}},{"id":121,"lv":"B2","n":2,"title":"Designing the Prototype","tr":"Prototipi tasarlamak","text":"Our first major task was to design a working prototype of the solar water heater. The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes. However, achieving good efficiency with cheap materials is far from simple. We compared several designs using computer simulations, estimating how much heat each one would collect on a typical winter day in central Anatolia.","words":["major","basic","principle","straightforward","sunlight","dark","surface","transfer","flow","achieve","efficiency","simulation","estimate","typical","central"],"ex":{"major":"Our first major task was to design a working prototype of the solar water heater.","basic":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","principle":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","straightforward":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","sunlight":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","dark":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","surface":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","transfer":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","flow":"The basic principle is straightforward: sunlight heats a dark surface, and the heat is transferred to water flowing through pipes.","achieve":"However, achieving good efficiency with cheap materials is far from simple.","efficiency":"However, achieving good efficiency with cheap materials is far from simple.","simulation":"We compared several designs using computer simulations, estimating how much heat each one would collect on a typical winter day in central Anatolia.","estimate":"We compared several designs using computer simulations, estimating how much heat each one would collect on a typical winter day in central Anatolia.","typical":"We compared several designs using computer simulations, estimating how much heat each one would collect on a typical winter day in central Anatolia.","central":"We compared several designs using computer simulations, estimating how much heat each one would collect on a typical winter day in central Anatolia."},"fm":{"transfer":"transferred","flow":"flowing","achieve":"achieving","simulation":"simulations","estimate":"estimating"}},{"id":122,"lv":"B2","n":3,"title":"The Limits of Simulation","tr":"Simülasyonun sınırları","text":"The simulations were useful, but they had limitations. They assumed perfect insulation and ideal weather conditions, which never exist in reality. Professor Demir encouraged us to treat the results with caution. \"A model is only as good as its assumptions,\" she reminded us. Consequently, we decided to build two different prototypes and test them outdoors, so that we could compare the predictions with actual measurements.","words":["limitation","ideal","condition","never","exist","treat","caution","assumption","consequently","outdoors","prediction","actual","measurement"],"ex":{"limitation":"The simulations were useful, but they had limitations.","ideal":"They assumed perfect insulation and ideal weather conditions, which never exist in reality.","condition":"They assumed perfect insulation and ideal weather conditions, which never exist in reality.","never":"They assumed perfect insulation and ideal weather conditions, which never exist in reality.","exist":"They assumed perfect insulation and ideal weather conditions, which never exist in reality.","treat":"Professor Demir encouraged us to treat the results with caution.","caution":"Professor Demir encouraged us to treat the results with caution.","assumption":"\"A model is only as good as its assumptions,\" she reminded us.","consequently":"Consequently, we decided to build two different prototypes and test them outdoors, so that we could compare the predictions with actual measurements.","outdoors":"Consequently, we decided to build two different prototypes and test them outdoors, so that we could compare the predictions with actual measurements.","prediction":"Consequently, we decided to build two different prototypes and test them outdoors, so that we could compare the predictions with actual measurements.","actual":"Consequently, we decided to build two different prototypes and test them outdoors, so that we could compare the predictions with actual measurements.","measurement":"Consequently, we decided to build two different prototypes and test them outdoors, so that we could compare the predictions with actual measurements."},"fm":{"limitation":"limitations","condition":"conditions","assumption":"assumptions","prediction":"predictions","measurement":"measurements"}},{"id":123,"lv":"B2","n":4,"title":"Gathering Materials","tr":"Malzeme toplamak","text":"Gathering the materials turned out to be an adventure in itself. Since our budget was limited, we visited scrapyards and second-hand markets around Ankara. We found old window glass, aluminium sheets and a used water tank at remarkably low prices. Some sellers were curious about our project, and one of them even gave us a discount once he heard that it was intended for village families.","words":["gather","adventure","itself","since","budget","limited","scrapyard","around","aluminium","sheet","tank","remarkably","seller","discount","once","hear","intend"],"ex":{"gather":"Gathering the materials turned out to be an adventure in itself.","adventure":"Gathering the materials turned out to be an adventure in itself.","itself":"Gathering the materials turned out to be an adventure in itself.","since":"Since our budget was limited, we visited scrapyards and second-hand markets around Ankara.","budget":"Since our budget was limited, we visited scrapyards and second-hand markets around Ankara.","limited":"Since our budget was limited, we visited scrapyards and second-hand markets around Ankara.","scrapyard":"Since our budget was limited, we visited scrapyards and second-hand markets around Ankara.","around":"Since our budget was limited, we visited scrapyards and second-hand markets around Ankara.","aluminium":"We found old window glass, aluminium sheets and a used water tank at remarkably low prices.","sheet":"We found old window glass, aluminium sheets and a used water tank at remarkably low prices.","tank":"We found old window glass, aluminium sheets and a used water tank at remarkably low prices.","remarkably":"We found old window glass, aluminium sheets and a used water tank at remarkably low prices.","seller":"Some sellers were curious about our project, and one of them even gave us a discount once he heard that it was intended for village families.","discount":"Some sellers were curious about our project, and one of them even gave us a discount once he heard that it was intended for village families.","once":"Some sellers were curious about our project, and one of them even gave us a discount once he heard that it was intended for village families.","hear":"Some sellers were curious about our project, and one of them even gave us a discount once he heard that it was intended for village families.","intend":"Some sellers were curious about our project, and one of them even gave us a discount once he heard that it was intended for village families."},"fm":{"gather":"gathering","scrapyard":"scrapyards","sheet":"sheets","seller":"sellers","hear":"heard","intend":"intended"}},{"id":124,"lv":"B2","n":5,"title":"The Experiment on the Roof","tr":"Çatıda deney","text":"With the department's permission, we installed both prototypes on the roof of the engineering building. We attached temperature sensors to the inlet and outlet pipes and connected them to a small data logger. Every hour, the device recorded the temperatures, the amount of sunlight and the air temperature. For the first time, our project felt genuinely real, and we checked the data on our phones almost obsessively.","words":["permission","roof","attach","inlet","outlet","logger","device","amount","genuinely","obsessively"],"ex":{"permission":"With the department's permission, we installed both prototypes on the roof of the engineering building.","roof":"With the department's permission, we installed both prototypes on the roof of the engineering building.","attach":"We attached temperature sensors to the inlet and outlet pipes and connected them to a small data logger.","inlet":"We attached temperature sensors to the inlet and outlet pipes and connected them to a small data logger.","outlet":"We attached temperature sensors to the inlet and outlet pipes and connected them to a small data logger.","logger":"We attached temperature sensors to the inlet and outlet pipes and connected them to a small data logger.","device":"Every hour, the device recorded the temperatures, the amount of sunlight and the air temperature.","amount":"Every hour, the device recorded the temperatures, the amount of sunlight and the air temperature.","genuinely":"For the first time, our project felt genuinely real, and we checked the data on our phones almost obsessively.","obsessively":"For the first time, our project felt genuinely real, and we checked the data on our phones almost obsessively."},"fm":{"attach":"attached"}},{"id":125,"lv":"B2","n":6,"title":"Unexpected Results","tr":"Beklenmedik sonuçlar","text":"After two weeks, the results were surprising. The simpler prototype, which we had expected to perform worse, actually produced hotter water on cold mornings. After analysing the data, Zehra suggested an explanation: the complex design had more joints, and heat was escaping through them. This taught us an important lesson. Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists.","words":["surprising","perform","worse","actually","analyse","explanation","complex","joint","escape","lesson","complexity","automatically","advantage","must","non","specialist"],"ex":{"surprising":"After two weeks, the results were surprising.","perform":"The simpler prototype, which we had expected to perform worse, actually produced hotter water on cold mornings.","worse":"The simpler prototype, which we had expected to perform worse, actually produced hotter water on cold mornings.","actually":"The simpler prototype, which we had expected to perform worse, actually produced hotter water on cold mornings.","analyse":"After analysing the data, Zehra suggested an explanation: the complex design had more joints, and heat was escaping through them.","explanation":"After analysing the data, Zehra suggested an explanation: the complex design had more joints, and heat was escaping through them.","complex":"After analysing the data, Zehra suggested an explanation: the complex design had more joints, and heat was escaping through them.","joint":"After analysing the data, Zehra suggested an explanation: the complex design had more joints, and heat was escaping through them.","escape":"After analysing the data, Zehra suggested an explanation: the complex design had more joints, and heat was escaping through them.","lesson":"This taught us an important lesson.","complexity":"Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists.","automatically":"Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists.","advantage":"Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists.","must":"Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists.","non":"Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists.","specialist":"Complexity is not automatically an advantage, especially when a system must be built and repaired by non-specialists."},"fm":{"analyse":"analysing","joint":"joints","escape":"escaping","specialist":"specialists"}},{"id":126,"lv":"B2","n":7,"title":"A Seminar on Climate Change","tr":"İklim değişikliği semineri","text":"In October, the department organised a seminar on climate change. The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades. She explained that droughts and extreme weather events are expected to become more frequent. What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","words":["october","seminar","climate","speaker","scientist","average","rise","noticeably","recent","decade","drought","extreme","event","frequent","strike","argument","role","emission","community","adapt","unavoidable"],"ex":{"october":"In October, the department organised a seminar on climate change.","seminar":"In October, the department organised a seminar on climate change.","climate":"In October, the department organised a seminar on climate change.","speaker":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","scientist":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","average":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","rise":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","noticeably":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","recent":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","decade":"The speaker, a climate scientist, presented data showing that average temperatures in Turkey have risen noticeably over recent decades.","drought":"She explained that droughts and extreme weather events are expected to become more frequent.","extreme":"She explained that droughts and extreme weather events are expected to become more frequent.","event":"She explained that droughts and extreme weather events are expected to become more frequent.","frequent":"She explained that droughts and extreme weather events are expected to become more frequent.","strike":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","argument":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","role":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","emission":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","community":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","adapt":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable.","unavoidable":"What struck me most was her argument that engineers have a central role in both reducing emissions and helping communities adapt to changes that are already unavoidable."},"fm":{"rise":"risen","decade":"decades","drought":"droughts","event":"events","strike":"struck","emission":"emissions","community":"communities"}},{"id":127,"lv":"B2","n":8,"title":"A Debate on Energy Policy","tr":"Enerji politikası tartışması","text":"After the seminar, our class held a debate on national energy policy. One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions. Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive. I realised that both sides had valid points, and that good policy requires balancing environmental, economic and social concerns.","words":["hold","debate","policy","argue","invest","heavily","power","abundant","sunshine","strong","region","point","source","intermittent","reliable","storage","remain","valid","require","environmental","economic","social"],"ex":{"hold":"After the seminar, our class held a debate on national energy policy.","debate":"After the seminar, our class held a debate on national energy policy.","policy":"After the seminar, our class held a debate on national energy policy.","argue":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","invest":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","heavily":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","power":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","abundant":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","sunshine":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","strong":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","region":"One group argued that the country should invest heavily in solar and wind power, since we have abundant sunshine and strong winds in many regions.","point":"Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive.","source":"Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive.","intermittent":"Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive.","reliable":"Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive.","storage":"Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive.","remain":"Another group pointed out that renewable sources are intermittent and that reliable storage remains expensive.","valid":"I realised that both sides had valid points, and that good policy requires balancing environmental, economic and social concerns.","require":"I realised that both sides had valid points, and that good policy requires balancing environmental, economic and social concerns.","environmental":"I realised that both sides had valid points, and that good policy requires balancing environmental, economic and social concerns.","economic":"I realised that both sides had valid points, and that good policy requires balancing environmental, economic and social concerns.","social":"I realised that both sides had valid points, and that good policy requires balancing environmental, economic and social concerns."},"fm":{"hold":"held","argue":"argued","region":"regions","point":"pointed","source":"sources","remain":"remains","require":"requires"}},{"id":128,"lv":"B2","n":9,"title":"The Storage Problem","tr":"Depolama sorunu","text":"The debate made me think about energy storage, which connected directly to my internship experience. Batteries can store electricity for hours, but storing energy for days or seasons is much more difficult. Researchers are exploring alternatives such as pumped hydro, hydrogen and thermal storage. I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","words":["directly","store","season","researcher","explore","pump","hydro","hydrogen","essay","essentially","provide","deserve","attention","technically","mature"],"ex":{"directly":"The debate made me think about energy storage, which connected directly to my internship experience.","store":"Batteries can store electricity for hours, but storing energy for days or seasons is much more difficult.","season":"Batteries can store electricity for hours, but storing energy for days or seasons is much more difficult.","researcher":"Researchers are exploring alternatives such as pumped hydro, hydrogen and thermal storage.","explore":"Researchers are exploring alternatives such as pumped hydro, hydrogen and thermal storage.","pump":"Researchers are exploring alternatives such as pumped hydro, hydrogen and thermal storage.","hydro":"Researchers are exploring alternatives such as pumped hydro, hydrogen and thermal storage.","hydrogen":"Researchers are exploring alternatives such as pumped hydro, hydrogen and thermal storage.","essay":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","essentially":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","provide":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","deserve":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","attention":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","technically":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature.","mature":"I wrote a short essay arguing that thermal storage, which is what our water tank essentially provides, deserves more attention because it is cheap and technically mature."},"fm":{"season":"seasons","researcher":"researchers","explore":"exploring","pump":"pumped","provide":"provides","deserve":"deserves"}},{"id":129,"lv":"B2","n":10,"title":"An AI Course","tr":"Yapay zekâ dersi","text":"That semester, I also took an elective course on artificial intelligence for engineers. We learned how machine learning algorithms can detect patterns in large datasets. Our lecturer emphasised that these tools are powerful but not magical. If the training data is incomplete or biased, the predictions will be unreliable. For my course project, I trained a simple model to predict the output of our solar heater from weather forecasts.","words":["semester","elective","artificial","intelligence","algorithm","detect","dataset","emphasise","powerful","magical","incomplete","biased","unreliable","predict","forecast"],"ex":{"semester":"That semester, I also took an elective course on artificial intelligence for engineers.","elective":"That semester, I also took an elective course on artificial intelligence for engineers.","artificial":"That semester, I also took an elective course on artificial intelligence for engineers.","intelligence":"That semester, I also took an elective course on artificial intelligence for engineers.","algorithm":"We learned how machine learning algorithms can detect patterns in large datasets.","detect":"We learned how machine learning algorithms can detect patterns in large datasets.","dataset":"We learned how machine learning algorithms can detect patterns in large datasets.","emphasise":"Our lecturer emphasised that these tools are powerful but not magical.","powerful":"Our lecturer emphasised that these tools are powerful but not magical.","magical":"Our lecturer emphasised that these tools are powerful but not magical.","incomplete":"If the training data is incomplete or biased, the predictions will be unreliable.","biased":"If the training data is incomplete or biased, the predictions will be unreliable.","unreliable":"If the training data is incomplete or biased, the predictions will be unreliable.","predict":"For my course project, I trained a simple model to predict the output of our solar heater from weather forecasts.","forecast":"For my course project, I trained a simple model to predict the output of our solar heater from weather forecasts."},"fm":{"algorithm":"algorithms","dataset":"datasets","emphasise":"emphasised","forecast":"forecasts"}},{"id":130,"lv":"B2","n":11,"title":"The Model's Predictions","tr":"Model tahminleri","text":"Surprisingly, the model worked reasonably well on sunny days, predicting the water temperature within a few degrees. On cloudy days, however, its predictions were far less accurate, because we had collected very little data under those conditions. This experience made the lecturer's warning concrete for me. A model cannot know what it has never seen. I suggested in my report that we should continue collecting data throughout the winter.","words":["reasonably","within","degree","accurate","under","concrete","cannot","continue","throughout"],"ex":{"reasonably":"Surprisingly, the model worked reasonably well on sunny days, predicting the water temperature within a few degrees.","within":"Surprisingly, the model worked reasonably well on sunny days, predicting the water temperature within a few degrees.","degree":"Surprisingly, the model worked reasonably well on sunny days, predicting the water temperature within a few degrees.","accurate":"On cloudy days, however, its predictions were far less accurate, because we had collected very little data under those conditions.","under":"On cloudy days, however, its predictions were far less accurate, because we had collected very little data under those conditions.","concrete":"This experience made the lecturer's warning concrete for me.","cannot":"A model cannot know what it has never seen.","continue":"I suggested in my report that we should continue collecting data throughout the winter.","throughout":"I suggested in my report that we should continue collecting data throughout the winter."},"fm":{"degree":"degrees"}},{"id":131,"lv":"B2","n":12,"title":"Social Media and Attention","tr":"Sosyal medya ve dikkat","text":"Around this time, I noticed that I was spending too much time on my phone. I would open an app to check one message and find myself scrolling for half an hour. It was affecting my concentration, especially when I was studying. Inspired by an article on digital habits, I turned off most notifications and set a daily time limit. Within a couple of weeks, I felt calmer and more productive.","words":["app","scroll","affect","concentration","inspire","article","digital","habit","notification","set","daily","limit","couple","calm","productive"],"ex":{"app":"I would open an app to check one message and find myself scrolling for half an hour.","scroll":"I would open an app to check one message and find myself scrolling for half an hour.","affect":"It was affecting my concentration, especially when I was studying.","concentration":"It was affecting my concentration, especially when I was studying.","inspire":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","article":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","digital":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","habit":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","notification":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","set":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","daily":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","limit":"Inspired by an article on digital habits, I turned off most notifications and set a daily time limit.","couple":"Within a couple of weeks, I felt calmer and more productive.","calm":"Within a couple of weeks, I felt calmer and more productive.","productive":"Within a couple of weeks, I felt calmer and more productive."},"fm":{"scroll":"scrolling","affect":"affecting","inspire":"inspired","habit":"habits","notification":"notifications","calm":"calmer"}},{"id":132,"lv":"B2","n":13,"title":"Can Returns from London","tr":"Can Londra'dan dönüyor","text":"Can had come back from London full of stories. He had stayed with the Wilsons, who apparently still talked about me and my Turkish tea. Jack had grown taller and was now obsessed with robots, partly because of my stories. Can's English had improved dramatically, and he had become more self-confident. He admitted that my advice to speak English all the time had been annoying but extremely effective.","words":["apparently","obsessed","partly","dramatically","self","admit","annoying","extremely","effective"],"ex":{"apparently":"He had stayed with the Wilsons, who apparently still talked about me and my Turkish tea.","obsessed":"Jack had grown taller and was now obsessed with robots, partly because of my stories.","partly":"Jack had grown taller and was now obsessed with robots, partly because of my stories.","dramatically":"Can's English had improved dramatically, and he had become more self-confident.","self":"Can's English had improved dramatically, and he had become more self-confident.","admit":"He admitted that my advice to speak English all the time had been annoying but extremely effective.","annoying":"He admitted that my advice to speak English all the time had been annoying but extremely effective.","extremely":"He admitted that my advice to speak English all the time had been annoying but extremely effective.","effective":"He admitted that my advice to speak English all the time had been annoying but extremely effective."},"fm":{"admit":"admitted"}},{"id":133,"lv":"B2","n":14,"title":"Applying for Funding","tr":"Fon başvurusu","text":"In November, Professor Demir told us about a national innovation fund that supports student projects with social impact. If we were successful, we would receive money to build a full-scale system in a real village house. The application was demanding: we had to describe the problem, our solution, a budget, a timeline and the expected benefits. We divided the sections among ourselves and worked on them every evening for three weeks.","words":["november","innovation","fund","impact","successful","scale","demanding","timeline","benefit","among"],"ex":{"november":"In November, Professor Demir told us about a national innovation fund that supports student projects with social impact.","innovation":"In November, Professor Demir told us about a national innovation fund that supports student projects with social impact.","fund":"In November, Professor Demir told us about a national innovation fund that supports student projects with social impact.","impact":"In November, Professor Demir told us about a national innovation fund that supports student projects with social impact.","successful":"If we were successful, we would receive money to build a full-scale system in a real village house.","scale":"If we were successful, we would receive money to build a full-scale system in a real village house.","demanding":"The application was demanding: we had to describe the problem, our solution, a budget, a timeline and the expected benefits.","timeline":"The application was demanding: we had to describe the problem, our solution, a budget, a timeline and the expected benefits.","benefit":"The application was demanding: we had to describe the problem, our solution, a budget, a timeline and the expected benefits.","among":"We divided the sections among ourselves and worked on them every evening for three weeks."},"fm":{"benefit":"benefits"}},{"id":134,"lv":"B2","n":15,"title":"Measuring Impact","tr":"Etkiyi ölçmek","text":"The most challenging part of the application was explaining the expected impact. It was not enough to say that our heater would help people. We had to estimate how much money a family could save, how much carbon dioxide emissions would be reduced and how many households could potentially benefit. I used the data from our field visit to make these estimates, and I clearly stated the assumptions behind every number.","words":["challenging","carbon","dioxide","household","potentially","field","behind"],"ex":{"challenging":"The most challenging part of the application was explaining the expected impact.","carbon":"We had to estimate how much money a family could save, how much carbon dioxide emissions would be reduced and how many households could potentially benefit.","dioxide":"We had to estimate how much money a family could save, how much carbon dioxide emissions would be reduced and how many households could potentially benefit.","household":"We had to estimate how much money a family could save, how much carbon dioxide emissions would be reduced and how many households could potentially benefit.","potentially":"We had to estimate how much money a family could save, how much carbon dioxide emissions would be reduced and how many households could potentially benefit.","field":"I used the data from our field visit to make these estimates, and I clearly stated the assumptions behind every number.","behind":"I used the data from our field visit to make these estimates, and I clearly stated the assumptions behind every number."},"fm":{"household":"households"}},{"id":135,"lv":"B2","n":16,"title":"The Interview Panel","tr":"Mülakat paneli","text":"Our application reached the final round, and we were invited to present our project to a panel of experts. One panel member, an economist, challenged us on whether villagers would actually adopt the technology. It was an excellent question, and we had not thought about it enough. Zehra replied that we planned to involve local people in building the system, so that they would understand and trust it.","words":["reach","round","expert","economist","whether","villager","adopt","technology","excellent","involve","trust"],"ex":{"reach":"Our application reached the final round, and we were invited to present our project to a panel of experts.","round":"Our application reached the final round, and we were invited to present our project to a panel of experts.","expert":"Our application reached the final round, and we were invited to present our project to a panel of experts.","economist":"One panel member, an economist, challenged us on whether villagers would actually adopt the technology.","whether":"One panel member, an economist, challenged us on whether villagers would actually adopt the technology.","villager":"One panel member, an economist, challenged us on whether villagers would actually adopt the technology.","adopt":"One panel member, an economist, challenged us on whether villagers would actually adopt the technology.","technology":"One panel member, an economist, challenged us on whether villagers would actually adopt the technology.","excellent":"It was an excellent question, and we had not thought about it enough.","involve":"Zehra replied that we planned to involve local people in building the system, so that they would understand and trust it.","trust":"Zehra replied that we planned to involve local people in building the system, so that they would understand and trust it."},"fm":{"reach":"reached","expert":"experts","villager":"villagers"}},{"id":136,"lv":"B2","n":17,"title":"We Won the Funding","tr":"Fon kazandık","text":"Two weeks later, we received the news that our project had been selected for funding. We were all overjoyed. The amount was modest, but it was enough to install a complete system in one house and monitor it for a whole year. Professor Demir congratulated us and immediately reminded us of our responsibilities. \"Now you have to deliver what you promised,\" she said with a smile.","words":["select","funding","overjoyed","modest","monitor","congratulate","immediately","responsibility","deliver"],"ex":{"select":"Two weeks later, we received the news that our project had been selected for funding.","funding":"Two weeks later, we received the news that our project had been selected for funding.","overjoyed":"We were all overjoyed.","modest":"The amount was modest, but it was enough to install a complete system in one house and monitor it for a whole year.","monitor":"The amount was modest, but it was enough to install a complete system in one house and monitor it for a whole year.","congratulate":"Professor Demir congratulated us and immediately reminded us of our responsibilities.","immediately":"Professor Demir congratulated us and immediately reminded us of our responsibilities.","responsibility":"Professor Demir congratulated us and immediately reminded us of our responsibilities.","deliver":"\"Now you have to deliver what you promised,\" she said with a smile."},"fm":{"select":"selected","congratulate":"congratulated","responsibility":"responsibilities"}},{"id":137,"lv":"B2","n":18,"title":"Choosing the House","tr":"Ev sahibini seçmek","text":"With the help of the village headman, we chose a house belonging to an elderly couple, Hatice and Osman. Their house was typical of the region: thick stone walls, small windows and a wood stove. They heated water on the stove, which was time-consuming and used a lot of firewood. They were somewhat skeptical at first, but they agreed after we explained that the system would cost them nothing.","words":["headman","belong","elderly","thick","stone","wall","consume","firewood","somewhat","skeptical"],"ex":{"headman":"With the help of the village headman, we chose a house belonging to an elderly couple, Hatice and Osman.","belong":"With the help of the village headman, we chose a house belonging to an elderly couple, Hatice and Osman.","elderly":"With the help of the village headman, we chose a house belonging to an elderly couple, Hatice and Osman.","thick":"Their house was typical of the region: thick stone walls, small windows and a wood stove.","stone":"Their house was typical of the region: thick stone walls, small windows and a wood stove.","wall":"Their house was typical of the region: thick stone walls, small windows and a wood stove.","consume":"They heated water on the stove, which was time-consuming and used a lot of firewood.","firewood":"They heated water on the stove, which was time-consuming and used a lot of firewood.","somewhat":"They were somewhat skeptical at first, but they agreed after we explained that the system would cost them nothing.","skeptical":"They were somewhat skeptical at first, but they agreed after we explained that the system would cost them nothing."},"fm":{"belong":"belonging","wall":"walls","consume":"consuming"}},{"id":138,"lv":"B2","n":19,"title":"Building with the Villagers","tr":"Köylülerle birlikte inşa","text":"We built the system during the spring break. Following our plan, we invited neighbours to help. Several young men assisted with the heavy work, and Osman, who had been a carpenter, made the wooden frame himself. Working together created a sense of ownership. By the end of the week, the solar collector was on the roof, the insulated tank was in the attic, and the first warm water was flowing from the tap.","words":["neighbour","young","assist","carpenter","wooden","ownership","collector","insulate","attic","tap"],"ex":{"neighbour":"Following our plan, we invited neighbours to help.","young":"Several young men assisted with the heavy work, and Osman, who had been a carpenter, made the wooden frame himself.","assist":"Several young men assisted with the heavy work, and Osman, who had been a carpenter, made the wooden frame himself.","carpenter":"Several young men assisted with the heavy work, and Osman, who had been a carpenter, made the wooden frame himself.","wooden":"Several young men assisted with the heavy work, and Osman, who had been a carpenter, made the wooden frame himself.","ownership":"Working together created a sense of ownership.","collector":"By the end of the week, the solar collector was on the roof, the insulated tank was in the attic, and the first warm water was flowing from the tap.","insulate":"By the end of the week, the solar collector was on the roof, the insulated tank was in the attic, and the first warm water was flowing from the tap.","attic":"By the end of the week, the solar collector was on the roof, the insulated tank was in the attic, and the first warm water was flowing from the tap.","tap":"By the end of the week, the solar collector was on the roof, the insulated tank was in the attic, and the first warm water was flowing from the tap."},"fm":{"neighbour":"neighbours","assist":"assisted","insulate":"insulated"}},{"id":139,"lv":"B2","n":20,"title":"First Reactions","tr":"İlk tepkiler","text":"Hatice's reaction was unforgettable. When warm water came out of the tap on a sunny afternoon, she laughed and called her neighbours to come and see. Within a few days, other families were asking whether they could have a similar system. We had to explain that our funding covered only one house. Nevertheless, their enthusiasm convinced us that the project addressed a genuine need.","words":["reaction","unforgettable","similar","nevertheless","enthusiasm","convince","genuine"],"ex":{"reaction":"Hatice's reaction was unforgettable.","unforgettable":"Hatice's reaction was unforgettable.","similar":"Within a few days, other families were asking whether they could have a similar system.","nevertheless":"Nevertheless, their enthusiasm convinced us that the project addressed a genuine need.","enthusiasm":"Nevertheless, their enthusiasm convinced us that the project addressed a genuine need.","convince":"Nevertheless, their enthusiasm convinced us that the project addressed a genuine need.","genuine":"Nevertheless, their enthusiasm convinced us that the project addressed a genuine need."},"fm":{"convince":"convinced"}},{"id":140,"lv":"B2","n":21,"title":"Problems with Data Collection","tr":"Veri toplama sorunları","text":"Monitoring the system remotely proved more difficult than we had anticipated. The mobile signal in the village was weak, so the data logger often failed to send its measurements. On one occasion, a power cut erased several days of data. We eventually solved the problem by storing the data on a memory card and asking Osman's grandson to send us photos of a simple display every week. Sometimes the low-tech solution is the most reliable.","words":["remotely","prove","anticipate","mobile","signal","weak","fail","occasion","cut","erase","eventually","memory","grandson","display","tech"],"ex":{"remotely":"Monitoring the system remotely proved more difficult than we had anticipated.","prove":"Monitoring the system remotely proved more difficult than we had anticipated.","anticipate":"Monitoring the system remotely proved more difficult than we had anticipated.","mobile":"The mobile signal in the village was weak, so the data logger often failed to send its measurements.","signal":"The mobile signal in the village was weak, so the data logger often failed to send its measurements.","weak":"The mobile signal in the village was weak, so the data logger often failed to send its measurements.","fail":"The mobile signal in the village was weak, so the data logger often failed to send its measurements.","occasion":"On one occasion, a power cut erased several days of data.","cut":"On one occasion, a power cut erased several days of data.","erase":"On one occasion, a power cut erased several days of data.","eventually":"We eventually solved the problem by storing the data on a memory card and asking Osman's grandson to send us photos of a simple display every week.","memory":"We eventually solved the problem by storing the data on a memory card and asking Osman's grandson to send us photos of a simple display every week.","grandson":"We eventually solved the problem by storing the data on a memory card and asking Osman's grandson to send us photos of a simple display every week.","display":"We eventually solved the problem by storing the data on a memory card and asking Osman's grandson to send us photos of a simple display every week.","tech":"Sometimes the low-tech solution is the most reliable."},"fm":{"prove":"proved","anticipate":"anticipated","fail":"failed","erase":"erased"}},{"id":141,"lv":"B2","n":22,"title":"The Project Report","tr":"Mezuniyet projesi raporu","text":"Writing the final report was a substantial task. The report had to be written in English, following the format of a scientific paper. We described the background, the design process, the experimental method, the results and the limitations. Professor Demir insisted that we discuss our failures honestly. \"Readers learn as much from what did not work,\" she explained, \"as from what did.\" We revised the report four times before submitting it.","words":["substantial","format","scientific","paper","background","experimental","method","insist","reader","revise","submit"],"ex":{"substantial":"Writing the final report was a substantial task.","format":"The report had to be written in English, following the format of a scientific paper.","scientific":"The report had to be written in English, following the format of a scientific paper.","paper":"The report had to be written in English, following the format of a scientific paper.","background":"We described the background, the design process, the experimental method, the results and the limitations.","experimental":"We described the background, the design process, the experimental method, the results and the limitations.","method":"We described the background, the design process, the experimental method, the results and the limitations.","insist":"Professor Demir insisted that we discuss our failures honestly.","reader":"\"Readers learn as much from what did not work,\" she explained, \"as from what did.\"","revise":"We revised the report four times before submitting it.","submit":"We revised the report four times before submitting it."},"fm":{"insist":"insisted","reader":"readers","revise":"revised","submit":"submitting"}},{"id":142,"lv":"B2","n":23,"title":"Job Applications","tr":"İş başvuruları","text":"Meanwhile, I had to think about my career. Selin, my former supervisor, informed me that the bus company had an opening for a junior battery engineer. At the same time, Professor Demir encouraged me to apply for a master's programme abroad. I felt torn. The job offered security and practical experience, whereas a master's degree would deepen my knowledge and open doors to research. I decided to apply for both and then make a decision.","words":["meanwhile","career","former","inform","opening","junior","master","programme","tear","practical","whereas","deepen","knowledge","decision"],"ex":{"meanwhile":"Meanwhile, I had to think about my career.","career":"Meanwhile, I had to think about my career.","former":"Selin, my former supervisor, informed me that the bus company had an opening for a junior battery engineer.","inform":"Selin, my former supervisor, informed me that the bus company had an opening for a junior battery engineer.","opening":"Selin, my former supervisor, informed me that the bus company had an opening for a junior battery engineer.","junior":"Selin, my former supervisor, informed me that the bus company had an opening for a junior battery engineer.","master":"At the same time, Professor Demir encouraged me to apply for a master's programme abroad.","programme":"At the same time, Professor Demir encouraged me to apply for a master's programme abroad.","tear":"I felt torn.","practical":"The job offered security and practical experience, whereas a master's degree would deepen my knowledge and open doors to research.","whereas":"The job offered security and practical experience, whereas a master's degree would deepen my knowledge and open doors to research.","deepen":"The job offered security and practical experience, whereas a master's degree would deepen my knowledge and open doors to research.","knowledge":"The job offered security and practical experience, whereas a master's degree would deepen my knowledge and open doors to research.","decision":"I decided to apply for both and then make a decision."},"fm":{"inform":"informed","tear":"torn"}},{"id":143,"lv":"B2","n":24,"title":"The Master's Application","tr":"Yüksek lisans başvurusu","text":"The master's applications required a statement of purpose, two letters of recommendation and an English language certificate. I took the language exam in February and achieved a score well above the minimum requirement, which was a great relief. In my statement, I described how my internship and the village project had shaped my interest in affordable energy solutions. Selin and Professor Demir kindly agreed to write my recommendation letters.","words":["statement","purpose","recommendation","february","minimum","relief","shape","affordable","kindly"],"ex":{"statement":"The master's applications required a statement of purpose, two letters of recommendation and an English language certificate.","purpose":"The master's applications required a statement of purpose, two letters of recommendation and an English language certificate.","recommendation":"The master's applications required a statement of purpose, two letters of recommendation and an English language certificate.","february":"I took the language exam in February and achieved a score well above the minimum requirement, which was a great relief.","minimum":"I took the language exam in February and achieved a score well above the minimum requirement, which was a great relief.","relief":"I took the language exam in February and achieved a score well above the minimum requirement, which was a great relief.","shape":"In my statement, I described how my internship and the village project had shaped my interest in affordable energy solutions.","affordable":"In my statement, I described how my internship and the village project had shaped my interest in affordable energy solutions.","kindly":"Selin and Professor Demir kindly agreed to write my recommendation letters."},"fm":{"shape":"shaped"}},{"id":144,"lv":"B2","n":25,"title":"An Offer and an Acceptance","tr":"Bir teklif ve bir kabul","text":"In April, two pieces of news arrived in the same week. The bus company offered me the junior engineer position, and a university in the Netherlands accepted me for a two-year master's programme in sustainable energy, with a partial scholarship. Instead of feeling happy, I felt anxious. Whichever option I chose, I would lose something valuable. I spent several sleepless nights weighing the advantages and disadvantages.","words":["april","piece","partial","scholarship","feeling","whichever","option","valuable","sleepless","weigh","disadvantage"],"ex":{"april":"In April, two pieces of news arrived in the same week.","piece":"In April, two pieces of news arrived in the same week.","partial":"The bus company offered me the junior engineer position, and a university in the Netherlands accepted me for a two-year master's programme in sustainable energy, with a partial scholarship.","scholarship":"The bus company offered me the junior engineer position, and a university in the Netherlands accepted me for a two-year master's programme in sustainable energy, with a partial scholarship.","feeling":"Instead of feeling happy, I felt anxious.","whichever":"Whichever option I chose, I would lose something valuable.","option":"Whichever option I chose, I would lose something valuable.","valuable":"Whichever option I chose, I would lose something valuable.","sleepless":"I spent several sleepless nights weighing the advantages and disadvantages.","weigh":"I spent several sleepless nights weighing the advantages and disadvantages.","disadvantage":"I spent several sleepless nights weighing the advantages and disadvantages."},"fm":{"piece":"pieces","weigh":"weighing","disadvantage":"disadvantages"}},{"id":145,"lv":"B2","n":26,"title":"A Difficult Decision","tr":"Zor bir karar","text":"Eventually, I discussed the dilemma with Selin herself. To my surprise, she encouraged me to choose the master's degree. She said that the company would still need good engineers in two years, and that international experience would make me more valuable. My parents were worried about the cost, but the scholarship covered my tuition fees, and I had savings from my internship. I accepted the offer from the Netherlands.","words":["dilemma","herself","surprise","tuition","fee","savings"],"ex":{"dilemma":"Eventually, I discussed the dilemma with Selin herself.","herself":"Eventually, I discussed the dilemma with Selin herself.","surprise":"To my surprise, she encouraged me to choose the master's degree.","tuition":"My parents were worried about the cost, but the scholarship covered my tuition fees, and I had savings from my internship.","fee":"My parents were worried about the cost, but the scholarship covered my tuition fees, and I had savings from my internship.","savings":"My parents were worried about the cost, but the scholarship covered my tuition fees, and I had savings from my internship."},"fm":{"fee":"fees"}},{"id":146,"lv":"B2","n":27,"title":"The Graduation Ceremony","tr":"Mezuniyet töreni","text":"In June, I graduated with honours. The ceremony took place in the university stadium, under a bright sun. My parents, Ayşe and Mert sat in the audience, and even my grandmother made the long journey from the village. When my name was called, I could hear Mert shouting. Afterwards, we took countless photos. My grandmother held my diploma carefully, as if it were made of glass.","words":["honour","ceremony","bright","sun","audience","journey","afterwards","countless","diploma"],"ex":{"honour":"In June, I graduated with honours.","ceremony":"The ceremony took place in the university stadium, under a bright sun.","bright":"The ceremony took place in the university stadium, under a bright sun.","sun":"The ceremony took place in the university stadium, under a bright sun.","audience":"My parents, Ayşe and Mert sat in the audience, and even my grandmother made the long journey from the village.","journey":"My parents, Ayşe and Mert sat in the audience, and even my grandmother made the long journey from the village.","afterwards":"Afterwards, we took countless photos.","countless":"Afterwards, we took countless photos.","diploma":"My grandmother held my diploma carefully, as if it were made of glass."},"fm":{"honour":"honours"}},{"id":147,"lv":"B2","n":28,"title":"Saying Farewell","tr":"Veda etmek","text":"The weeks after graduation were full of farewells. Can had decided to stay in Ankara and start working for a defence company. Zehra had found a job in Istanbul, and Burak was going to start his own small business repairing drones. We met one last time at our favourite café near the campus. We promised to stay in touch, although we all knew that our lives were about to change significantly.","words":["defence","business","drone","café","campus","touch","significantly"],"ex":{"defence":"Can had decided to stay in Ankara and start working for a defence company.","business":"Zehra had found a job in Istanbul, and Burak was going to start his own small business repairing drones.","drone":"Zehra had found a job in Istanbul, and Burak was going to start his own small business repairing drones.","café":"We met one last time at our favourite café near the campus.","campus":"We met one last time at our favourite café near the campus.","touch":"We promised to stay in touch, although we all knew that our lives were about to change significantly.","significantly":"We promised to stay in touch, although we all knew that our lives were about to change significantly."},"fm":{"drone":"drones"}},{"id":148,"lv":"B2","n":29,"title":"Preparing for the Netherlands","tr":"Hollanda'ya hazırlık","text":"Preparing to move abroad involved a surprising amount of bureaucracy. I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns. After weeks of searching online, I found a small room in a student house. Mrs Wilson, with whom I still exchanged emails, sent me practical advice about living in Northern Europe, including the importance of a good waterproof jacket.","words":["bureaucracy","residence","permit","health","insurance","accommodation","notoriously","town","whom","exchange","northern","importance","waterproof"],"ex":{"bureaucracy":"Preparing to move abroad involved a surprising amount of bureaucracy.","residence":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","permit":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","health":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","insurance":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","accommodation":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","notoriously":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","town":"I needed a residence permit, health insurance and accommodation, which is notoriously hard to find in Dutch university towns.","whom":"Mrs Wilson, with whom I still exchanged emails, sent me practical advice about living in Northern Europe, including the importance of a good waterproof jacket.","exchange":"Mrs Wilson, with whom I still exchanged emails, sent me practical advice about living in Northern Europe, including the importance of a good waterproof jacket.","northern":"Mrs Wilson, with whom I still exchanged emails, sent me practical advice about living in Northern Europe, including the importance of a good waterproof jacket.","importance":"Mrs Wilson, with whom I still exchanged emails, sent me practical advice about living in Northern Europe, including the importance of a good waterproof jacket.","waterproof":"Mrs Wilson, with whom I still exchanged emails, sent me practical advice about living in Northern Europe, including the importance of a good waterproof jacket."},"fm":{"town":"towns","exchange":"exchanged"}},{"id":149,"lv":"B2","n":30,"title":"A New Country","tr":"Yeni bir ülke","text":"I arrived in the Netherlands at the end of August. My first impression was that everything was flat and orderly. Bicycles were everywhere, far outnumbering cars in the town centre. I bought a second-hand bicycle on my first day, as my housemates told me it was essential. Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine.","words":["impression","orderly","bicycle","outnumber","housemate","essential","cycle","traffic","barely","initially","terrifying","routine"],"ex":{"impression":"My first impression was that everything was flat and orderly.","orderly":"My first impression was that everything was flat and orderly.","bicycle":"Bicycles were everywhere, far outnumbering cars in the town centre.","outnumber":"Bicycles were everywhere, far outnumbering cars in the town centre.","housemate":"I bought a second-hand bicycle on my first day, as my housemates told me it was essential.","essential":"I bought a second-hand bicycle on my first day, as my housemates told me it was essential.","cycle":"Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine.","traffic":"Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine.","barely":"Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine.","initially":"Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine.","terrifying":"Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine.","routine":"Cycling in the rain, with traffic rules I barely understood, was initially terrifying, but within a week it had become part of my daily routine."},"fm":{"bicycle":"bicycles","outnumber":"outnumbering","housemate":"housemates","cycle":"cycling"}},{"id":150,"lv":"B2","n":31,"title":"Culture Shock","tr":"Kültür şoku","text":"Despite my previous experience in London, I experienced a certain amount of culture shock. Dutch people are famously direct, and at first I sometimes interpreted their honesty as rudeness. In Turkey, we often soften criticism to protect someone's feelings. Gradually, I came to appreciate the Dutch style: when someone said my idea was not good, they also explained exactly why, which was genuinely helpful.","words":["despite","previous","certain","culture","shock","famously","interpret","rudeness","soften","criticism","protect","someone","gradually","appreciate"],"ex":{"despite":"Despite my previous experience in London, I experienced a certain amount of culture shock.","previous":"Despite my previous experience in London, I experienced a certain amount of culture shock.","certain":"Despite my previous experience in London, I experienced a certain amount of culture shock.","culture":"Despite my previous experience in London, I experienced a certain amount of culture shock.","shock":"Despite my previous experience in London, I experienced a certain amount of culture shock.","famously":"Dutch people are famously direct, and at first I sometimes interpreted their honesty as rudeness.","interpret":"Dutch people are famously direct, and at first I sometimes interpreted their honesty as rudeness.","rudeness":"Dutch people are famously direct, and at first I sometimes interpreted their honesty as rudeness.","soften":"In Turkey, we often soften criticism to protect someone's feelings.","criticism":"In Turkey, we often soften criticism to protect someone's feelings.","protect":"In Turkey, we often soften criticism to protect someone's feelings.","someone":"In Turkey, we often soften criticism to protect someone's feelings.","gradually":"Gradually, I came to appreciate the Dutch style: when someone said my idea was not good, they also explained exactly why, which was genuinely helpful.","appreciate":"Gradually, I came to appreciate the Dutch style: when someone said my idea was not good, they also explained exactly why, which was genuinely helpful."},"fm":{"interpret":"interpreted"}},{"id":151,"lv":"B2","n":32,"title":"An International Classroom","tr":"Uluslararası sınıf","text":"My master's class consisted of thirty students from nineteen countries. In group projects, these differences were both a challenge and a strength. Some students expected the group leader to make decisions, while others assumed that every decision should be discussed by everyone. We learned to agree on working methods at the very beginning of each project. This experience taught me more about teamwork than any lecture could have done.","words":["consist","nineteen","difference","leader"],"ex":{"consist":"My master's class consisted of thirty students from nineteen countries.","nineteen":"My master's class consisted of thirty students from nineteen countries.","difference":"In group projects, these differences were both a challenge and a strength.","leader":"Some students expected the group leader to make decisions, while others assumed that every decision should be discussed by everyone."},"fm":{"consist":"consisted","difference":"differences"}},{"id":152,"lv":"B2","n":33,"title":"Visiting a Wind Farm","tr":"Rüzgâr çiftliği ziyareti","text":"In our first semester, we visited an offshore wind farm in the North Sea. We travelled by boat for two hours, and I struggled with seasickness the whole time. Nevertheless, seeing the giant turbines up close was breathtaking. Each blade was longer than a football field. An engineer explained how the turbines were maintained in harsh weather and how their electricity reached the mainland through cables buried under the seabed.","words":["offshore","north","struggle","seasickness","giant","breathtaking","maintain","harsh","mainland","bury","seabed"],"ex":{"offshore":"In our first semester, we visited an offshore wind farm in the North Sea.","north":"In our first semester, we visited an offshore wind farm in the North Sea.","struggle":"We travelled by boat for two hours, and I struggled with seasickness the whole time.","seasickness":"We travelled by boat for two hours, and I struggled with seasickness the whole time.","giant":"Nevertheless, seeing the giant turbines up close was breathtaking.","breathtaking":"Nevertheless, seeing the giant turbines up close was breathtaking.","maintain":"An engineer explained how the turbines were maintained in harsh weather and how their electricity reached the mainland through cables buried under the seabed.","harsh":"An engineer explained how the turbines were maintained in harsh weather and how their electricity reached the mainland through cables buried under the seabed.","mainland":"An engineer explained how the turbines were maintained in harsh weather and how their electricity reached the mainland through cables buried under the seabed.","bury":"An engineer explained how the turbines were maintained in harsh weather and how their electricity reached the mainland through cables buried under the seabed.","seabed":"An engineer explained how the turbines were maintained in harsh weather and how their electricity reached the mainland through cables buried under the seabed."},"fm":{"struggle":"struggled","maintain":"maintained","bury":"buried"}},{"id":153,"lv":"B2","n":34,"title":"Smart Grids","tr":"Akıllı şebekeler","text":"One of my favourite courses dealt with smart grids. Traditional electricity networks were designed for power to flow in one direction, from large power stations to consumers. Today, however, millions of households produce their own electricity with solar panels and sometimes store it in batteries. A smart grid uses sensors, communication and software to balance supply and demand in real time. I found the subject fascinating, as it combined everything I had studied.","words":["smart","grid","direction","consumer","million","communication","supply","fascinating"],"ex":{"smart":"One of my favourite courses dealt with smart grids.","grid":"One of my favourite courses dealt with smart grids.","direction":"Traditional electricity networks were designed for power to flow in one direction, from large power stations to consumers.","consumer":"Traditional electricity networks were designed for power to flow in one direction, from large power stations to consumers.","million":"Today, however, millions of households produce their own electricity with solar panels and sometimes store it in batteries.","communication":"A smart grid uses sensors, communication and software to balance supply and demand in real time.","supply":"A smart grid uses sensors, communication and software to balance supply and demand in real time.","fascinating":"I found the subject fascinating, as it combined everything I had studied."},"fm":{"grid":"grids","consumer":"consumers","million":"millions"}},{"id":154,"lv":"B2","n":35,"title":"News from the Village","tr":"Köyden haber","text":"In December, I received a message from Osman's grandson with photos of the solar heater covered in snow. To everyone's delight, the system was still working, although less effectively in winter. He mentioned that three other families had copied our design using their own money and materials. This news meant more to me than any grade. Our idea was spreading without our involvement, which is perhaps the best sign of success.","words":["effectively","mention","copy","grade","spread","involvement","perhaps","sign","success"],"ex":{"effectively":"To everyone's delight, the system was still working, although less effectively in winter.","mention":"He mentioned that three other families had copied our design using their own money and materials.","copy":"He mentioned that three other families had copied our design using their own money and materials.","grade":"This news meant more to me than any grade.","spread":"Our idea was spreading without our involvement, which is perhaps the best sign of success.","involvement":"Our idea was spreading without our involvement, which is perhaps the best sign of success.","perhaps":"Our idea was spreading without our involvement, which is perhaps the best sign of success.","sign":"Our idea was spreading without our involvement, which is perhaps the best sign of success.","success":"Our idea was spreading without our involvement, which is perhaps the best sign of success."},"fm":{"mention":"mentioned","copy":"copied","spread":"spreading"}},{"id":155,"lv":"B2","n":36,"title":"A Part-Time Job","tr":"Yarı zamanlı iş","text":"To cover my living expenses, I found a part-time job as a research assistant in a laboratory studying heat pumps. Heat pumps move heat from the outside air or ground into buildings, using electricity far more efficiently than conventional heaters. My job involved preparing experiments and processing measurement data. It was not glamorous work, but I learned laboratory skills and got to know the researchers, which later proved very valuable.","words":["expense","assistant","laboratory","ground","conventional","experiment","glamorous"],"ex":{"expense":"To cover my living expenses, I found a part-time job as a research assistant in a laboratory studying heat pumps.","assistant":"To cover my living expenses, I found a part-time job as a research assistant in a laboratory studying heat pumps.","laboratory":"To cover my living expenses, I found a part-time job as a research assistant in a laboratory studying heat pumps.","ground":"Heat pumps move heat from the outside air or ground into buildings, using electricity far more efficiently than conventional heaters.","conventional":"Heat pumps move heat from the outside air or ground into buildings, using electricity far more efficiently than conventional heaters.","experiment":"My job involved preparing experiments and processing measurement data.","glamorous":"It was not glamorous work, but I learned laboratory skills and got to know the researchers, which later proved very valuable."},"fm":{"expense":"expenses","experiment":"experiments"}},{"id":156,"lv":"B2","n":37,"title":"Loneliness","tr":"Yalnızlık","text":"The Dutch winter was dark, wet and long. In January, the sun set before five o'clock, and I began to feel lonely and homesick. I missed my family, Turkish food and the sunny winter days of Ankara. A housemate from Greece noticed that I was withdrawn and invited me to join a running group. Exercising with others and having a regular social activity gradually lifted my mood. I learned that asking for support is a strength, not a weakness.","words":["january","lonely","homesick","withdraw","exercise","regular","activity","mood","weakness"],"ex":{"january":"In January, the sun set before five o'clock, and I began to feel lonely and homesick.","lonely":"In January, the sun set before five o'clock, and I began to feel lonely and homesick.","homesick":"In January, the sun set before five o'clock, and I began to feel lonely and homesick.","withdraw":"A housemate from Greece noticed that I was withdrawn and invited me to join a running group.","exercise":"Exercising with others and having a regular social activity gradually lifted my mood.","regular":"Exercising with others and having a regular social activity gradually lifted my mood.","activity":"Exercising with others and having a regular social activity gradually lifted my mood.","mood":"Exercising with others and having a regular social activity gradually lifted my mood.","weakness":"I learned that asking for support is a strength, not a weakness."},"fm":{"withdraw":"withdrawn","exercise":"exercising"}},{"id":157,"lv":"B2","n":38,"title":"A Conference","tr":"Bir konferans","text":"In the spring, my supervisor at the laboratory suggested that I present a poster about our village project at a student conference. Preparing the poster forced me to summarise two years of work on a single page. At the conference, dozens of people stopped to ask questions. A researcher from Kenya told me about a similar project in East Africa, and we exchanged contact details. I realised that the problems we had faced were shared around the world.","words":["poster","conference","summarise","page","dozen","east","detail"],"ex":{"poster":"In the spring, my supervisor at the laboratory suggested that I present a poster about our village project at a student conference.","conference":"In the spring, my supervisor at the laboratory suggested that I present a poster about our village project at a student conference.","summarise":"Preparing the poster forced me to summarise two years of work on a single page.","page":"Preparing the poster forced me to summarise two years of work on a single page.","dozen":"At the conference, dozens of people stopped to ask questions.","east":"A researcher from Kenya told me about a similar project in East Africa, and we exchanged contact details.","detail":"A researcher from Kenya told me about a similar project in East Africa, and we exchanged contact details."},"fm":{"dozen":"dozens","detail":"details"}},{"id":158,"lv":"B2","n":39,"title":"The Thesis Topic","tr":"Tez konusu","text":"By the end of my first year, I had to choose a topic for my master's thesis. After discussions with my supervisor, I decided to study how heat pumps and thermal storage could be combined to make heating more affordable in regions with cold winters and limited incomes. The topic connected my experiences from Bursa, the village and the Netherlands. For the first time, my scattered interests seemed to form a single, coherent direction.","words":["topic","thesis","scattered","coherent"],"ex":{"topic":"By the end of my first year, I had to choose a topic for my master's thesis.","thesis":"By the end of my first year, I had to choose a topic for my master's thesis.","scattered":"For the first time, my scattered interests seemed to form a single, coherent direction.","coherent":"For the first time, my scattered interests seemed to form a single, coherent direction."},"fm":{}},{"id":159,"lv":"B2","n":40,"title":"Looking Back","tr":"Geriye bakmak","text":"On a warm evening in June, I cycled along a canal and reflected on how much my life had changed. Five years earlier, I had been a nervous first-year student who could barely introduce himself in English. Now I was conducting research in a foreign country and discussing complex ideas with people from all over the world. I felt grateful to everyone who had helped me, and curious about what the future would bring.","words":["canal","reflect","conduct"],"ex":{"canal":"On a warm evening in June, I cycled along a canal and reflected on how much my life had changed.","reflect":"On a warm evening in June, I cycled along a canal and reflected on how much my life had changed.","conduct":"Now I was conducting research in a foreign country and discussing complex ideas with people from all over the world."},"fm":{"reflect":"reflected","conduct":"conducting"}},{"id":160,"lv":"C1","n":1,"title":"Reviewing the Literature","tr":"Literatür taraması","text":"The first stage of my thesis was a thorough literature review. My supervisor, Dr Visser, insisted that I read widely before formulating any hypothesis. Over two months, I worked through more than a hundred papers on heat pumps, thermal storage and energy poverty. Many of them contradicted one another, which was initially bewildering. Gradually, however, I learned to evaluate the methodology of each study rather than simply accepting its conclusions at face value.","words":["stage","thorough","literature","review","widely","formulate","hypothesis","poverty","contradict","bewildering","evaluate","methodology","rather","simply","value"],"ex":{"stage":"The first stage of my thesis was a thorough literature review.","thorough":"The first stage of my thesis was a thorough literature review.","literature":"The first stage of my thesis was a thorough literature review.","review":"The first stage of my thesis was a thorough literature review.","widely":"My supervisor, Dr Visser, insisted that I read widely before formulating any hypothesis.","formulate":"My supervisor, Dr Visser, insisted that I read widely before formulating any hypothesis.","hypothesis":"My supervisor, Dr Visser, insisted that I read widely before formulating any hypothesis.","poverty":"Over two months, I worked through more than a hundred papers on heat pumps, thermal storage and energy poverty.","contradict":"Many of them contradicted one another, which was initially bewildering.","bewildering":"Many of them contradicted one another, which was initially bewildering.","evaluate":"Gradually, however, I learned to evaluate the methodology of each study rather than simply accepting its conclusions at face value.","methodology":"Gradually, however, I learned to evaluate the methodology of each study rather than simply accepting its conclusions at face value.","rather":"Gradually, however, I learned to evaluate the methodology of each study rather than simply accepting its conclusions at face value.","simply":"Gradually, however, I learned to evaluate the methodology of each study rather than simply accepting its conclusions at face value.","value":"Gradually, however, I learned to evaluate the methodology of each study rather than simply accepting its conclusions at face value."},"fm":{"formulate":"formulating","contradict":"contradicted"}},{"id":161,"lv":"C1","n":2,"title":"Formulating a Research Question","tr":"Araştırma sorusu","text":"Dr Visser repeatedly emphasised that a good thesis rests on a precise research question. My initial question, whether heat pumps could make heating affordable, was far too broad. After several frustrating iterations, I narrowed it down considerably: under what conditions does combining a small heat pump with a water storage tank reduce heating costs for low-income households in continental climates? The revised question was less ambitious, but it was answerable within the time available.","words":["repeatedly","precise","initial","broad","frustrating","iteration","considerably","continental","answerable","available"],"ex":{"repeatedly":"Dr Visser repeatedly emphasised that a good thesis rests on a precise research question.","precise":"Dr Visser repeatedly emphasised that a good thesis rests on a precise research question.","initial":"My initial question, whether heat pumps could make heating affordable, was far too broad.","broad":"My initial question, whether heat pumps could make heating affordable, was far too broad.","frustrating":"After several frustrating iterations, I narrowed it down considerably: under what conditions does combining a small heat pump with a water storage tank reduce heating costs for low-income households in continental climates?","iteration":"After several frustrating iterations, I narrowed it down considerably: under what conditions does combining a small heat pump with a water storage tank reduce heating costs for low-income households in continental climates?","considerably":"After several frustrating iterations, I narrowed it down considerably: under what conditions does combining a small heat pump with a water storage tank reduce heating costs for low-income households in continental climates?","continental":"After several frustrating iterations, I narrowed it down considerably: under what conditions does combining a small heat pump with a water storage tank reduce heating costs for low-income households in continental climates?","answerable":"The revised question was less ambitious, but it was answerable within the time available.","available":"The revised question was less ambitious, but it was answerable within the time available."},"fm":{"iteration":"iterations"}},{"id":162,"lv":"C1","n":3,"title":"Building a Model","tr":"Bir model kurmak","text":"To answer the question, I developed a computational model of a typical house, including its walls, windows, heating system and occupants' behaviour. Calibrating the model was painstaking. I compared its predictions with measured data from the laboratory and adjusted uncertain parameters until the discrepancies became acceptably small. Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","words":["computational","occupant","behaviour","calibrate","painstaking","adjust","uncertain","parameter","discrepancy","acceptably","meticulously","reviewer","scrutinise","might","otherwise","forget","reasoning"],"ex":{"computational":"To answer the question, I developed a computational model of a typical house, including its walls, windows, heating system and occupants' behaviour.","occupant":"To answer the question, I developed a computational model of a typical house, including its walls, windows, heating system and occupants' behaviour.","behaviour":"To answer the question, I developed a computational model of a typical house, including its walls, windows, heating system and occupants' behaviour.","calibrate":"Calibrating the model was painstaking.","painstaking":"Calibrating the model was painstaking.","adjust":"I compared its predictions with measured data from the laboratory and adjusted uncertain parameters until the discrepancies became acceptably small.","uncertain":"I compared its predictions with measured data from the laboratory and adjusted uncertain parameters until the discrepancies became acceptably small.","parameter":"I compared its predictions with measured data from the laboratory and adjusted uncertain parameters until the discrepancies became acceptably small.","discrepancy":"I compared its predictions with measured data from the laboratory and adjusted uncertain parameters until the discrepancies became acceptably small.","acceptably":"I compared its predictions with measured data from the laboratory and adjusted uncertain parameters until the discrepancies became acceptably small.","meticulously":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","reviewer":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","scrutinise":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","might":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","otherwise":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","forget":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning.","reasoning":"Throughout this process, I documented every assumption meticulously, knowing that reviewers would scrutinise them and that I might otherwise forget my own reasoning."},"fm":{"occupant":"occupants","calibrate":"calibrating","adjust":"adjusted","parameter":"parameters","discrepancy":"discrepancies","reviewer":"reviewers"}},{"id":163,"lv":"C1","n":4,"title":"Dealing with Uncertainty","tr":"Belirsizlikle başa çıkmak","text":"One of the most valuable concepts I encountered was uncertainty analysis. Rather than producing a single estimate of energy savings, I ran thousands of simulations with varying inputs, such as electricity prices and insulation quality. The outcome was a range of plausible results rather than one deceptively precise number. Presenting results this way felt less impressive at first, yet it was considerably more honest and, ultimately, more useful to decision-makers.","words":["concept","encounter","uncertainty","analysis","vary","input","outcome","range","plausible","deceptively","impressive","yet","honest","ultimately","decision-maker"],"ex":{"concept":"One of the most valuable concepts I encountered was uncertainty analysis.","encounter":"One of the most valuable concepts I encountered was uncertainty analysis.","uncertainty":"One of the most valuable concepts I encountered was uncertainty analysis.","analysis":"One of the most valuable concepts I encountered was uncertainty analysis.","vary":"Rather than producing a single estimate of energy savings, I ran thousands of simulations with varying inputs, such as electricity prices and insulation quality.","input":"Rather than producing a single estimate of energy savings, I ran thousands of simulations with varying inputs, such as electricity prices and insulation quality.","outcome":"The outcome was a range of plausible results rather than one deceptively precise number.","range":"The outcome was a range of plausible results rather than one deceptively precise number.","plausible":"The outcome was a range of plausible results rather than one deceptively precise number.","deceptively":"The outcome was a range of plausible results rather than one deceptively precise number.","impressive":"Presenting results this way felt less impressive at first, yet it was considerably more honest and, ultimately, more useful to decision-makers.","yet":"Presenting results this way felt less impressive at first, yet it was considerably more honest and, ultimately, more useful to decision-makers.","honest":"Presenting results this way felt less impressive at first, yet it was considerably more honest and, ultimately, more useful to decision-makers.","ultimately":"Presenting results this way felt less impressive at first, yet it was considerably more honest and, ultimately, more useful to decision-makers.","decision-maker":"Presenting results this way felt less impressive at first, yet it was considerably more honest and, ultimately, more useful to decision-makers."},"fm":{"concept":"concepts","encounter":"encountered","vary":"varying","input":"inputs","decision-maker":"decision-makers"}},{"id":164,"lv":"C1","n":5,"title":"A Counterintuitive Finding","tr":"Şaşırtıcı bir bulgu","text":"The simulations revealed something counterintuitive. In poorly insulated houses, adding a heat pump alone yielded only modest savings, because most of the heat simply escaped through the walls. However, when basic insulation was combined with a smaller, cheaper heat pump, the total investment decreased and the savings increased substantially. In other words, the sequence of interventions mattered enormously. Insulating first and electrifying second proved to be the most cost-effective strategy.","words":["reveal","counterintuitive","poorly","yield","investment","decrease","substantially","sequence","intervention","matter","enormously","electrify","strategy"],"ex":{"reveal":"The simulations revealed something counterintuitive.","counterintuitive":"The simulations revealed something counterintuitive.","poorly":"In poorly insulated houses, adding a heat pump alone yielded only modest savings, because most of the heat simply escaped through the walls.","yield":"In poorly insulated houses, adding a heat pump alone yielded only modest savings, because most of the heat simply escaped through the walls.","investment":"However, when basic insulation was combined with a smaller, cheaper heat pump, the total investment decreased and the savings increased substantially.","decrease":"However, when basic insulation was combined with a smaller, cheaper heat pump, the total investment decreased and the savings increased substantially.","substantially":"However, when basic insulation was combined with a smaller, cheaper heat pump, the total investment decreased and the savings increased substantially.","sequence":"In other words, the sequence of interventions mattered enormously.","intervention":"In other words, the sequence of interventions mattered enormously.","matter":"In other words, the sequence of interventions mattered enormously.","enormously":"In other words, the sequence of interventions mattered enormously.","electrify":"Insulating first and electrifying second proved to be the most cost-effective strategy.","strategy":"Insulating first and electrifying second proved to be the most cost-effective strategy."},"fm":{"reveal":"revealed","yield":"yielded","decrease":"decreased","intervention":"interventions","matter":"mattered","electrify":"electrifying"}},{"id":165,"lv":"C1","n":6,"title":"A Disagreement with My Supervisor","tr":"Danışmanla anlaşmazlık","text":"When I presented these findings, Dr Visser was initially skeptical. She suspected that the result might be an artefact of the model rather than a genuine effect. Although I was disappointed, I recognised that her skepticism was entirely legitimate. She proposed a test: if the effect was real, it should persist even when the most uncertain parameters were varied substantially. I spent another month conducting these sensitivity tests, and the conclusion held.","words":["suspect","artefact","effect","disappointed","skepticism","entirely","legitimate","propose","persist","sensitivity"],"ex":{"suspect":"She suspected that the result might be an artefact of the model rather than a genuine effect.","artefact":"She suspected that the result might be an artefact of the model rather than a genuine effect.","effect":"She suspected that the result might be an artefact of the model rather than a genuine effect.","disappointed":"Although I was disappointed, I recognised that her skepticism was entirely legitimate.","skepticism":"Although I was disappointed, I recognised that her skepticism was entirely legitimate.","entirely":"Although I was disappointed, I recognised that her skepticism was entirely legitimate.","legitimate":"Although I was disappointed, I recognised that her skepticism was entirely legitimate.","propose":"She proposed a test: if the effect was real, it should persist even when the most uncertain parameters were varied substantially.","persist":"She proposed a test: if the effect was real, it should persist even when the most uncertain parameters were varied substantially.","sensitivity":"I spent another month conducting these sensitivity tests, and the conclusion held."},"fm":{"suspect":"suspected","propose":"proposed"}},{"id":166,"lv":"C1","n":7,"title":"Research Ethics","tr":"Araştırma etiği","text":"To validate the model, I wanted to monitor real households, which raised ethical questions I had not previously considered. Collecting detailed data on when people are at home could reveal sensitive information about their daily lives. I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely. The process was bureaucratic, but I came to regard it as essential.","words":["validate","raise","ethical","previously","consider","detailed","sensitive","ethics","committee","participant","consent","anonymise","securely","bureaucratic","regard"],"ex":{"validate":"To validate the model, I wanted to monitor real households, which raised ethical questions I had not previously considered.","raise":"To validate the model, I wanted to monitor real households, which raised ethical questions I had not previously considered.","ethical":"To validate the model, I wanted to monitor real households, which raised ethical questions I had not previously considered.","previously":"To validate the model, I wanted to monitor real households, which raised ethical questions I had not previously considered.","consider":"To validate the model, I wanted to monitor real households, which raised ethical questions I had not previously considered.","detailed":"Collecting detailed data on when people are at home could reveal sensitive information about their daily lives.","sensitive":"Collecting detailed data on when people are at home could reveal sensitive information about their daily lives.","ethics":"I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely.","committee":"I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely.","participant":"I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely.","consent":"I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely.","anonymise":"I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely.","securely":"I had to submit a proposal to the university's ethics committee, explaining how participants would give informed consent and how their data would be anonymised and stored securely.","bureaucratic":"The process was bureaucratic, but I came to regard it as essential.","regard":"The process was bureaucratic, but I came to regard it as essential."},"fm":{"raise":"raised","consider":"considered","participant":"participants","anonymise":"anonymised"}},{"id":167,"lv":"C1","n":8,"title":"Fieldwork","tr":"Saha çalışması","text":"With the committee's approval, we installed sensors in twelve homes in a former mining town where many residents struggled to pay their energy bills. Visiting these households was humbling. Some elderly residents heated only one room throughout the winter and wore coats indoors. These encounters reminded me that behind every statistic on energy poverty are individuals making difficult trade-offs between warmth, food and other necessities.","words":["approval","mining","resident","bill","humbling","indoors","statistic","individual","trade-off","warmth","necessity"],"ex":{"approval":"With the committee's approval, we installed sensors in twelve homes in a former mining town where many residents struggled to pay their energy bills.","mining":"With the committee's approval, we installed sensors in twelve homes in a former mining town where many residents struggled to pay their energy bills.","resident":"With the committee's approval, we installed sensors in twelve homes in a former mining town where many residents struggled to pay their energy bills.","bill":"With the committee's approval, we installed sensors in twelve homes in a former mining town where many residents struggled to pay their energy bills.","humbling":"Visiting these households was humbling.","indoors":"Some elderly residents heated only one room throughout the winter and wore coats indoors.","statistic":"These encounters reminded me that behind every statistic on energy poverty are individuals making difficult trade-offs between warmth, food and other necessities.","individual":"These encounters reminded me that behind every statistic on energy poverty are individuals making difficult trade-offs between warmth, food and other necessities.","trade-off":"These encounters reminded me that behind every statistic on energy poverty are individuals making difficult trade-offs between warmth, food and other necessities.","warmth":"These encounters reminded me that behind every statistic on energy poverty are individuals making difficult trade-offs between warmth, food and other necessities.","necessity":"These encounters reminded me that behind every statistic on energy poverty are individuals making difficult trade-offs between warmth, food and other necessities."},"fm":{"resident":"residents","bill":"bills","individual":"individuals","trade-off":"trade-offs","necessity":"necessities"}},{"id":168,"lv":"C1","n":9,"title":"What the Data Revealed","tr":"Verilerin söyledikleri","text":"The measured data broadly confirmed the model's predictions, although there were notable discrepancies. Occupants' behaviour proved far more variable than I had assumed. Some households opened windows while the heating was running, whereas others kept temperatures surprisingly low to save money. I concluded that technical solutions alone are insufficient; they must be accompanied by clear information and, ideally, by financial support that reaches the households most in need.","words":["broadly","confirm","notable","variable","conclude","insufficient","accompany","ideally","financial"],"ex":{"broadly":"The measured data broadly confirmed the model's predictions, although there were notable discrepancies.","confirm":"The measured data broadly confirmed the model's predictions, although there were notable discrepancies.","notable":"The measured data broadly confirmed the model's predictions, although there were notable discrepancies.","variable":"Occupants' behaviour proved far more variable than I had assumed.","conclude":"I concluded that technical solutions alone are insufficient; they must be accompanied by clear information and, ideally, by financial support that reaches the households most in need.","insufficient":"I concluded that technical solutions alone are insufficient; they must be accompanied by clear information and, ideally, by financial support that reaches the households most in need.","accompany":"I concluded that technical solutions alone are insufficient; they must be accompanied by clear information and, ideally, by financial support that reaches the households most in need.","ideally":"I concluded that technical solutions alone are insufficient; they must be accompanied by clear information and, ideally, by financial support that reaches the households most in need.","financial":"I concluded that technical solutions alone are insufficient; they must be accompanied by clear information and, ideally, by financial support that reaches the households most in need."},"fm":{"confirm":"confirmed","conclude":"concluded","accompany":"accompanied"}},{"id":169,"lv":"C1","n":10,"title":"The First Paper","tr":"İlk makale","text":"Dr Visser suggested that we turn part of my thesis into a journal article. Writing for an academic journal demanded a level of precision and concision I had never practised before. Every claim had to be supported either by our own data or by references. We submitted the manuscript in March and, three months later, received the reviewers' comments. One reviewer was enthusiastic; the other was scathing, describing our methodology as inadequately justified.","words":["journal","academic","level","precision","concision","claim","either","manuscript","comment","enthusiastic","scathing","inadequately","justify"],"ex":{"journal":"Dr Visser suggested that we turn part of my thesis into a journal article.","academic":"Writing for an academic journal demanded a level of precision and concision I had never practised before.","level":"Writing for an academic journal demanded a level of precision and concision I had never practised before.","precision":"Writing for an academic journal demanded a level of precision and concision I had never practised before.","concision":"Writing for an academic journal demanded a level of precision and concision I had never practised before.","claim":"Every claim had to be supported either by our own data or by references.","either":"Every claim had to be supported either by our own data or by references.","manuscript":"We submitted the manuscript in March and, three months later, received the reviewers' comments.","comment":"We submitted the manuscript in March and, three months later, received the reviewers' comments.","enthusiastic":"One reviewer was enthusiastic; the other was scathing, describing our methodology as inadequately justified.","scathing":"One reviewer was enthusiastic; the other was scathing, describing our methodology as inadequately justified.","inadequately":"One reviewer was enthusiastic; the other was scathing, describing our methodology as inadequately justified.","justify":"One reviewer was enthusiastic; the other was scathing, describing our methodology as inadequately justified."},"fm":{"comment":"comments","justify":"justified"}},{"id":170,"lv":"C1","n":11,"title":"Responding to Criticism","tr":"Hakem eleştirisi","text":"My first instinct was to feel indignant about the harsh review. Dr Visser, however, advised me to set the comments aside for a few days and then reread them dispassionately. On closer inspection, several of the criticisms were valid. We performed additional analyses, rewrote the methods section and responded to each point courteously and in detail. The revised paper was accepted. The experience taught me that criticism, however painful, often improves the work.","words":["instinct","indignant","aside","reread","dispassionately","inspection","additional","rewrite","respond","courteously","painful"],"ex":{"instinct":"My first instinct was to feel indignant about the harsh review.","indignant":"My first instinct was to feel indignant about the harsh review.","aside":"Dr Visser, however, advised me to set the comments aside for a few days and then reread them dispassionately.","reread":"Dr Visser, however, advised me to set the comments aside for a few days and then reread them dispassionately.","dispassionately":"Dr Visser, however, advised me to set the comments aside for a few days and then reread them dispassionately.","inspection":"On closer inspection, several of the criticisms were valid.","additional":"We performed additional analyses, rewrote the methods section and responded to each point courteously and in detail.","rewrite":"We performed additional analyses, rewrote the methods section and responded to each point courteously and in detail.","respond":"We performed additional analyses, rewrote the methods section and responded to each point courteously and in detail.","courteously":"We performed additional analyses, rewrote the methods section and responded to each point courteously and in detail.","painful":"The experience taught me that criticism, however painful, often improves the work."},"fm":{"rewrite":"rewrote","respond":"responded"}},{"id":171,"lv":"C1","n":12,"title":"A PhD Offer","tr":"Doktora teklifi","text":"Shortly before I submitted my thesis, Dr Visser offered me a fully funded PhD position in her group. It was a flattering and tempting proposal. A doctorate would allow me to pursue the research questions that fascinated me and perhaps eventually to become an academic. Yet I hesitated. I had always intended to return to Turkey and contribute more directly to solving practical problems there. The decision weighed on me for weeks.","words":["shortly","fully","phd","flattering","tempting","doctorate","allow","pursue","fascinated","hesitate","contribute"],"ex":{"shortly":"Shortly before I submitted my thesis, Dr Visser offered me a fully funded PhD position in her group.","fully":"Shortly before I submitted my thesis, Dr Visser offered me a fully funded PhD position in her group.","phd":"Shortly before I submitted my thesis, Dr Visser offered me a fully funded PhD position in her group.","flattering":"It was a flattering and tempting proposal.","tempting":"It was a flattering and tempting proposal.","doctorate":"A doctorate would allow me to pursue the research questions that fascinated me and perhaps eventually to become an academic.","allow":"A doctorate would allow me to pursue the research questions that fascinated me and perhaps eventually to become an academic.","pursue":"A doctorate would allow me to pursue the research questions that fascinated me and perhaps eventually to become an academic.","fascinated":"A doctorate would allow me to pursue the research questions that fascinated me and perhaps eventually to become an academic.","hesitate":"Yet I hesitated.","contribute":"I had always intended to return to Turkey and contribute more directly to solving practical problems there."},"fm":{"hesitate":"hesitated"}},{"id":172,"lv":"C1","n":13,"title":"Weighing Values","tr":"Değerleri tartmak","text":"To clarify my thinking, I wrote down what I valued most: learning, impact, proximity to my family and financial stability. When I ranked these values honestly, impact and family came first. A PhD would maximise learning, but I suspected that I could achieve greater impact by applying existing knowledge rather than generating new knowledge. With considerable reluctance, I declined the offer, and Dr Visser, to her credit, respected my reasoning.","words":["clarify","proximity","stability","rank","maximise","generate","considerable","reluctance","decline","credit","respect"],"ex":{"clarify":"To clarify my thinking, I wrote down what I valued most: learning, impact, proximity to my family and financial stability.","proximity":"To clarify my thinking, I wrote down what I valued most: learning, impact, proximity to my family and financial stability.","stability":"To clarify my thinking, I wrote down what I valued most: learning, impact, proximity to my family and financial stability.","rank":"When I ranked these values honestly, impact and family came first.","maximise":"A PhD would maximise learning, but I suspected that I could achieve greater impact by applying existing knowledge rather than generating new knowledge.","generate":"A PhD would maximise learning, but I suspected that I could achieve greater impact by applying existing knowledge rather than generating new knowledge.","considerable":"With considerable reluctance, I declined the offer, and Dr Visser, to her credit, respected my reasoning.","reluctance":"With considerable reluctance, I declined the offer, and Dr Visser, to her credit, respected my reasoning.","decline":"With considerable reluctance, I declined the offer, and Dr Visser, to her credit, respected my reasoning.","credit":"With considerable reluctance, I declined the offer, and Dr Visser, to her credit, respected my reasoning.","respect":"With considerable reluctance, I declined the offer, and Dr Visser, to her credit, respected my reasoning."},"fm":{"rank":"ranked","generate":"generating","decline":"declined","respect":"respected"}},{"id":173,"lv":"C1","n":14,"title":"The Thesis Defence","tr":"Tez savunması","text":"My thesis defence took place in a small seminar room in front of a committee of three professors. The external examiner, a renowned specialist in building physics, asked probing questions about the limitations of my model. At one point, I had to admit that I did not know the answer, and I explained how I would investigate it. Afterwards, he told me that acknowledging uncertainty had impressed him more than any confident answer could have.","words":["external","examiner","renowned","probe","investigate","acknowledge","impress"],"ex":{"external":"The external examiner, a renowned specialist in building physics, asked probing questions about the limitations of my model.","examiner":"The external examiner, a renowned specialist in building physics, asked probing questions about the limitations of my model.","renowned":"The external examiner, a renowned specialist in building physics, asked probing questions about the limitations of my model.","probe":"The external examiner, a renowned specialist in building physics, asked probing questions about the limitations of my model.","investigate":"At one point, I had to admit that I did not know the answer, and I explained how I would investigate it.","acknowledge":"Afterwards, he told me that acknowledging uncertainty had impressed him more than any confident answer could have.","impress":"Afterwards, he told me that acknowledging uncertainty had impressed him more than any confident answer could have."},"fm":{"probe":"probing","acknowledge":"acknowledging","impress":"impressed"}},{"id":174,"lv":"C1","n":15,"title":"Returning to Turkey","tr":"Türkiye'ye dönüş","text":"I returned to Ankara with a master's degree, a published paper and a clear sense of purpose, but no job. Rather than joining a large company, I decided to explore whether our village project could become a sustainable social enterprise. This was a risky choice, and some relatives openly questioned my judgement. My father, however, supported me unreservedly. \"You have spent years preparing,\" he said. \"Now it is time to find out what you can build.\"","words":["publish","enterprise","risky","relative","openly","judgement","unreservedly"],"ex":{"publish":"I returned to Ankara with a master's degree, a published paper and a clear sense of purpose, but no job.","enterprise":"Rather than joining a large company, I decided to explore whether our village project could become a sustainable social enterprise.","risky":"This was a risky choice, and some relatives openly questioned my judgement.","relative":"This was a risky choice, and some relatives openly questioned my judgement.","openly":"This was a risky choice, and some relatives openly questioned my judgement.","judgement":"This was a risky choice, and some relatives openly questioned my judgement.","unreservedly":"My father, however, supported me unreservedly."},"fm":{"publish":"published","relative":"relatives"}},{"id":175,"lv":"C1","n":16,"title":"Founding a Venture","tr":"Bir girişim kurmak","text":"I contacted Zehra, who was growing restless in her corporate job, and proposed that we establish the enterprise together. After lengthy discussions, she agreed to join on a part-time basis. Our concept was to offer affordable packages combining insulation, solar water heating and, where appropriate, small heat pumps, installed by trained local technicians. We drafted a business plan, though neither of us had any formal training in management or finance.","words":["restless","corporate","establish","lengthy","basis","package","appropriate","neither","finance"],"ex":{"restless":"I contacted Zehra, who was growing restless in her corporate job, and proposed that we establish the enterprise together.","corporate":"I contacted Zehra, who was growing restless in her corporate job, and proposed that we establish the enterprise together.","establish":"I contacted Zehra, who was growing restless in her corporate job, and proposed that we establish the enterprise together.","lengthy":"After lengthy discussions, she agreed to join on a part-time basis.","basis":"After lengthy discussions, she agreed to join on a part-time basis.","package":"Our concept was to offer affordable packages combining insulation, solar water heating and, where appropriate, small heat pumps, installed by trained local technicians.","appropriate":"Our concept was to offer affordable packages combining insulation, solar water heating and, where appropriate, small heat pumps, installed by trained local technicians.","neither":"We drafted a business plan, though neither of us had any formal training in management or finance.","finance":"We drafted a business plan, though neither of us had any formal training in management or finance."},"fm":{"package":"packages"}},{"id":176,"lv":"C1","n":17,"title":"In Search of Finance","tr":"Finansman arayışı","text":"Securing finance proved exceptionally difficult. Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission. Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency. The sums were modest, but they enabled us to pilot our model in three villages.","words":["secure","exceptionally","reluctant","lend","track","investor","rapid","growth","incompatible","mission","obtain","combination","grant","development","foundation","loan","regional","agency","sum","enable"],"ex":{"secure":"Securing finance proved exceptionally difficult.","exceptionally":"Securing finance proved exceptionally difficult.","reluctant":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","lend":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","track":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","investor":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","rapid":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","growth":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","incompatible":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","mission":"Banks were reluctant to lend to a start-up without a track record, and conventional investors expected rapid growth and high returns, which were incompatible with our mission.","obtain":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","combination":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","grant":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","development":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","foundation":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","loan":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","regional":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","agency":"Eventually, we obtained a combination of a small grant from an international development foundation and an interest-free loan from a regional development agency.","sum":"The sums were modest, but they enabled us to pilot our model in three villages.","enable":"The sums were modest, but they enabled us to pilot our model in three villages."},"fm":{"secure":"securing","investor":"investors","obtain":"obtained","sum":"sums","enable":"enabled"}},{"id":177,"lv":"C1","n":18,"title":"Training Technicians","tr":"Teknisyen yetiştirmek","text":"A central element of our approach was training local technicians, so that the installations could be maintained without our presence. We recruited young people from the pilot villages, several of whom had left school early and had few employment prospects. Designing the training programme forced us to translate technical knowledge into practical, accessible instructions. Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","words":["element","approach","installation","presence","recruit","employment","prospect","translate","accessible","instruction","trainee","gain","confidence","rewarding","aspect","entire","venture"],"ex":{"element":"A central element of our approach was training local technicians, so that the installations could be maintained without our presence.","approach":"A central element of our approach was training local technicians, so that the installations could be maintained without our presence.","installation":"A central element of our approach was training local technicians, so that the installations could be maintained without our presence.","presence":"A central element of our approach was training local technicians, so that the installations could be maintained without our presence.","recruit":"We recruited young people from the pilot villages, several of whom had left school early and had few employment prospects.","employment":"We recruited young people from the pilot villages, several of whom had left school early and had few employment prospects.","prospect":"We recruited young people from the pilot villages, several of whom had left school early and had few employment prospects.","translate":"Designing the training programme forced us to translate technical knowledge into practical, accessible instructions.","accessible":"Designing the training programme forced us to translate technical knowledge into practical, accessible instructions.","instruction":"Designing the training programme forced us to translate technical knowledge into practical, accessible instructions.","trainee":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","gain":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","confidence":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","rewarding":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","aspect":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","entire":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture.","venture":"Watching our trainees gain confidence and skills became one of the most rewarding aspects of the entire venture."},"fm":{"installation":"installations","recruit":"recruited","prospect":"prospects","instruction":"instructions","trainee":"trainees","aspect":"aspects"}},{"id":178,"lv":"C1","n":19,"title":"The First Crisis","tr":"İlk kriz","text":"Our first winter brought an unexpected crisis. A batch of valves we had purchased from a new supplier failed in freezing temperatures, causing leaks in several houses. We could have blamed the supplier, but our customers had trusted us, not the supplier. We immediately replaced every faulty valve at our own expense, which nearly exhausted our funds. The incident was financially painful, yet it strengthened our reputation for reliability considerably.","words":["unexpected","crisis","valve","purchase","freezing","leak","blame","customer","exhausted","incident","financially","strengthen","reputation","reliability"],"ex":{"unexpected":"Our first winter brought an unexpected crisis.","crisis":"Our first winter brought an unexpected crisis.","valve":"A batch of valves we had purchased from a new supplier failed in freezing temperatures, causing leaks in several houses.","purchase":"A batch of valves we had purchased from a new supplier failed in freezing temperatures, causing leaks in several houses.","freezing":"A batch of valves we had purchased from a new supplier failed in freezing temperatures, causing leaks in several houses.","leak":"A batch of valves we had purchased from a new supplier failed in freezing temperatures, causing leaks in several houses.","blame":"We could have blamed the supplier, but our customers had trusted us, not the supplier.","customer":"We could have blamed the supplier, but our customers had trusted us, not the supplier.","exhausted":"We immediately replaced every faulty valve at our own expense, which nearly exhausted our funds.","incident":"The incident was financially painful, yet it strengthened our reputation for reliability considerably.","financially":"The incident was financially painful, yet it strengthened our reputation for reliability considerably.","strengthen":"The incident was financially painful, yet it strengthened our reputation for reliability considerably.","reputation":"The incident was financially painful, yet it strengthened our reputation for reliability considerably.","reliability":"The incident was financially painful, yet it strengthened our reputation for reliability considerably."},"fm":{"valve":"valves","purchase":"purchased","leak":"leaks","blame":"blamed","customer":"customers","strengthen":"strengthened"}},{"id":179,"lv":"C1","n":20,"title":"Learning from Failure","tr":"Ders çıkarmak","text":"After the crisis, Zehra and I conducted a thorough review to understand how it had happened. We discovered that, under pressure to reduce costs, we had skipped testing components in realistic conditions. We introduced a rigorous procedure: no new component would be installed until it had been tested through simulated freeze cycles. In retrospect, the failure was an invaluable, if expensive, lesson in the dangers of cutting corners.","words":["skip","component","realistic","rigorous","procedure","simulate","freeze","retrospect","invaluable","danger","corner"],"ex":{"skip":"We discovered that, under pressure to reduce costs, we had skipped testing components in realistic conditions.","component":"We discovered that, under pressure to reduce costs, we had skipped testing components in realistic conditions.","realistic":"We discovered that, under pressure to reduce costs, we had skipped testing components in realistic conditions.","rigorous":"We introduced a rigorous procedure: no new component would be installed until it had been tested through simulated freeze cycles.","procedure":"We introduced a rigorous procedure: no new component would be installed until it had been tested through simulated freeze cycles.","simulate":"We introduced a rigorous procedure: no new component would be installed until it had been tested through simulated freeze cycles.","freeze":"We introduced a rigorous procedure: no new component would be installed until it had been tested through simulated freeze cycles.","retrospect":"In retrospect, the failure was an invaluable, if expensive, lesson in the dangers of cutting corners.","invaluable":"In retrospect, the failure was an invaluable, if expensive, lesson in the dangers of cutting corners.","danger":"In retrospect, the failure was an invaluable, if expensive, lesson in the dangers of cutting corners.","corner":"In retrospect, the failure was an invaluable, if expensive, lesson in the dangers of cutting corners."},"fm":{"skip":"skipped","component":"components","simulate":"simulated","danger":"dangers","corner":"corners"}},{"id":180,"lv":"C1","n":21,"title":"Working with the Municipality","tr":"Belediyeyle işbirliği","text":"Our growing reputation attracted the attention of a provincial municipality interested in reducing energy poverty. Collaborating with a public institution introduced us to an entirely different world of procurement rules, committees and lengthy approval processes. At times, the bureaucracy seemed absurd. Nonetheless, I came to understand that many of these procedures exist to ensure transparency and prevent corruption in the spending of public money, which is a legitimate concern.","words":["attract","provincial","municipality","collaborate","institution","procurement","absurd","nonetheless","ensure","transparency","corruption"],"ex":{"attract":"Our growing reputation attracted the attention of a provincial municipality interested in reducing energy poverty.","provincial":"Our growing reputation attracted the attention of a provincial municipality interested in reducing energy poverty.","municipality":"Our growing reputation attracted the attention of a provincial municipality interested in reducing energy poverty.","collaborate":"Collaborating with a public institution introduced us to an entirely different world of procurement rules, committees and lengthy approval processes.","institution":"Collaborating with a public institution introduced us to an entirely different world of procurement rules, committees and lengthy approval processes.","procurement":"Collaborating with a public institution introduced us to an entirely different world of procurement rules, committees and lengthy approval processes.","absurd":"At times, the bureaucracy seemed absurd.","nonetheless":"Nonetheless, I came to understand that many of these procedures exist to ensure transparency and prevent corruption in the spending of public money, which is a legitimate concern.","ensure":"Nonetheless, I came to understand that many of these procedures exist to ensure transparency and prevent corruption in the spending of public money, which is a legitimate concern.","transparency":"Nonetheless, I came to understand that many of these procedures exist to ensure transparency and prevent corruption in the spending of public money, which is a legitimate concern.","corruption":"Nonetheless, I came to understand that many of these procedures exist to ensure transparency and prevent corruption in the spending of public money, which is a legitimate concern."},"fm":{"attract":"attracted","collaborate":"collaborating"}},{"id":181,"lv":"C1","n":22,"title":"A Stakeholder Meeting","tr":"Paydaş toplantısı","text":"The municipality organised a meeting with residents, local officials and representatives of the electricity distributor. Facilitating such a diverse group was challenging. The residents were primarily concerned about cost and disruption, the officials about accountability, and the distributor about the impact on the local grid. Instead of defending our proposal, I tried to listen and identify common ground. By the end, we had a list of shared priorities that formed the basis of a pilot agreement.","words":["official","representative","distributor","facilitate","diverse","primarily","disruption","accountability","defend","identify","priority","agreement"],"ex":{"official":"The municipality organised a meeting with residents, local officials and representatives of the electricity distributor.","representative":"The municipality organised a meeting with residents, local officials and representatives of the electricity distributor.","distributor":"The municipality organised a meeting with residents, local officials and representatives of the electricity distributor.","facilitate":"Facilitating such a diverse group was challenging.","diverse":"Facilitating such a diverse group was challenging.","primarily":"The residents were primarily concerned about cost and disruption, the officials about accountability, and the distributor about the impact on the local grid.","disruption":"The residents were primarily concerned about cost and disruption, the officials about accountability, and the distributor about the impact on the local grid.","accountability":"The residents were primarily concerned about cost and disruption, the officials about accountability, and the distributor about the impact on the local grid.","defend":"Instead of defending our proposal, I tried to listen and identify common ground.","identify":"Instead of defending our proposal, I tried to listen and identify common ground.","priority":"By the end, we had a list of shared priorities that formed the basis of a pilot agreement.","agreement":"By the end, we had a list of shared priorities that formed the basis of a pilot agreement."},"fm":{"official":"officials","representative":"representatives","facilitate":"facilitating","defend":"defending","priority":"priorities"}},{"id":182,"lv":"C1","n":23,"title":"Growing the Team","tr":"Ekibin büyümesi","text":"Within two years, our enterprise had grown to fourteen employees, including technicians, an accountant and a community coordinator. Managing people turned out to be far more demanding than managing technology. I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail. I read extensively on leadership, but the most useful lessons came from my own mistakes and from candid conversations with the team.","words":["fourteen","employee","accountant","coordinator","manage","constructive","resolve","conflict","delegate","attempt","control","extensively","leadership","candid"],"ex":{"fourteen":"Within two years, our enterprise had grown to fourteen employees, including technicians, an accountant and a community coordinator.","employee":"Within two years, our enterprise had grown to fourteen employees, including technicians, an accountant and a community coordinator.","accountant":"Within two years, our enterprise had grown to fourteen employees, including technicians, an accountant and a community coordinator.","coordinator":"Within two years, our enterprise had grown to fourteen employees, including technicians, an accountant and a community coordinator.","manage":"Managing people turned out to be far more demanding than managing technology.","constructive":"I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail.","resolve":"I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail.","conflict":"I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail.","delegate":"I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail.","attempt":"I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail.","control":"I had to learn how to give constructive feedback, resolve conflicts and delegate responsibility instead of attempting to control every detail.","extensively":"I read extensively on leadership, but the most useful lessons came from my own mistakes and from candid conversations with the team.","leadership":"I read extensively on leadership, but the most useful lessons came from my own mistakes and from candid conversations with the team.","candid":"I read extensively on leadership, but the most useful lessons came from my own mistakes and from candid conversations with the team."},"fm":{"employee":"employees","manage":"managing","conflict":"conflicts","attempt":"attempting"}},{"id":183,"lv":"C1","n":24,"title":"Learning to Delegate","tr":"Yetki devretmek","text":"Delegation did not come naturally to me. I was accustomed to doing things myself, partly because I believed I could do them better. This habit was exhausting for me and frustrating for my colleagues, who felt that I did not trust them. A turning point came when a technician named Yusuf redesigned our installation procedure without consulting me, reducing installation time by a third. I realised that my reluctance to delegate had been holding the organisation back.","words":["delegation","naturally","accustomed","believe","exhausting","consult","organisation"],"ex":{"delegation":"Delegation did not come naturally to me.","naturally":"Delegation did not come naturally to me.","accustomed":"I was accustomed to doing things myself, partly because I believed I could do them better.","believe":"I was accustomed to doing things myself, partly because I believed I could do them better.","exhausting":"This habit was exhausting for me and frustrating for my colleagues, who felt that I did not trust them.","consult":"A turning point came when a technician named Yusuf redesigned our installation procedure without consulting me, reducing installation time by a third.","organisation":"I realised that my reluctance to delegate had been holding the organisation back."},"fm":{"believe":"believed","consult":"consulting"}},{"id":184,"lv":"C1","n":25,"title":"Work and Life","tr":"İş ve yaşam dengesi","text":"During this period, I worked almost continuously, often late into the night and at weekends. My health began to suffer; I slept badly and had frequent headaches. Ayşe, who was by then studying psychology, gently confronted me about it. She pointed out that exhaustion impairs judgement and that a leader who burns out helps no one. Reluctantly, I began to set boundaries, protecting my evenings and taking proper holidays.","words":["continuously","suffer","sleep","badly","headache","psychology","gently","confront","exhaustion","impair","reluctantly","boundary","proper"],"ex":{"continuously":"During this period, I worked almost continuously, often late into the night and at weekends.","suffer":"My health began to suffer; I slept badly and had frequent headaches.","sleep":"My health began to suffer; I slept badly and had frequent headaches.","badly":"My health began to suffer; I slept badly and had frequent headaches.","headache":"My health began to suffer; I slept badly and had frequent headaches.","psychology":"Ayşe, who was by then studying psychology, gently confronted me about it.","gently":"Ayşe, who was by then studying psychology, gently confronted me about it.","confront":"Ayşe, who was by then studying psychology, gently confronted me about it.","exhaustion":"She pointed out that exhaustion impairs judgement and that a leader who burns out helps no one.","impair":"She pointed out that exhaustion impairs judgement and that a leader who burns out helps no one.","reluctantly":"Reluctantly, I began to set boundaries, protecting my evenings and taking proper holidays.","boundary":"Reluctantly, I began to set boundaries, protecting my evenings and taking proper holidays.","proper":"Reluctantly, I began to set boundaries, protecting my evenings and taking proper holidays."},"fm":{"sleep":"slept","headache":"headaches","confront":"confronted","impair":"impairs","boundary":"boundaries"}},{"id":185,"lv":"C1","n":26,"title":"Mert's Choice","tr":"Mert'in seçimi","text":"My younger brother Mert, meanwhile, had chosen an entirely different path. Instead of going to university immediately, he had trained as an electrician, and he was proud of working with his hands. Some relatives considered this a lesser choice, an attitude I found deeply unfair. Skilled tradespeople are indispensable to the energy transition; without them, no solar panel or heat pump gets installed. I eventually invited Mert to join our technical team.","words":["electrician","lesser","attitude","deeply","unfair","skilled","tradespeople","indispensable","transition"],"ex":{"electrician":"Instead of going to university immediately, he had trained as an electrician, and he was proud of working with his hands.","lesser":"Some relatives considered this a lesser choice, an attitude I found deeply unfair.","attitude":"Some relatives considered this a lesser choice, an attitude I found deeply unfair.","deeply":"Some relatives considered this a lesser choice, an attitude I found deeply unfair.","unfair":"Some relatives considered this a lesser choice, an attitude I found deeply unfair.","skilled":"Skilled tradespeople are indispensable to the energy transition; without them, no solar panel or heat pump gets installed.","tradespeople":"Skilled tradespeople are indispensable to the energy transition; without them, no solar panel or heat pump gets installed.","indispensable":"Skilled tradespeople are indispensable to the energy transition; without them, no solar panel or heat pump gets installed.","transition":"Skilled tradespeople are indispensable to the energy transition; without them, no solar panel or heat pump gets installed."},"fm":{}},{"id":186,"lv":"C1","n":27,"title":"Policy Recommendations","tr":"Politika önerileri","text":"As our experience accumulated, a government ministry invited us to contribute to a consultation on energy efficiency policy. We drafted recommendations based on our data, arguing that subsidies should target low-income households and prioritise insulation before new heating equipment. Writing for policymakers required yet another style: concise, evidence-based and free of technical jargon. I was struck by how rarely the people most affected by policy are consulted directly.","words":["accumulate","government","ministry","consultation","based","subsidy","target","prioritise","equipment","policymaker","concise","evidence","jargon"],"ex":{"accumulate":"As our experience accumulated, a government ministry invited us to contribute to a consultation on energy efficiency policy.","government":"As our experience accumulated, a government ministry invited us to contribute to a consultation on energy efficiency policy.","ministry":"As our experience accumulated, a government ministry invited us to contribute to a consultation on energy efficiency policy.","consultation":"As our experience accumulated, a government ministry invited us to contribute to a consultation on energy efficiency policy.","based":"We drafted recommendations based on our data, arguing that subsidies should target low-income households and prioritise insulation before new heating equipment.","subsidy":"We drafted recommendations based on our data, arguing that subsidies should target low-income households and prioritise insulation before new heating equipment.","target":"We drafted recommendations based on our data, arguing that subsidies should target low-income households and prioritise insulation before new heating equipment.","prioritise":"We drafted recommendations based on our data, arguing that subsidies should target low-income households and prioritise insulation before new heating equipment.","equipment":"We drafted recommendations based on our data, arguing that subsidies should target low-income households and prioritise insulation before new heating equipment.","policymaker":"Writing for policymakers required yet another style: concise, evidence-based and free of technical jargon.","concise":"Writing for policymakers required yet another style: concise, evidence-based and free of technical jargon.","evidence":"Writing for policymakers required yet another style: concise, evidence-based and free of technical jargon.","jargon":"Writing for policymakers required yet another style: concise, evidence-based and free of technical jargon."},"fm":{"accumulate":"accumulated","subsidy":"subsidies","policymaker":"policymakers"}},{"id":187,"lv":"C1","n":28,"title":"Greenwashing","tr":"Yeşil aklama","text":"Not every development in our sector was encouraging. As energy efficiency became fashionable, some companies began making exaggerated claims about their products, a practice known as greenwashing. One competitor advertised savings that were physically impossible under normal conditions. Although it would have been tempting to exaggerate our own results to compete, we decided to publish our actual performance data openly. Transparency, we believed, would prove more durable than marketing.","words":["sector","encouraging","fashionable","exaggerate","product","greenwashing","competitor","advertise","physically","impossible","compete","durable","marketing"],"ex":{"sector":"Not every development in our sector was encouraging.","encouraging":"Not every development in our sector was encouraging.","fashionable":"As energy efficiency became fashionable, some companies began making exaggerated claims about their products, a practice known as greenwashing.","exaggerate":"As energy efficiency became fashionable, some companies began making exaggerated claims about their products, a practice known as greenwashing.","product":"As energy efficiency became fashionable, some companies began making exaggerated claims about their products, a practice known as greenwashing.","greenwashing":"As energy efficiency became fashionable, some companies began making exaggerated claims about their products, a practice known as greenwashing.","competitor":"One competitor advertised savings that were physically impossible under normal conditions.","advertise":"One competitor advertised savings that were physically impossible under normal conditions.","physically":"One competitor advertised savings that were physically impossible under normal conditions.","impossible":"One competitor advertised savings that were physically impossible under normal conditions.","compete":"Although it would have been tempting to exaggerate our own results to compete, we decided to publish our actual performance data openly.","durable":"Transparency, we believed, would prove more durable than marketing.","marketing":"Transparency, we believed, would prove more durable than marketing."},"fm":{"exaggerate":"exaggerated","product":"products","advertise":"advertised"}},{"id":188,"lv":"C1","n":29,"title":"A Journalist","tr":"Bir gazeteci","text":"A journalist from a national newspaper interviewed me for an article on energy poverty. I was apprehensive, having heard that journalists sometimes simplify complex issues. To my relief, she was well informed and asked thoughtful questions. Nevertheless, the published headline overstated our achievements considerably. I learned to prepare concise key messages before interviews and to accept that I could not control how others would frame my words.","words":["journalist","newspaper","apprehensive","simplify","issue","thoughtful","headline","overstate","achievement","key"],"ex":{"journalist":"A journalist from a national newspaper interviewed me for an article on energy poverty.","newspaper":"A journalist from a national newspaper interviewed me for an article on energy poverty.","apprehensive":"I was apprehensive, having heard that journalists sometimes simplify complex issues.","simplify":"I was apprehensive, having heard that journalists sometimes simplify complex issues.","issue":"I was apprehensive, having heard that journalists sometimes simplify complex issues.","thoughtful":"To my relief, she was well informed and asked thoughtful questions.","headline":"Nevertheless, the published headline overstated our achievements considerably.","overstate":"Nevertheless, the published headline overstated our achievements considerably.","achievement":"Nevertheless, the published headline overstated our achievements considerably.","key":"I learned to prepare concise key messages before interviews and to accept that I could not control how others would frame my words."},"fm":{"issue":"issues","overstate":"overstated","achievement":"achievements"}},{"id":189,"lv":"C1","n":30,"title":"Digital Monitoring","tr":"Dijital izleme","text":"To improve maintenance, we introduced inexpensive sensors that monitored the systems remotely and alerted technicians to faults. This allowed us to fix problems before customers even noticed them. However, it raised the same privacy concerns I had encountered during my thesis. We adopted strict principles: collect only the data necessary for maintenance, explain clearly what is collected, and never sell it. Some advisers considered this commercially naive, but we never regretted it.","words":["inexpensive","alert","fault","fix","privacy","adviser","commercially","naive"],"ex":{"inexpensive":"To improve maintenance, we introduced inexpensive sensors that monitored the systems remotely and alerted technicians to faults.","alert":"To improve maintenance, we introduced inexpensive sensors that monitored the systems remotely and alerted technicians to faults.","fault":"To improve maintenance, we introduced inexpensive sensors that monitored the systems remotely and alerted technicians to faults.","fix":"This allowed us to fix problems before customers even noticed them.","privacy":"However, it raised the same privacy concerns I had encountered during my thesis.","adviser":"Some advisers considered this commercially naive, but we never regretted it.","commercially":"Some advisers considered this commercially naive, but we never regretted it.","naive":"Some advisers considered this commercially naive, but we never regretted it."},"fm":{"alert":"alerted","fault":"faults","adviser":"advisers"}},{"id":190,"lv":"C1","n":31,"title":"Can's Dilemma","tr":"Can'ın ikilemi","text":"Can, now an experienced engineer in the defence industry, confided in me that he was struggling with a moral dilemma. His team was developing a guidance system, and he had begun to question whether he wanted to contribute to weapons technology. We discussed it late into the night. I did not tell him what to do; I simply asked questions about his values. Months later, he moved to a company developing medical imaging equipment.","words":["industry","confide","moral","guidance","weapon","medical","imaging"],"ex":{"industry":"Can, now an experienced engineer in the defence industry, confided in me that he was struggling with a moral dilemma.","confide":"Can, now an experienced engineer in the defence industry, confided in me that he was struggling with a moral dilemma.","moral":"Can, now an experienced engineer in the defence industry, confided in me that he was struggling with a moral dilemma.","guidance":"His team was developing a guidance system, and he had begun to question whether he wanted to contribute to weapons technology.","weapon":"His team was developing a guidance system, and he had begun to question whether he wanted to contribute to weapons technology.","medical":"Months later, he moved to a company developing medical imaging equipment.","imaging":"Months later, he moved to a company developing medical imaging equipment."},"fm":{"confide":"confided","weapon":"weapons"}},{"id":191,"lv":"C1","n":32,"title":"Engineering and Responsibility","tr":"Mühendislik ve sorumluluk","text":"Our conversation prompted me to reflect on engineers' responsibilities more generally. Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable. Engineers therefore have obligations not only to their employers but to the public. Professional codes of ethics state this explicitly, yet in practice, commercial pressures can make these obligations easy to rationalise away.","words":["prompt","generally","purely","embody","bear","risk","consequence","acceptable","therefore","obligation","employer","professional","code","explicitly","commercial","rationalise"],"ex":{"prompt":"Our conversation prompted me to reflect on engineers' responsibilities more generally.","generally":"Our conversation prompted me to reflect on engineers' responsibilities more generally.","purely":"Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable.","embody":"Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable.","bear":"Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable.","risk":"Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable.","consequence":"Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable.","acceptable":"Engineering decisions are rarely purely technical; they embody choices about who benefits, who bears the risks and what consequences are acceptable.","therefore":"Engineers therefore have obligations not only to their employers but to the public.","obligation":"Engineers therefore have obligations not only to their employers but to the public.","employer":"Engineers therefore have obligations not only to their employers but to the public.","professional":"Professional codes of ethics state this explicitly, yet in practice, commercial pressures can make these obligations easy to rationalise away.","code":"Professional codes of ethics state this explicitly, yet in practice, commercial pressures can make these obligations easy to rationalise away.","explicitly":"Professional codes of ethics state this explicitly, yet in practice, commercial pressures can make these obligations easy to rationalise away.","commercial":"Professional codes of ethics state this explicitly, yet in practice, commercial pressures can make these obligations easy to rationalise away.","rationalise":"Professional codes of ethics state this explicitly, yet in practice, commercial pressures can make these obligations easy to rationalise away."},"fm":{"prompt":"prompted","bear":"bears","risk":"risks","consequence":"consequences","obligation":"obligations","employer":"employers","code":"codes"}},{"id":192,"lv":"C1","n":33,"title":"An Award","tr":"Bir ödül","text":"In our fifth year, our enterprise received an international award for social innovation. The ceremony in Geneva was glamorous and slightly surreal; I felt somewhat like an impostor among the distinguished guests. In my brief speech, I emphasised that the award belonged to our technicians and to the families who had trusted us. Privately, I worried that recognition might make us complacent. Awards celebrate the past, after all, not the challenges ahead.","words":["award","surreal","impostor","distinguished","guest","brief","speech","privately","recognition","complacent","past","ahead"],"ex":{"award":"In our fifth year, our enterprise received an international award for social innovation.","surreal":"The ceremony in Geneva was glamorous and slightly surreal; I felt somewhat like an impostor among the distinguished guests.","impostor":"The ceremony in Geneva was glamorous and slightly surreal; I felt somewhat like an impostor among the distinguished guests.","distinguished":"The ceremony in Geneva was glamorous and slightly surreal; I felt somewhat like an impostor among the distinguished guests.","guest":"The ceremony in Geneva was glamorous and slightly surreal; I felt somewhat like an impostor among the distinguished guests.","brief":"In my brief speech, I emphasised that the award belonged to our technicians and to the families who had trusted us.","speech":"In my brief speech, I emphasised that the award belonged to our technicians and to the families who had trusted us.","privately":"Privately, I worried that recognition might make us complacent.","recognition":"Privately, I worried that recognition might make us complacent.","complacent":"Privately, I worried that recognition might make us complacent.","past":"Awards celebrate the past, after all, not the challenges ahead.","ahead":"Awards celebrate the past, after all, not the challenges ahead."},"fm":{"guest":"guests"}},{"id":193,"lv":"C1","n":34,"title":"The Scaling Dilemma","tr":"Ölçeklendirme ikilemi","text":"After the award, investors who had previously ignored us suddenly expressed interest. One proposed a substantial investment, conditional on expanding rapidly into five new provinces. Zehra and I disagreed sharply about this. She argued that rapid growth would let us help many more families; I feared that it would compromise quality and our close relationships with communities. Ultimately, we accepted a smaller investment with slower, more manageable growth targets.","words":["ignore","express","conditional","expand","rapidly","province","sharply","fear","compromise","relationship","manageable"],"ex":{"ignore":"After the award, investors who had previously ignored us suddenly expressed interest.","express":"After the award, investors who had previously ignored us suddenly expressed interest.","conditional":"One proposed a substantial investment, conditional on expanding rapidly into five new provinces.","expand":"One proposed a substantial investment, conditional on expanding rapidly into five new provinces.","rapidly":"One proposed a substantial investment, conditional on expanding rapidly into five new provinces.","province":"One proposed a substantial investment, conditional on expanding rapidly into five new provinces.","sharply":"Zehra and I disagreed sharply about this.","fear":"She argued that rapid growth would let us help many more families; I feared that it would compromise quality and our close relationships with communities.","compromise":"She argued that rapid growth would let us help many more families; I feared that it would compromise quality and our close relationships with communities.","relationship":"She argued that rapid growth would let us help many more families; I feared that it would compromise quality and our close relationships with communities.","manageable":"Ultimately, we accepted a smaller investment with slower, more manageable growth targets."},"fm":{"ignore":"ignored","express":"expressed","expand":"expanding","province":"provinces","fear":"feared","relationship":"relationships"}},{"id":194,"lv":"C1","n":35,"title":"Losing My Grandmother","tr":"Büyükannemin vefatı","text":"That autumn, my grandmother passed away peacefully in her sleep, at the age of ninety-one. I returned to the village for the funeral, where neighbours shared stories of her generosity and stubbornness in equal measure. Sitting in her empty kitchen, beside the old stove where she had told me countless stories, I was overwhelmed by grief and gratitude. In many ways, our entire enterprise had begun in that very room.","words":["peacefully","age","ninety","funeral","generosity","stubbornness","equal","beside","overwhelm","grief","gratitude"],"ex":{"peacefully":"That autumn, my grandmother passed away peacefully in her sleep, at the age of ninety-one.","age":"That autumn, my grandmother passed away peacefully in her sleep, at the age of ninety-one.","ninety":"That autumn, my grandmother passed away peacefully in her sleep, at the age of ninety-one.","funeral":"I returned to the village for the funeral, where neighbours shared stories of her generosity and stubbornness in equal measure.","generosity":"I returned to the village for the funeral, where neighbours shared stories of her generosity and stubbornness in equal measure.","stubbornness":"I returned to the village for the funeral, where neighbours shared stories of her generosity and stubbornness in equal measure.","equal":"I returned to the village for the funeral, where neighbours shared stories of her generosity and stubbornness in equal measure.","beside":"Sitting in her empty kitchen, beside the old stove where she had told me countless stories, I was overwhelmed by grief and gratitude.","overwhelm":"Sitting in her empty kitchen, beside the old stove where she had told me countless stories, I was overwhelmed by grief and gratitude.","grief":"Sitting in her empty kitchen, beside the old stove where she had told me countless stories, I was overwhelmed by grief and gratitude.","gratitude":"Sitting in her empty kitchen, beside the old stove where she had told me countless stories, I was overwhelmed by grief and gratitude."},"fm":{"overwhelm":"overwhelmed"}},{"id":195,"lv":"C1","n":36,"title":"A Tribute","tr":"Bir anma","text":"To honour her memory, we established a small scholarship fund for young people from her village who wished to train as technicians. The first recipient was a determined young woman named Esra, who later became one of our most skilled installers. I like to think that my grandmother, who had never been allowed to finish primary school, would have been delighted that her legacy took the form of education.","words":["wish","recipient","determined","installer","primary","legacy"],"ex":{"wish":"To honour her memory, we established a small scholarship fund for young people from her village who wished to train as technicians.","recipient":"The first recipient was a determined young woman named Esra, who later became one of our most skilled installers.","determined":"The first recipient was a determined young woman named Esra, who later became one of our most skilled installers.","installer":"The first recipient was a determined young woman named Esra, who later became one of our most skilled installers.","primary":"I like to think that my grandmother, who had never been allowed to finish primary school, would have been delighted that her legacy took the form of education.","legacy":"I like to think that my grandmother, who had never been allowed to finish primary school, would have been delighted that her legacy took the form of education."},"fm":{"wish":"wished","installer":"installers"}},{"id":196,"lv":"C1","n":37,"title":"Adapting to Climate Change","tr":"İklim uyumu","text":"Over these years, the effects of climate change became increasingly tangible. Summers in central Anatolia grew hotter, and many of our customers began to struggle with overheating rather than cold. This prompted us to rethink our offering. Our heat pumps could also provide cooling, and good insulation protected houses against heat as effectively as against cold. Adaptation, we realised, was becoming as important as reducing emissions.","words":["increasingly","tangible","rethink","against","adaptation"],"ex":{"increasingly":"Over these years, the effects of climate change became increasingly tangible.","tangible":"Over these years, the effects of climate change became increasingly tangible.","rethink":"This prompted us to rethink our offering.","against":"Our heat pumps could also provide cooling, and good insulation protected houses against heat as effectively as against cold.","adaptation":"Adaptation, we realised, was becoming as important as reducing emissions."},"fm":{}},{"id":197,"lv":"C1","n":38,"title":"A Flawed Assumption","tr":"Yanlış bir varsayım","text":"Expanding into cooling exposed a flawed assumption in our business model. We had presumed that customers would use the equipment sparingly to minimise costs. In reality, during heatwaves, some households ran their air conditioning continuously, resulting in unexpectedly high electricity bills and complaints. We responded by developing simple guidance on efficient cooling and by fitting smart controllers. The episode reminded me that technology interacts with human behaviour in ways that are difficult to predict.","words":["expose","flawed","presume","sparingly","minimise","heatwave","unexpectedly","complaint","controller","episode","interact"],"ex":{"expose":"Expanding into cooling exposed a flawed assumption in our business model.","flawed":"Expanding into cooling exposed a flawed assumption in our business model.","presume":"We had presumed that customers would use the equipment sparingly to minimise costs.","sparingly":"We had presumed that customers would use the equipment sparingly to minimise costs.","minimise":"We had presumed that customers would use the equipment sparingly to minimise costs.","heatwave":"In reality, during heatwaves, some households ran their air conditioning continuously, resulting in unexpectedly high electricity bills and complaints.","unexpectedly":"In reality, during heatwaves, some households ran their air conditioning continuously, resulting in unexpectedly high electricity bills and complaints.","complaint":"In reality, during heatwaves, some households ran their air conditioning continuously, resulting in unexpectedly high electricity bills and complaints.","controller":"We responded by developing simple guidance on efficient cooling and by fitting smart controllers.","episode":"The episode reminded me that technology interacts with human behaviour in ways that are difficult to predict.","interact":"The episode reminded me that technology interacts with human behaviour in ways that are difficult to predict."},"fm":{"expose":"exposed","presume":"presumed","heatwave":"heatwaves","complaint":"complaints","controller":"controllers","interact":"interacts"}},{"id":198,"lv":"C1","n":39,"title":"A Group of Students","tr":"Bir öğrenci grubu","text":"One spring, Professor Demir asked me to speak to her final-year students. Facing them, I recognised my younger self: eager, idealistic and slightly anxious about the future. I told them candidly about our failures as well as our successes. Afterwards, a student asked how I had known which path to choose. I admitted that I had not known; I had simply made the best decisions I could with the information available and adjusted along the way.","words":["idealistic","candidly"],"ex":{"idealistic":"Facing them, I recognised my younger self: eager, idealistic and slightly anxious about the future.","candidly":"I told them candidly about our failures as well as our successes."},"fm":{}},{"id":199,"lv":"C1","n":40,"title":"Ten Years On","tr":"On yıl sonra","text":"Ten years after my first English lesson, I occasionally reread the simple sentences in my old notebook: \"My name is Deniz. I am a student.\" The contrast with my current life is striking. Yet I remain, fundamentally, a student. Every project, every failure and every conversation continues to teach me something. Perhaps the most important lesson is that expertise is not a destination but a disposition: a willingness to keep learning.","words":["occasionally","notebook","contrast","current","striking","fundamentally","expertise","destination","disposition","willingness"],"ex":{"occasionally":"Ten years after my first English lesson, I occasionally reread the simple sentences in my old notebook: \"My name is Deniz.","notebook":"Ten years after my first English lesson, I occasionally reread the simple sentences in my old notebook: \"My name is Deniz.","contrast":"The contrast with my current life is striking.","current":"The contrast with my current life is striking.","striking":"The contrast with my current life is striking.","fundamentally":"Yet I remain, fundamentally, a student.","expertise":"Perhaps the most important lesson is that expertise is not a destination but a disposition: a willingness to keep learning.","destination":"Perhaps the most important lesson is that expertise is not a destination but a disposition: a willingness to keep learning.","disposition":"Perhaps the most important lesson is that expertise is not a destination but a disposition: a willingness to keep learning.","willingness":"Perhaps the most important lesson is that expertise is not a destination but a disposition: a willingness to keep learning."},"fm":{}},{"id":200,"lv":"C2","n":1,"title":"The Idea for a Book","tr":"Bir kitap fikri","text":"It was Ayşe who first suggested, half in jest, that I write a book. \"You never stop telling stories about the villages,\" she teased, \"so you might as well put them on paper.\" The notion lingered. I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","words":["jest","tease","notion","linger","literary","pretension","narrative","blunder","serendipitous","breakthrough","resonate","seldom","messy"],"ex":{"jest":"It was Ayşe who first suggested, half in jest, that I write a book.","tease":"\"You never stop telling stories about the villages,\" she teased, \"so you might as well put them on paper.\"","notion":"The notion lingered.","linger":"The notion lingered.","literary":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","pretension":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","narrative":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","blunder":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","serendipitous":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","breakthrough":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","resonate":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","seldom":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is.","messy":"I had no literary pretensions, yet I felt that the narrative of our enterprise, with its blunders and serendipitous breakthroughs, might resonate with young engineers who are seldom told how messy innovation actually is."},"fm":{"tease":"teased","linger":"lingered","pretension":"pretensions","blunder":"blunders","breakthrough":"breakthroughs"}},{"id":201,"lv":"C2","n":2,"title":"The Discipline of Writing","tr":"Yazmanın zorluğu","text":"Writing proved far more arduous than I had envisaged. Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour. My early drafts were stilted and self-congratulatory. An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\" That laconic advice transformed the manuscript, compelling me to dwell on uncertainty rather than gloss over it.","words":["arduous","envisage","terse","impersonal","register","voice","rhythm","candour","stilted","congratulatory","editor","scrawl","blunt","remark","margin","triumph","doubt","laconic","transform","compelling","dwell","gloss"],"ex":{"arduous":"Writing proved far more arduous than I had envisaged.","envisage":"Writing proved far more arduous than I had envisaged.","terse":"Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour.","impersonal":"Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour.","register":"Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour.","voice":"Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour.","rhythm":"Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour.","candour":"Technical reports had accustomed me to a terse, impersonal register, whereas a book demanded voice, rhythm and candour.","stilted":"My early drafts were stilted and self-congratulatory.","congratulatory":"My early drafts were stilted and self-congratulatory.","editor":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","scrawl":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","blunt":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","remark":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","margin":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","triumph":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","doubt":"An editor, to whom Professor Demir had introduced me, scrawled a blunt remark in the margin: \"Less triumph, more doubt.\"","laconic":"That laconic advice transformed the manuscript, compelling me to dwell on uncertainty rather than gloss over it.","transform":"That laconic advice transformed the manuscript, compelling me to dwell on uncertainty rather than gloss over it.","compelling":"That laconic advice transformed the manuscript, compelling me to dwell on uncertainty rather than gloss over it.","dwell":"That laconic advice transformed the manuscript, compelling me to dwell on uncertainty rather than gloss over it.","gloss":"That laconic advice transformed the manuscript, compelling me to dwell on uncertainty rather than gloss over it."},"fm":{"envisage":"envisaged","scrawl":"scrawled","transform":"transformed"}},{"id":202,"lv":"C2","n":3,"title":"Lessons from History","tr":"Teknoloji tarihi","text":"To situate our work in a broader context, I immersed myself in the history of technology. I was struck by how often innovations had been hailed as panaceas, only to engender unforeseen predicaments. The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate. Such precedents instilled in me a wariness of any technology marketed as an unambiguous solution to complex societal problems.","words":["situate","context","immerse","hail","panacea","engender","unforeseen","predicament","automobile","liberation","beget","congestion","sprawl","fossil","propel","prosperity","quietly","destabilise","precedent","instil","wariness","unambiguous","societal"],"ex":{"situate":"To situate our work in a broader context, I immersed myself in the history of technology.","context":"To situate our work in a broader context, I immersed myself in the history of technology.","immerse":"To situate our work in a broader context, I immersed myself in the history of technology.","hail":"I was struck by how often innovations had been hailed as panaceas, only to engender unforeseen predicaments.","panacea":"I was struck by how often innovations had been hailed as panaceas, only to engender unforeseen predicaments.","engender":"I was struck by how often innovations had been hailed as panaceas, only to engender unforeseen predicaments.","unforeseen":"I was struck by how often innovations had been hailed as panaceas, only to engender unforeseen predicaments.","predicament":"I was struck by how often innovations had been hailed as panaceas, only to engender unforeseen predicaments.","automobile":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","liberation":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","beget":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","congestion":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","sprawl":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","fossil":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","propel":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","prosperity":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","quietly":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","destabilise":"The automobile promised liberation yet begot congestion and sprawl; cheap fossil fuels propelled prosperity while quietly destabilising the climate.","precedent":"Such precedents instilled in me a wariness of any technology marketed as an unambiguous solution to complex societal problems.","instil":"Such precedents instilled in me a wariness of any technology marketed as an unambiguous solution to complex societal problems.","wariness":"Such precedents instilled in me a wariness of any technology marketed as an unambiguous solution to complex societal problems.","unambiguous":"Such precedents instilled in me a wariness of any technology marketed as an unambiguous solution to complex societal problems.","societal":"Such precedents instilled in me a wariness of any technology marketed as an unambiguous solution to complex societal problems."},"fm":{"immerse":"immersed","hail":"hailed","panacea":"panaceas","predicament":"predicaments","beget":"begot","propel":"propelled","destabilise":"destabilising","precedent":"precedents","instil":"instilled"}},{"id":203,"lv":"C2","n":4,"title":"The Rebound Effect","tr":"Jevons paradoksu","text":"One concept preoccupied me in particular: the rebound effect, sometimes called the Jevons paradox. When a resource is used more efficiently, it becomes cheaper, which can paradoxically stimulate greater consumption. Our own data hinted at this phenomenon; some households, once their heating became affordable, understandably heated more rooms. I did not regard this as a failure, since warmth is a legitimate need, but it complicated simplistic assumptions about efficiency curtailing emissions.","words":["preoccupy","particular","rebound","paradox","paradoxically","stimulate","consumption","hint","phenomenon","understandably","simplistic","curtail"],"ex":{"preoccupy":"One concept preoccupied me in particular: the rebound effect, sometimes called the Jevons paradox.","particular":"One concept preoccupied me in particular: the rebound effect, sometimes called the Jevons paradox.","rebound":"One concept preoccupied me in particular: the rebound effect, sometimes called the Jevons paradox.","paradox":"One concept preoccupied me in particular: the rebound effect, sometimes called the Jevons paradox.","paradoxically":"When a resource is used more efficiently, it becomes cheaper, which can paradoxically stimulate greater consumption.","stimulate":"When a resource is used more efficiently, it becomes cheaper, which can paradoxically stimulate greater consumption.","consumption":"When a resource is used more efficiently, it becomes cheaper, which can paradoxically stimulate greater consumption.","hint":"Our own data hinted at this phenomenon; some households, once their heating became affordable, understandably heated more rooms.","phenomenon":"Our own data hinted at this phenomenon; some households, once their heating became affordable, understandably heated more rooms.","understandably":"Our own data hinted at this phenomenon; some households, once their heating became affordable, understandably heated more rooms.","simplistic":"I did not regard this as a failure, since warmth is a legitimate need, but it complicated simplistic assumptions about efficiency curtailing emissions.","curtail":"I did not regard this as a failure, since warmth is a legitimate need, but it complicated simplistic assumptions about efficiency curtailing emissions."},"fm":{"preoccupy":"preoccupied","hint":"hinted","curtail":"curtailing"}},{"id":204,"lv":"C2","n":5,"title":"The Growth Debate","tr":"Büyüme tartışması","text":"The rebound effect led me, somewhat inexorably, into the contentious debate about economic growth. Proponents of so-called green growth maintain that prosperity can be decoupled from environmental harm through innovation. Advocates of degrowth contend that wealthy societies must curb consumption altogether. I found neither camp entirely persuasive. Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable.","words":["lead","inexorably","contentious","proponent","green","decouple","harm","advocate","degrowth","contend","wealthy","society","curb","altogether","camp","persuasive","dogmatism","obscure","unglamorous","incremental","wasteful","equitable"],"ex":{"lead":"The rebound effect led me, somewhat inexorably, into the contentious debate about economic growth.","inexorably":"The rebound effect led me, somewhat inexorably, into the contentious debate about economic growth.","contentious":"The rebound effect led me, somewhat inexorably, into the contentious debate about economic growth.","proponent":"Proponents of so-called green growth maintain that prosperity can be decoupled from environmental harm through innovation.","green":"Proponents of so-called green growth maintain that prosperity can be decoupled from environmental harm through innovation.","decouple":"Proponents of so-called green growth maintain that prosperity can be decoupled from environmental harm through innovation.","harm":"Proponents of so-called green growth maintain that prosperity can be decoupled from environmental harm through innovation.","advocate":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","degrowth":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","contend":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","wealthy":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","society":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","curb":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","altogether":"Advocates of degrowth contend that wealthy societies must curb consumption altogether.","camp":"I found neither camp entirely persuasive.","persuasive":"I found neither camp entirely persuasive.","dogmatism":"Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable.","obscure":"Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable.","unglamorous":"Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable.","incremental":"Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable.","wasteful":"Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable.","equitable":"Dogmatism on either side seemed to obscure the unglamorous, incremental work of making particular systems less wasteful and more equitable."},"fm":{"lead":"led","proponent":"proponents","decouple":"decoupled","advocate":"advocates","society":"societies"}},{"id":205,"lv":"C2","n":6,"title":"A Keynote Address","tr":"Bir konferans konuşması","text":"When I was invited to deliver a keynote address at an international energy conference, I was initially inclined to decline, fearing that I lacked the requisite eminence. Zehra dismissed my hesitancy as false modesty. In the address, I eschewed grand pronouncements and instead recounted the episode of the faulty valves. Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future.","words":["keynote","inclined","lack","requisite","eminence","dismiss","hesitancy","false","modesty","eschew","grand","pronouncement","recount","judge","admission","fallibility","polished","vision","frictionless"],"ex":{"keynote":"When I was invited to deliver a keynote address at an international energy conference, I was initially inclined to decline, fearing that I lacked the requisite eminence.","inclined":"When I was invited to deliver a keynote address at an international energy conference, I was initially inclined to decline, fearing that I lacked the requisite eminence.","lack":"When I was invited to deliver a keynote address at an international energy conference, I was initially inclined to decline, fearing that I lacked the requisite eminence.","requisite":"When I was invited to deliver a keynote address at an international energy conference, I was initially inclined to decline, fearing that I lacked the requisite eminence.","eminence":"When I was invited to deliver a keynote address at an international energy conference, I was initially inclined to decline, fearing that I lacked the requisite eminence.","dismiss":"Zehra dismissed my hesitancy as false modesty.","hesitancy":"Zehra dismissed my hesitancy as false modesty.","false":"Zehra dismissed my hesitancy as false modesty.","modesty":"Zehra dismissed my hesitancy as false modesty.","eschew":"In the address, I eschewed grand pronouncements and instead recounted the episode of the faulty valves.","grand":"In the address, I eschewed grand pronouncements and instead recounted the episode of the faulty valves.","pronouncement":"In the address, I eschewed grand pronouncements and instead recounted the episode of the faulty valves.","recount":"In the address, I eschewed grand pronouncements and instead recounted the episode of the faulty valves.","judge":"Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future.","admission":"Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future.","fallibility":"Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future.","polished":"Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future.","vision":"Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future.","frictionless":"Judging by the audience's reaction, an admission of fallibility proved more compelling than any polished vision of a frictionless future."},"fm":{"lack":"lacked","dismiss":"dismissed","eschew":"eschewed","pronouncement":"pronouncements","recount":"recounted","judge":"judging"}},{"id":206,"lv":"C2","n":7,"title":"Automation and Labour","tr":"Yapay zekâ ve emek","text":"During the question session, a delegate asked whether automation would render technicians like ours obsolete. It was a perceptive question. Algorithms were already optimising our maintenance schedules with uncanny accuracy. Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation. I argued that the pertinent question was not whether machines would replace workers, but who would reap the gains.","words":["session","automation","render","ours","obsolete","perceptive","optimise","schedule","uncanny","accuracy","crumble","persuade","wary","homeowner","improvise","scant","tacit","stubbornly","resistant","pertinent","worker","reap"],"ex":{"session":"During the question session, a delegate asked whether automation would render technicians like ours obsolete.","automation":"During the question session, a delegate asked whether automation would render technicians like ours obsolete.","render":"During the question session, a delegate asked whether automation would render technicians like ours obsolete.","ours":"During the question session, a delegate asked whether automation would render technicians like ours obsolete.","obsolete":"During the question session, a delegate asked whether automation would render technicians like ours obsolete.","perceptive":"It was a perceptive question.","optimise":"Algorithms were already optimising our maintenance schedules with uncanny accuracy.","schedule":"Algorithms were already optimising our maintenance schedules with uncanny accuracy.","uncanny":"Algorithms were already optimising our maintenance schedules with uncanny accuracy.","accuracy":"Algorithms were already optimising our maintenance schedules with uncanny accuracy.","crumble":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","persuade":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","wary":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","homeowner":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","improvise":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","scant":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","tacit":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","stubbornly":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","resistant":"Yet installing insulation in a crumbling village house, persuading a wary homeowner, or improvising a repair with scant resources demanded tacit skills that remain stubbornly resistant to automation.","pertinent":"I argued that the pertinent question was not whether machines would replace workers, but who would reap the gains.","worker":"I argued that the pertinent question was not whether machines would replace workers, but who would reap the gains.","reap":"I argued that the pertinent question was not whether machines would replace workers, but who would reap the gains."},"fm":{"optimise":"optimising","schedule":"schedules","crumble":"crumbling","persuade":"persuading","improvise":"improvising","worker":"workers"}},{"id":207,"lv":"C2","n":8,"title":"Tacit Knowledge","tr":"Örtük bilgi","text":"The philosopher Michael Polanyi famously observed that we know more than we can tell. This insight, which I encountered belatedly, illuminated much of my experience. Yusuf could diagnose a malfunctioning pump merely by listening to it, yet he struggled to articulate how. Such tacit knowledge is transmitted through apprenticeship and shared practice rather than manuals. Organisations that disregard it, I came to believe, imperil the very expertise on which they depend.","words":["philosopher","observe","insight","belatedly","illuminate","diagnose","malfunction","merely","articulate","transmit","apprenticeship","manual","disregard","imperil","depend"],"ex":{"philosopher":"The philosopher Michael Polanyi famously observed that we know more than we can tell.","observe":"The philosopher Michael Polanyi famously observed that we know more than we can tell.","insight":"This insight, which I encountered belatedly, illuminated much of my experience.","belatedly":"This insight, which I encountered belatedly, illuminated much of my experience.","illuminate":"This insight, which I encountered belatedly, illuminated much of my experience.","diagnose":"Yusuf could diagnose a malfunctioning pump merely by listening to it, yet he struggled to articulate how.","malfunction":"Yusuf could diagnose a malfunctioning pump merely by listening to it, yet he struggled to articulate how.","merely":"Yusuf could diagnose a malfunctioning pump merely by listening to it, yet he struggled to articulate how.","articulate":"Yusuf could diagnose a malfunctioning pump merely by listening to it, yet he struggled to articulate how.","transmit":"Such tacit knowledge is transmitted through apprenticeship and shared practice rather than manuals.","apprenticeship":"Such tacit knowledge is transmitted through apprenticeship and shared practice rather than manuals.","manual":"Such tacit knowledge is transmitted through apprenticeship and shared practice rather than manuals.","disregard":"Organisations that disregard it, I came to believe, imperil the very expertise on which they depend.","imperil":"Organisations that disregard it, I came to believe, imperil the very expertise on which they depend.","depend":"Organisations that disregard it, I came to believe, imperil the very expertise on which they depend."},"fm":{"observe":"observed","illuminate":"illuminated","malfunction":"malfunctioning","transmit":"transmitted","manual":"manuals"}},{"id":208,"lv":"C2","n":9,"title":"Zehra Moves On","tr":"Zehra'nın ayrılışı","text":"After nine years, Zehra announced that she intended to leave the enterprise to pursue a doctorate in public policy. The news was bittersweet. Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism. She reassured me that her departure was not a repudiation of our work but its natural continuation. We marked the occasion with a modest dinner, reminiscing until the restaurant staff began pointedly stacking chairs.","words":["nine","announce","bittersweet","partnership","innumerable","dispute","pragmatism","temper","idealism","reassure","departure","repudiation","natural","continuation","reminisce","restaurant","staff","pointedly","stack"],"ex":{"nine":"After nine years, Zehra announced that she intended to leave the enterprise to pursue a doctorate in public policy.","announce":"After nine years, Zehra announced that she intended to leave the enterprise to pursue a doctorate in public policy.","bittersweet":"The news was bittersweet.","partnership":"Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism.","innumerable":"Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism.","dispute":"Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism.","pragmatism":"Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism.","temper":"Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism.","idealism":"Our partnership had weathered innumerable disputes and crises, and her pragmatism had often tempered my idealism.","reassure":"She reassured me that her departure was not a repudiation of our work but its natural continuation.","departure":"She reassured me that her departure was not a repudiation of our work but its natural continuation.","repudiation":"She reassured me that her departure was not a repudiation of our work but its natural continuation.","natural":"She reassured me that her departure was not a repudiation of our work but its natural continuation.","continuation":"She reassured me that her departure was not a repudiation of our work but its natural continuation.","reminisce":"We marked the occasion with a modest dinner, reminiscing until the restaurant staff began pointedly stacking chairs.","restaurant":"We marked the occasion with a modest dinner, reminiscing until the restaurant staff began pointedly stacking chairs.","staff":"We marked the occasion with a modest dinner, reminiscing until the restaurant staff began pointedly stacking chairs.","pointedly":"We marked the occasion with a modest dinner, reminiscing until the restaurant staff began pointedly stacking chairs.","stack":"We marked the occasion with a modest dinner, reminiscing until the restaurant staff began pointedly stacking chairs."},"fm":{"announce":"announced","dispute":"disputes","temper":"tempered","reassure":"reassured","reminisce":"reminiscing","stack":"stacking"}},{"id":209,"lv":"C2","n":10,"title":"Passing the Baton","tr":"Liderlik devri","text":"Zehra's departure compelled me to confront an uncomfortable question: was the enterprise excessively dependent on its founders? I resolved to cultivate a new generation of leaders. Esra, the first recipient of my grandmother's scholarship, had risen to become head of operations. Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","words":["compel","uncomfortable","excessively","dependent","founder","cultivate","generation","entrust","authority","nominal","relinquish","disconcerting","frequently","surpass"],"ex":{"compel":"Zehra's departure compelled me to confront an uncomfortable question: was the enterprise excessively dependent on its founders?","uncomfortable":"Zehra's departure compelled me to confront an uncomfortable question: was the enterprise excessively dependent on its founders?","excessively":"Zehra's departure compelled me to confront an uncomfortable question: was the enterprise excessively dependent on its founders?","dependent":"Zehra's departure compelled me to confront an uncomfortable question: was the enterprise excessively dependent on its founders?","founder":"Zehra's departure compelled me to confront an uncomfortable question: was the enterprise excessively dependent on its founders?","cultivate":"I resolved to cultivate a new generation of leaders.","generation":"I resolved to cultivate a new generation of leaders.","entrust":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","authority":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","nominal":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","relinquish":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","disconcerting":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","frequently":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own.","surpass":"Entrusting her with genuine authority, rather than merely nominal responsibility, required me to relinquish control in ways that were at times disconcerting, yet her decisions frequently surpassed my own."},"fm":{"compel":"compelled","founder":"founders","entrust":"entrusting","surpass":"surpassed"}},{"id":210,"lv":"C2","n":11,"title":"A Reading Circle","tr":"Bir edebiyat kulübü","text":"Partly to counterbalance the relentless pragmatism of my working life, I joined a reading circle that met monthly in a bookshop in Ankara. We read novels and poetry, both Turkish and foreign, often in translation. Initially, I approached literature with an engineer's impatience, scanning for plot and conclusion. Over time, I learned to savour ambiguity and to appreciate that the most profound works frequently withhold resolution rather than supply it.","words":["counterbalance","relentless","monthly","bookshop","novel","poetry","translation","impatience","scan","plot","savour","ambiguity","profound","withhold","resolution"],"ex":{"counterbalance":"Partly to counterbalance the relentless pragmatism of my working life, I joined a reading circle that met monthly in a bookshop in Ankara.","relentless":"Partly to counterbalance the relentless pragmatism of my working life, I joined a reading circle that met monthly in a bookshop in Ankara.","monthly":"Partly to counterbalance the relentless pragmatism of my working life, I joined a reading circle that met monthly in a bookshop in Ankara.","bookshop":"Partly to counterbalance the relentless pragmatism of my working life, I joined a reading circle that met monthly in a bookshop in Ankara.","novel":"We read novels and poetry, both Turkish and foreign, often in translation.","poetry":"We read novels and poetry, both Turkish and foreign, often in translation.","translation":"We read novels and poetry, both Turkish and foreign, often in translation.","impatience":"Initially, I approached literature with an engineer's impatience, scanning for plot and conclusion.","scan":"Initially, I approached literature with an engineer's impatience, scanning for plot and conclusion.","plot":"Initially, I approached literature with an engineer's impatience, scanning for plot and conclusion.","savour":"Over time, I learned to savour ambiguity and to appreciate that the most profound works frequently withhold resolution rather than supply it.","ambiguity":"Over time, I learned to savour ambiguity and to appreciate that the most profound works frequently withhold resolution rather than supply it.","profound":"Over time, I learned to savour ambiguity and to appreciate that the most profound works frequently withhold resolution rather than supply it.","withhold":"Over time, I learned to savour ambiguity and to appreciate that the most profound works frequently withhold resolution rather than supply it.","resolution":"Over time, I learned to savour ambiguity and to appreciate that the most profound works frequently withhold resolution rather than supply it."},"fm":{"novel":"novels","scan":"scanning"}},{"id":211,"lv":"C2","n":12,"title":"Living with Ambiguity","tr":"Belirsizlikle yaşamak","text":"That newfound tolerance for ambiguity seeped, unexpectedly, into my professional conduct. I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously. In meetings, I noticed that I listened more and interjected less. A colleague remarked, with characteristic Dutch bluntness during a visit, that I had become \"less certain and more convincing\", an observation I chose to interpret as a compliment.","words":["newfound","tolerance","seep","premature","closure","intractable","willing","entertain","simultaneously","interject","characteristic","bluntness","convincing","observation","compliment"],"ex":{"newfound":"That newfound tolerance for ambiguity seeped, unexpectedly, into my professional conduct.","tolerance":"That newfound tolerance for ambiguity seeped, unexpectedly, into my professional conduct.","seep":"That newfound tolerance for ambiguity seeped, unexpectedly, into my professional conduct.","premature":"I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously.","closure":"I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously.","intractable":"I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously.","willing":"I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously.","entertain":"I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously.","simultaneously":"I became less inclined to force premature closure on intractable problems and more willing to entertain several hypotheses simultaneously.","interject":"In meetings, I noticed that I listened more and interjected less.","characteristic":"A colleague remarked, with characteristic Dutch bluntness during a visit, that I had become \"less certain and more convincing\", an observation I chose to interpret as a compliment.","bluntness":"A colleague remarked, with characteristic Dutch bluntness during a visit, that I had become \"less certain and more convincing\", an observation I chose to interpret as a compliment.","convincing":"A colleague remarked, with characteristic Dutch bluntness during a visit, that I had become \"less certain and more convincing\", an observation I chose to interpret as a compliment.","observation":"A colleague remarked, with characteristic Dutch bluntness during a visit, that I had become \"less certain and more convincing\", an observation I chose to interpret as a compliment.","compliment":"A colleague remarked, with characteristic Dutch bluntness during a visit, that I had become \"less certain and more convincing\", an observation I chose to interpret as a compliment."},"fm":{"seep":"seeped","interject":"interjected"}},{"id":212,"lv":"C2","n":13,"title":"Mentoring","tr":"Mentorluk","text":"Each year, I mentored a handful of young engineers, some from our own staff and others from universities. Mentoring is a curious undertaking. The temptation is to dispense advice, to recount one's own trajectory as though it were a template. Yet circumstances differ, and what proved prudent for me might be ill-advised for them. I gradually learned that the most valuable thing I could offer was not answers but well-chosen questions and an attentive, non-judgemental ear.","words":["mentor","handful","undertaking","temptation","dispense","trajectory","template","circumstance","differ","prudent","ill","attentive","judgemental","ear"],"ex":{"mentor":"Each year, I mentored a handful of young engineers, some from our own staff and others from universities.","handful":"Each year, I mentored a handful of young engineers, some from our own staff and others from universities.","undertaking":"Mentoring is a curious undertaking.","temptation":"The temptation is to dispense advice, to recount one's own trajectory as though it were a template.","dispense":"The temptation is to dispense advice, to recount one's own trajectory as though it were a template.","trajectory":"The temptation is to dispense advice, to recount one's own trajectory as though it were a template.","template":"The temptation is to dispense advice, to recount one's own trajectory as though it were a template.","circumstance":"Yet circumstances differ, and what proved prudent for me might be ill-advised for them.","differ":"Yet circumstances differ, and what proved prudent for me might be ill-advised for them.","prudent":"Yet circumstances differ, and what proved prudent for me might be ill-advised for them.","ill":"Yet circumstances differ, and what proved prudent for me might be ill-advised for them.","attentive":"I gradually learned that the most valuable thing I could offer was not answers but well-chosen questions and an attentive, non-judgemental ear.","judgemental":"I gradually learned that the most valuable thing I could offer was not answers but well-chosen questions and an attentive, non-judgemental ear.","ear":"I gradually learned that the most valuable thing I could offer was not answers but well-chosen questions and an attentive, non-judgemental ear."},"fm":{"mentor":"mentored","circumstance":"circumstances"}},{"id":213,"lv":"C2","n":14,"title":"In Praise of Failure","tr":"Başarısızlığın değeri","text":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success. Many of them regarded a single setback as a verdict on their worth. I shared the unvarnished chronology of our missteps, from the leaking valves to the misjudged cooling strategy. I wanted them to grasp that failure, when acknowledged and scrutinised, is not the antithesis of competence but one of its indispensable ingredients.","words":["mentee","pervasive","dread","exacerbate","media","curate","setback","verdict","worth","unvarnished","chronology","misstep","misjudge","grasp","antithesis","competence","ingredient"],"ex":{"mentee":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success.","pervasive":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success.","dread":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success.","exacerbate":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success.","media":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success.","curate":"Among my mentees, I noticed a pervasive dread of failure, exacerbated perhaps by social media's relentless display of curated success.","setback":"Many of them regarded a single setback as a verdict on their worth.","verdict":"Many of them regarded a single setback as a verdict on their worth.","worth":"Many of them regarded a single setback as a verdict on their worth.","unvarnished":"I shared the unvarnished chronology of our missteps, from the leaking valves to the misjudged cooling strategy.","chronology":"I shared the unvarnished chronology of our missteps, from the leaking valves to the misjudged cooling strategy.","misstep":"I shared the unvarnished chronology of our missteps, from the leaking valves to the misjudged cooling strategy.","misjudge":"I shared the unvarnished chronology of our missteps, from the leaking valves to the misjudged cooling strategy.","grasp":"I wanted them to grasp that failure, when acknowledged and scrutinised, is not the antithesis of competence but one of its indispensable ingredients.","antithesis":"I wanted them to grasp that failure, when acknowledged and scrutinised, is not the antithesis of competence but one of its indispensable ingredients.","competence":"I wanted them to grasp that failure, when acknowledged and scrutinised, is not the antithesis of competence but one of its indispensable ingredients.","ingredient":"I wanted them to grasp that failure, when acknowledged and scrutinised, is not the antithesis of competence but one of its indispensable ingredients."},"fm":{"mentee":"mentees","exacerbate":"exacerbated","curate":"curated","misstep":"missteps","misjudge":"misjudged","ingredient":"ingredients"}},{"id":214,"lv":"C2","n":15,"title":"Engineering and Democracy","tr":"Mühendislik ve demokrasi","text":"Our collaboration with municipalities convinced me that infrastructure is inherently political. Decisions about where to build power lines, which neighbourhoods receive upgrades first, or how costs are apportioned all embody value judgements, however technical their presentation. When such decisions are made opaquely, public trust erodes. I became an advocate for participatory planning, in which citizens deliberate on infrastructure choices, cumbersome as such processes can be.","words":["collaboration","infrastructure","inherently","political","upgrade","apportion","opaquely","erode","participatory","citizen","deliberate","cumbersome"],"ex":{"collaboration":"Our collaboration with municipalities convinced me that infrastructure is inherently political.","infrastructure":"Our collaboration with municipalities convinced me that infrastructure is inherently political.","inherently":"Our collaboration with municipalities convinced me that infrastructure is inherently political.","political":"Our collaboration with municipalities convinced me that infrastructure is inherently political.","upgrade":"Decisions about where to build power lines, which neighbourhoods receive upgrades first, or how costs are apportioned all embody value judgements, however technical their presentation.","apportion":"Decisions about where to build power lines, which neighbourhoods receive upgrades first, or how costs are apportioned all embody value judgements, however technical their presentation.","opaquely":"When such decisions are made opaquely, public trust erodes.","erode":"When such decisions are made opaquely, public trust erodes.","participatory":"I became an advocate for participatory planning, in which citizens deliberate on infrastructure choices, cumbersome as such processes can be.","citizen":"I became an advocate for participatory planning, in which citizens deliberate on infrastructure choices, cumbersome as such processes can be.","deliberate":"I became an advocate for participatory planning, in which citizens deliberate on infrastructure choices, cumbersome as such processes can be.","cumbersome":"I became an advocate for participatory planning, in which citizens deliberate on infrastructure choices, cumbersome as such processes can be."},"fm":{"upgrade":"upgrades","apportion":"apportioned","erode":"erodes","citizen":"citizens"}},{"id":215,"lv":"C2","n":16,"title":"A Disillusionment","tr":"Bir hayal kırıklığı","text":"Not all my advocacy bore fruit. A national programme I had helped shape was, after a change of administration, diluted almost beyond recognition. Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households. I was disheartened and, for a while, cynical. Ayşe reminded me that progress is seldom linear and that disillusionment, if indulged, becomes an excuse for disengagement. I resolved not to let it.","words":["advocacy","administration","dilute","beyond","redirect","towards","conspicuous","favourable","negligible","impoverished","disheartened","cynical","linear","disillusionment","indulge","disengagement"],"ex":{"advocacy":"Not all my advocacy bore fruit.","administration":"A national programme I had helped shape was, after a change of administration, diluted almost beyond recognition.","dilute":"A national programme I had helped shape was, after a change of administration, diluted almost beyond recognition.","beyond":"A national programme I had helped shape was, after a change of administration, diluted almost beyond recognition.","redirect":"Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households.","towards":"Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households.","conspicuous":"Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households.","favourable":"Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households.","negligible":"Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households.","impoverished":"Funding was redirected towards conspicuous projects that yielded favourable headlines but negligible benefit to impoverished households.","disheartened":"I was disheartened and, for a while, cynical.","cynical":"I was disheartened and, for a while, cynical.","linear":"Ayşe reminded me that progress is seldom linear and that disillusionment, if indulged, becomes an excuse for disengagement.","disillusionment":"Ayşe reminded me that progress is seldom linear and that disillusionment, if indulged, becomes an excuse for disengagement.","indulge":"Ayşe reminded me that progress is seldom linear and that disillusionment, if indulged, becomes an excuse for disengagement.","disengagement":"Ayşe reminded me that progress is seldom linear and that disillusionment, if indulged, becomes an excuse for disengagement."},"fm":{"dilute":"diluted","redirect":"redirected","indulge":"indulged"}},{"id":216,"lv":"C2","n":17,"title":"Mert's Workshop","tr":"Mert'in atölyesi","text":"Mert, meanwhile, had flourished. He had founded his own workshop, training electricians in the installation of solar systems and battery storage. His apprentices adored his exacting standards and irreverent humour in equal measure. Visiting his workshop, I was struck by how naturally he combined meticulous craftsmanship with unpretentious generosity. The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","words":["flourish","apprentice","adore","exacting","standard","irreverent","humour","meticulous","craftsmanship","unpretentious","disparage","solicit","whenever","wiring","reversal","relish","discreetly"],"ex":{"flourish":"Mert, meanwhile, had flourished.","apprentice":"His apprentices adored his exacting standards and irreverent humour in equal measure.","adore":"His apprentices adored his exacting standards and irreverent humour in equal measure.","exacting":"His apprentices adored his exacting standards and irreverent humour in equal measure.","standard":"His apprentices adored his exacting standards and irreverent humour in equal measure.","irreverent":"His apprentices adored his exacting standards and irreverent humour in equal measure.","humour":"His apprentices adored his exacting standards and irreverent humour in equal measure.","meticulous":"Visiting his workshop, I was struck by how naturally he combined meticulous craftsmanship with unpretentious generosity.","craftsmanship":"Visiting his workshop, I was struck by how naturally he combined meticulous craftsmanship with unpretentious generosity.","unpretentious":"Visiting his workshop, I was struck by how naturally he combined meticulous craftsmanship with unpretentious generosity.","disparage":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","solicit":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","whenever":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","wiring":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","reversal":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","relish":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly.","discreetly":"The relatives who had once disparaged his choice now solicited his advice whenever their own wiring malfunctioned, a reversal he relished discreetly."},"fm":{"flourish":"flourished","apprentice":"apprentices","adore":"adored","standard":"standards","disparage":"disparaged","solicit":"solicited","relish":"relished"}},{"id":217,"lv":"C2","n":18,"title":"Ayşe's Research","tr":"Ayşe'nin araştırması","text":"Ayşe, now a clinical psychologist, was researching how chronic financial insecurity affects mental health. Our conversations revealed unexpected affinities between our fields. She explained that persistent anxiety about bills consumes cognitive resources, leaving people less able to plan ahead, a phenomenon researchers term scarcity. This reframed my understanding of energy poverty. A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways.","words":["clinical","psychologist","chronic","insecurity","mental","affinity","persistent","anxiety","cognitive","able","scarcity","reframe","physical","hardship","psychological","burden","compound","insidious"],"ex":{"clinical":"Ayşe, now a clinical psychologist, was researching how chronic financial insecurity affects mental health.","psychologist":"Ayşe, now a clinical psychologist, was researching how chronic financial insecurity affects mental health.","chronic":"Ayşe, now a clinical psychologist, was researching how chronic financial insecurity affects mental health.","insecurity":"Ayşe, now a clinical psychologist, was researching how chronic financial insecurity affects mental health.","mental":"Ayşe, now a clinical psychologist, was researching how chronic financial insecurity affects mental health.","affinity":"Our conversations revealed unexpected affinities between our fields.","persistent":"She explained that persistent anxiety about bills consumes cognitive resources, leaving people less able to plan ahead, a phenomenon researchers term scarcity.","anxiety":"She explained that persistent anxiety about bills consumes cognitive resources, leaving people less able to plan ahead, a phenomenon researchers term scarcity.","cognitive":"She explained that persistent anxiety about bills consumes cognitive resources, leaving people less able to plan ahead, a phenomenon researchers term scarcity.","able":"She explained that persistent anxiety about bills consumes cognitive resources, leaving people less able to plan ahead, a phenomenon researchers term scarcity.","scarcity":"She explained that persistent anxiety about bills consumes cognitive resources, leaving people less able to plan ahead, a phenomenon researchers term scarcity.","reframe":"This reframed my understanding of energy poverty.","physical":"A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways.","hardship":"A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways.","psychological":"A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways.","burden":"A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways.","compound":"A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways.","insidious":"A cold home was not merely a physical hardship but a psychological burden that compounded disadvantage in insidious ways."},"fm":{"affinity":"affinities","reframe":"reframed","compound":"compounded"}},{"id":218,"lv":"C2","n":19,"title":"How a Story Is Told","tr":"Bir hikâyenin anlatılışı","text":"My book was finally published in both Turkish and English. Its reception was gratifying, albeit modest. One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents. The critique stung, precisely because it was partly justified. Rereading my chapters, I discerned a condescending undertone I had not intended. It was a sobering reminder that narratives about others inevitably reveal as much about the narrator as about their subjects.","words":["reception","gratifying","albeit","criticise","romanticise","cast","passive","beneficiary","agent","critique","sting","precisely","chapter","discern","condescending","undertone","sobering","reminder","inevitably","narrator"],"ex":{"reception":"Its reception was gratifying, albeit modest.","gratifying":"Its reception was gratifying, albeit modest.","albeit":"Its reception was gratifying, albeit modest.","criticise":"One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents.","romanticise":"One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents.","cast":"One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents.","passive":"One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents.","beneficiary":"One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents.","agent":"One review, however, criticised me for romanticising rural life and casting villagers as passive beneficiaries rather than agents.","critique":"The critique stung, precisely because it was partly justified.","sting":"The critique stung, precisely because it was partly justified.","precisely":"The critique stung, precisely because it was partly justified.","chapter":"Rereading my chapters, I discerned a condescending undertone I had not intended.","discern":"Rereading my chapters, I discerned a condescending undertone I had not intended.","condescending":"Rereading my chapters, I discerned a condescending undertone I had not intended.","undertone":"Rereading my chapters, I discerned a condescending undertone I had not intended.","sobering":"It was a sobering reminder that narratives about others inevitably reveal as much about the narrator as about their subjects.","reminder":"It was a sobering reminder that narratives about others inevitably reveal as much about the narrator as about their subjects.","inevitably":"It was a sobering reminder that narratives about others inevitably reveal as much about the narrator as about their subjects.","narrator":"It was a sobering reminder that narratives about others inevitably reveal as much about the narrator as about their subjects."},"fm":{"criticise":"criticised","romanticise":"romanticising","cast":"casting","beneficiary":"beneficiaries","agent":"agents","sting":"stung","chapter":"chapters","discern":"discerned"}},{"id":219,"lv":"C2","n":20,"title":"Whose Voices?","tr":"Seslerin yeri","text":"In response, I collaborated with a documentary filmmaker on a project in which residents of the pilot villages recounted their own experiences, unmediated by my interpretation. Their accounts were by turns humorous, critical and moving. Hatice, now in her eighties, recalled her initial suspicion of \"the young engineers with their strange contraptions\" with mischievous delight. Relinquishing narrative authority felt uncomfortable, but the resulting film was far richer than anything I could have written.","words":["response","documentary","filmmaker","unmediated","interpretation","account","humorous","critical","moving","eighty","recall","suspicion","contraption","mischievous","rich","anything"],"ex":{"response":"In response, I collaborated with a documentary filmmaker on a project in which residents of the pilot villages recounted their own experiences, unmediated by my interpretation.","documentary":"In response, I collaborated with a documentary filmmaker on a project in which residents of the pilot villages recounted their own experiences, unmediated by my interpretation.","filmmaker":"In response, I collaborated with a documentary filmmaker on a project in which residents of the pilot villages recounted their own experiences, unmediated by my interpretation.","unmediated":"In response, I collaborated with a documentary filmmaker on a project in which residents of the pilot villages recounted their own experiences, unmediated by my interpretation.","interpretation":"In response, I collaborated with a documentary filmmaker on a project in which residents of the pilot villages recounted their own experiences, unmediated by my interpretation.","account":"Their accounts were by turns humorous, critical and moving.","humorous":"Their accounts were by turns humorous, critical and moving.","critical":"Their accounts were by turns humorous, critical and moving.","moving":"Their accounts were by turns humorous, critical and moving.","eighty":"Hatice, now in her eighties, recalled her initial suspicion of \"the young engineers with their strange contraptions\" with mischievous delight.","recall":"Hatice, now in her eighties, recalled her initial suspicion of \"the young engineers with their strange contraptions\" with mischievous delight.","suspicion":"Hatice, now in her eighties, recalled her initial suspicion of \"the young engineers with their strange contraptions\" with mischievous delight.","contraption":"Hatice, now in her eighties, recalled her initial suspicion of \"the young engineers with their strange contraptions\" with mischievous delight.","mischievous":"Hatice, now in her eighties, recalled her initial suspicion of \"the young engineers with their strange contraptions\" with mischievous delight.","rich":"Relinquishing narrative authority felt uncomfortable, but the resulting film was far richer than anything I could have written.","anything":"Relinquishing narrative authority felt uncomfortable, but the resulting film was far richer than anything I could have written."},"fm":{"account":"accounts","eighty":"eighties","recall":"recalled","contraption":"contraptions","rich":"richer"}},{"id":220,"lv":"C2","n":21,"title":"The Earthquake","tr":"Afet","text":"Then came the earthquake. In the early hours of a winter morning, a devastating tremor struck several provinces, and tens of thousands of buildings collapsed. Among the affected areas were towns where we had installed systems. In the following days, the scale of the catastrophe was almost incomprehensible. Our technicians, several of whom had lost relatives, nonetheless volunteered to help restore heating and electricity to emergency shelters in freezing conditions.","words":["earthquake","devastating","tremor","collapse","catastrophe","incomprehensible","volunteer","restore","shelter"],"ex":{"earthquake":"Then came the earthquake.","devastating":"In the early hours of a winter morning, a devastating tremor struck several provinces, and tens of thousands of buildings collapsed.","tremor":"In the early hours of a winter morning, a devastating tremor struck several provinces, and tens of thousands of buildings collapsed.","collapse":"In the early hours of a winter morning, a devastating tremor struck several provinces, and tens of thousands of buildings collapsed.","catastrophe":"In the following days, the scale of the catastrophe was almost incomprehensible.","incomprehensible":"In the following days, the scale of the catastrophe was almost incomprehensible.","volunteer":"Our technicians, several of whom had lost relatives, nonetheless volunteered to help restore heating and electricity to emergency shelters in freezing conditions.","restore":"Our technicians, several of whom had lost relatives, nonetheless volunteered to help restore heating and electricity to emergency shelters in freezing conditions.","shelter":"Our technicians, several of whom had lost relatives, nonetheless volunteered to help restore heating and electricity to emergency shelters in freezing conditions."},"fm":{"collapse":"collapsed","volunteer":"volunteered","shelter":"shelters"}},{"id":221,"lv":"C2","n":22,"title":"In the Aftermath","tr":"Yıkımın ardından","text":"Working in the aftermath of the disaster was harrowing. The physical devastation was overwhelming, yet it was the human loss that left the deepest imprint. I met an elderly man searching the rubble for photographs of his late wife. As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","words":["aftermath","disaster","harrowing","devastation","overwhelming","loss","deep","imprint","rubble","photograph","wife","avoid","truth","death","negligent","construction","lax","enforcement"],"ex":{"aftermath":"Working in the aftermath of the disaster was harrowing.","disaster":"Working in the aftermath of the disaster was harrowing.","harrowing":"Working in the aftermath of the disaster was harrowing.","devastation":"The physical devastation was overwhelming, yet it was the human loss that left the deepest imprint.","overwhelming":"The physical devastation was overwhelming, yet it was the human loss that left the deepest imprint.","loss":"The physical devastation was overwhelming, yet it was the human loss that left the deepest imprint.","deep":"The physical devastation was overwhelming, yet it was the human loss that left the deepest imprint.","imprint":"The physical devastation was overwhelming, yet it was the human loss that left the deepest imprint.","rubble":"I met an elderly man searching the rubble for photographs of his late wife.","photograph":"I met an elderly man searching the rubble for photographs of his late wife.","wife":"I met an elderly man searching the rubble for photographs of his late wife.","avoid":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","truth":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","death":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","negligent":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","construction":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","lax":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper.","enforcement":"As an engineer, I could not avoid confronting the uncomfortable truth that many deaths had resulted not from the earthquake itself but from negligent construction and the lax enforcement of building codes that had long existed on paper."},"fm":{"deep":"deepest","photograph":"photographs","death":"deaths"}},{"id":222,"lv":"C2","n":23,"title":"Accountability","tr":"Hesap verebilirlik","text":"The disaster provoked an intense public reckoning. Engineers, contractors and officials were scrutinised, and some faced prosecution. I felt a mixture of anger and introspection. It was too easy to blame individual wrongdoers while ignoring systemic incentives that rewarded speed and cost-cutting over safety. I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","words":["provoke","intense","reckoning","contractor","prosecution","anger","introspection","wrongdoer","systemic","incentive","reward","integrity","underpin","capable","uphold","conscientious","outcompete","unscrupulous"],"ex":{"provoke":"The disaster provoked an intense public reckoning.","intense":"The disaster provoked an intense public reckoning.","reckoning":"The disaster provoked an intense public reckoning.","contractor":"Engineers, contractors and officials were scrutinised, and some faced prosecution.","prosecution":"Engineers, contractors and officials were scrutinised, and some faced prosecution.","anger":"I felt a mixture of anger and introspection.","introspection":"I felt a mixture of anger and introspection.","wrongdoer":"It was too easy to blame individual wrongdoers while ignoring systemic incentives that rewarded speed and cost-cutting over safety.","systemic":"It was too easy to blame individual wrongdoers while ignoring systemic incentives that rewarded speed and cost-cutting over safety.","incentive":"It was too easy to blame individual wrongdoers while ignoring systemic incentives that rewarded speed and cost-cutting over safety.","reward":"It was too easy to blame individual wrongdoers while ignoring systemic incentives that rewarded speed and cost-cutting over safety.","integrity":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","underpin":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","capable":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","uphold":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","conscientious":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","outcompete":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones.","unscrupulous":"I wrote an essay arguing that professional integrity must be underpinned by institutions capable of upholding it; otherwise, conscientious engineers are simply outcompeted by unscrupulous ones."},"fm":{"provoke":"provoked","contractor":"contractors","wrongdoer":"wrongdoers","incentive":"incentives","reward":"rewarded","underpin":"underpinned","uphold":"upholding","outcompete":"outcompeted"}},{"id":223,"lv":"C2","n":24,"title":"Rebuilding","tr":"Yeniden inşa","text":"In the reconstruction that followed, our enterprise was invited to advise on making new housing both earthquake-resistant and energy-efficient. These objectives were occasionally in tension; heavy insulation materials, for instance, could add weight to structures. Reconciling them required close collaboration with structural engineers, architects and residents. I found myself repeatedly reiterating a principle I had learned from Professor Demir: rushed solutions, however well-intentioned, often entrench the very problems they purport to solve.","words":["reconstruction","housing","objective","tension","instance","weight","structure","reconcile","structural","architect","reiterate","rush","intention","entrench","purport"],"ex":{"reconstruction":"In the reconstruction that followed, our enterprise was invited to advise on making new housing both earthquake-resistant and energy-efficient.","housing":"In the reconstruction that followed, our enterprise was invited to advise on making new housing both earthquake-resistant and energy-efficient.","objective":"These objectives were occasionally in tension; heavy insulation materials, for instance, could add weight to structures.","tension":"These objectives were occasionally in tension; heavy insulation materials, for instance, could add weight to structures.","instance":"These objectives were occasionally in tension; heavy insulation materials, for instance, could add weight to structures.","weight":"These objectives were occasionally in tension; heavy insulation materials, for instance, could add weight to structures.","structure":"These objectives were occasionally in tension; heavy insulation materials, for instance, could add weight to structures.","reconcile":"Reconciling them required close collaboration with structural engineers, architects and residents.","structural":"Reconciling them required close collaboration with structural engineers, architects and residents.","architect":"Reconciling them required close collaboration with structural engineers, architects and residents.","reiterate":"I found myself repeatedly reiterating a principle I had learned from Professor Demir: rushed solutions, however well-intentioned, often entrench the very problems they purport to solve.","rush":"I found myself repeatedly reiterating a principle I had learned from Professor Demir: rushed solutions, however well-intentioned, often entrench the very problems they purport to solve.","intention":"I found myself repeatedly reiterating a principle I had learned from Professor Demir: rushed solutions, however well-intentioned, often entrench the very problems they purport to solve.","entrench":"I found myself repeatedly reiterating a principle I had learned from Professor Demir: rushed solutions, however well-intentioned, often entrench the very problems they purport to solve.","purport":"I found myself repeatedly reiterating a principle I had learned from Professor Demir: rushed solutions, however well-intentioned, often entrench the very problems they purport to solve."},"fm":{"objective":"objectives","structure":"structures","reconcile":"reconciling","architect":"architects","reiterate":"reiterating","rush":"rushed","intention":"intentioned"}},{"id":224,"lv":"C2","n":25,"title":"Resilience","tr":"Dayanıklılık","text":"The earthquake reshaped my thinking about resilience. Efficient systems are frequently optimised to the point of fragility, with no redundancy to absorb shocks. In the shelters, decentralised solar panels and batteries had continued to function when the central grid collapsed. I began to argue that energy planning should value robustness and redundancy, even at some cost to efficiency. Resilience, I suggested, is the capacity not merely to withstand disruption but to recover gracefully from it.","words":["reshape","resilience","fragility","redundancy","absorb","decentralise","function","robustness","withstand","recover","gracefully"],"ex":{"reshape":"The earthquake reshaped my thinking about resilience.","resilience":"The earthquake reshaped my thinking about resilience.","fragility":"Efficient systems are frequently optimised to the point of fragility, with no redundancy to absorb shocks.","redundancy":"Efficient systems are frequently optimised to the point of fragility, with no redundancy to absorb shocks.","absorb":"Efficient systems are frequently optimised to the point of fragility, with no redundancy to absorb shocks.","decentralise":"In the shelters, decentralised solar panels and batteries had continued to function when the central grid collapsed.","function":"In the shelters, decentralised solar panels and batteries had continued to function when the central grid collapsed.","robustness":"I began to argue that energy planning should value robustness and redundancy, even at some cost to efficiency.","withstand":"Resilience, I suggested, is the capacity not merely to withstand disruption but to recover gracefully from it.","recover":"Resilience, I suggested, is the capacity not merely to withstand disruption but to recover gracefully from it.","gracefully":"Resilience, I suggested, is the capacity not merely to withstand disruption but to recover gracefully from it."},"fm":{"reshape":"reshaped","decentralise":"decentralised"}},{"id":225,"lv":"C2","n":26,"title":"A Letter from Can","tr":"Can'ın mektubu","text":"Some months later, Can wrote me a long letter, an unusual gesture in an age of terse messages. He reflected on our student years, the robot that once spun in circles, and the late-night conversation that had prompted his change of career. His medical imaging equipment was now used in hospitals across the region, including some that had treated earthquake survivors. He closed with characteristic understatement: \"Not bad for two kids who once burned their fingers soldering.\"","words":["unusual","gesture","spin","across","survivor","understatement","kid"],"ex":{"unusual":"Some months later, Can wrote me a long letter, an unusual gesture in an age of terse messages.","gesture":"Some months later, Can wrote me a long letter, an unusual gesture in an age of terse messages.","spin":"He reflected on our student years, the robot that once spun in circles, and the late-night conversation that had prompted his change of career.","across":"His medical imaging equipment was now used in hospitals across the region, including some that had treated earthquake survivors.","survivor":"His medical imaging equipment was now used in hospitals across the region, including some that had treated earthquake survivors.","understatement":"He closed with characteristic understatement: \"Not bad for two kids who once burned their fingers soldering.\"","kid":"He closed with characteristic understatement: \"Not bad for two kids who once burned their fingers soldering.\""},"fm":{"spin":"spun","survivor":"survivors","kid":"kids"}},{"id":226,"lv":"C2","n":27,"title":"Meeting Elif Again","tr":"Elif ile buluşma","text":"Elif, whom I had seen only sporadically over the years, visited Ankara for a medical conference. She had become a paediatric surgeon of considerable renown. Over a long dinner, we compared the ethical dilemmas of our professions: she weighed the risks of operating on fragile infants; I weighed the trade-offs between affordability and safety. We agreed that both medicine and engineering demand acting decisively despite irreducible uncertainty, and living with the consequences.","words":["sporadically","paediatric","surgeon","renown","profession","operate","fragile","infant","affordability","act","decisively","irreducible"],"ex":{"sporadically":"Elif, whom I had seen only sporadically over the years, visited Ankara for a medical conference.","paediatric":"She had become a paediatric surgeon of considerable renown.","surgeon":"She had become a paediatric surgeon of considerable renown.","renown":"She had become a paediatric surgeon of considerable renown.","profession":"Over a long dinner, we compared the ethical dilemmas of our professions: she weighed the risks of operating on fragile infants; I weighed the trade-offs between affordability and safety.","operate":"Over a long dinner, we compared the ethical dilemmas of our professions: she weighed the risks of operating on fragile infants; I weighed the trade-offs between affordability and safety.","fragile":"Over a long dinner, we compared the ethical dilemmas of our professions: she weighed the risks of operating on fragile infants; I weighed the trade-offs between affordability and safety.","infant":"Over a long dinner, we compared the ethical dilemmas of our professions: she weighed the risks of operating on fragile infants; I weighed the trade-offs between affordability and safety.","affordability":"Over a long dinner, we compared the ethical dilemmas of our professions: she weighed the risks of operating on fragile infants; I weighed the trade-offs between affordability and safety.","act":"We agreed that both medicine and engineering demand acting decisively despite irreducible uncertainty, and living with the consequences.","decisively":"We agreed that both medicine and engineering demand acting decisively despite irreducible uncertainty, and living with the consequences.","irreducible":"We agreed that both medicine and engineering demand acting decisively despite irreducible uncertainty, and living with the consequences."},"fm":{"profession":"professions","operate":"operating","infant":"infants","act":"acting"}},{"id":227,"lv":"C2","n":28,"title":"Technological Optimism","tr":"Teknolojik iyimserlik","text":"A younger colleague once accused me, not unkindly, of having become a pessimist. I protested that I remained an optimist, though of a chastened variety. Naive technological optimism presumes that ingenuity will automatically resolve our predicaments. The optimism I endorse is more conditional: it acknowledges that technologies can mitigate suffering, but only when embedded in just institutions, accompanied by humility, and subjected to the scrutiny of those who must live with them.","words":["accuse","unkindly","pessimist","protest","optimist","chastened","variety","technological","optimism","ingenuity","endorse","mitigate","embed","humility","scrutiny"],"ex":{"accuse":"A younger colleague once accused me, not unkindly, of having become a pessimist.","unkindly":"A younger colleague once accused me, not unkindly, of having become a pessimist.","pessimist":"A younger colleague once accused me, not unkindly, of having become a pessimist.","protest":"I protested that I remained an optimist, though of a chastened variety.","optimist":"I protested that I remained an optimist, though of a chastened variety.","chastened":"I protested that I remained an optimist, though of a chastened variety.","variety":"I protested that I remained an optimist, though of a chastened variety.","technological":"Naive technological optimism presumes that ingenuity will automatically resolve our predicaments.","optimism":"Naive technological optimism presumes that ingenuity will automatically resolve our predicaments.","ingenuity":"Naive technological optimism presumes that ingenuity will automatically resolve our predicaments.","endorse":"The optimism I endorse is more conditional: it acknowledges that technologies can mitigate suffering, but only when embedded in just institutions, accompanied by humility, and subjected to the scrutiny of those who must live with them.","mitigate":"The optimism I endorse is more conditional: it acknowledges that technologies can mitigate suffering, but only when embedded in just institutions, accompanied by humility, and subjected to the scrutiny of those who must live with them.","embed":"The optimism I endorse is more conditional: it acknowledges that technologies can mitigate suffering, but only when embedded in just institutions, accompanied by humility, and subjected to the scrutiny of those who must live with them.","humility":"The optimism I endorse is more conditional: it acknowledges that technologies can mitigate suffering, but only when embedded in just institutions, accompanied by humility, and subjected to the scrutiny of those who must live with them.","scrutiny":"The optimism I endorse is more conditional: it acknowledges that technologies can mitigate suffering, but only when embedded in just institutions, accompanied by humility, and subjected to the scrutiny of those who must live with them."},"fm":{"accuse":"accused","protest":"protested","embed":"embedded"}},{"id":228,"lv":"C2","n":29,"title":"Time and Maintenance","tr":"Zaman ve bakım","text":"Visiting a village where we had installed our earliest systems over fifteen years earlier, I was moved to find several still functioning, lovingly patched by local technicians. Maintenance, I reflected, is the unsung counterpart of innovation. Societies lavish admiration on inventors while neglecting the custodians who keep things working. Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap. I resolved to champion the dignity of repair.","words":["fifteen","lovingly","patch","unsung","counterpart","lavish","admiration","inventor","neglect","custodian","diligent","ingenious","invention","swiftly","deteriorate","scrap","champion","dignity"],"ex":{"fifteen":"Visiting a village where we had installed our earliest systems over fifteen years earlier, I was moved to find several still functioning, lovingly patched by local technicians.","lovingly":"Visiting a village where we had installed our earliest systems over fifteen years earlier, I was moved to find several still functioning, lovingly patched by local technicians.","patch":"Visiting a village where we had installed our earliest systems over fifteen years earlier, I was moved to find several still functioning, lovingly patched by local technicians.","unsung":"Maintenance, I reflected, is the unsung counterpart of innovation.","counterpart":"Maintenance, I reflected, is the unsung counterpart of innovation.","lavish":"Societies lavish admiration on inventors while neglecting the custodians who keep things working.","admiration":"Societies lavish admiration on inventors while neglecting the custodians who keep things working.","inventor":"Societies lavish admiration on inventors while neglecting the custodians who keep things working.","neglect":"Societies lavish admiration on inventors while neglecting the custodians who keep things working.","custodian":"Societies lavish admiration on inventors while neglecting the custodians who keep things working.","diligent":"Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap.","ingenious":"Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap.","invention":"Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap.","swiftly":"Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap.","deteriorate":"Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap.","scrap":"Yet without diligent maintenance, even the most ingenious invention swiftly deteriorates into scrap.","champion":"I resolved to champion the dignity of repair.","dignity":"I resolved to champion the dignity of repair."},"fm":{"patch":"patched","inventor":"inventors","neglect":"neglecting","custodian":"custodians","deteriorate":"deteriorates"}},{"id":229,"lv":"C2","n":30,"title":"The Right to Repair","tr":"Onarım hakkı","text":"That conviction drew me into the movement for the right to repair. Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks. This practice, while profitable, generates mountains of waste and deprives communities of autonomy. I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","words":["conviction","movement","deliberately","employ","proprietary","seal","casing","lock","profitable","deprive","autonomy","testify","parliamentary","repairable","mandate","discretion","whose","opposite"],"ex":{"conviction":"That conviction drew me into the movement for the right to repair.","movement":"That conviction drew me into the movement for the right to repair.","deliberately":"Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks.","employ":"Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks.","proprietary":"Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks.","seal":"Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks.","casing":"Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks.","lock":"Manufacturers increasingly design products that are deliberately difficult to fix, employing proprietary parts, sealed casings and software locks.","profitable":"This practice, while profitable, generates mountains of waste and deprives communities of autonomy.","deprive":"This practice, while profitable, generates mountains of waste and deprives communities of autonomy.","autonomy":"This practice, while profitable, generates mountains of waste and deprives communities of autonomy.","testify":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","parliamentary":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","repairable":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","mandate":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","discretion":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","whose":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction.","opposite":"I testified before a parliamentary committee, arguing that durable, repairable design should be mandated rather than left to the discretion of companies whose incentives point in the opposite direction."},"fm":{"employ":"employing","seal":"sealed","casing":"casings","lock":"locks","deprive":"deprives","testify":"testified","mandate":"mandated"}},{"id":230,"lv":"C2","n":31,"title":"A Student's Question","tr":"Bir öğrencinin sorusu","text":"At a university lecture, a student posed a question that unsettled me: had I ever compromised my principles for the sake of the enterprise? After a pause, I admitted that I had. Years earlier, under financial duress, we had accepted funding from a company whose environmental record I found dubious. I had rationalised it as pragmatic. Recounting it publicly was uncomfortable, but candour seemed more instructive than an unblemished but fictitious portrait of integrity.","words":["pose","unsettle","ever","sake","pause","duress","dubious","pragmatic","publicly","instructive","unblemished","fictitious","portrait"],"ex":{"pose":"At a university lecture, a student posed a question that unsettled me: had I ever compromised my principles for the sake of the enterprise?","unsettle":"At a university lecture, a student posed a question that unsettled me: had I ever compromised my principles for the sake of the enterprise?","ever":"At a university lecture, a student posed a question that unsettled me: had I ever compromised my principles for the sake of the enterprise?","sake":"At a university lecture, a student posed a question that unsettled me: had I ever compromised my principles for the sake of the enterprise?","pause":"After a pause, I admitted that I had.","duress":"Years earlier, under financial duress, we had accepted funding from a company whose environmental record I found dubious.","dubious":"Years earlier, under financial duress, we had accepted funding from a company whose environmental record I found dubious.","pragmatic":"I had rationalised it as pragmatic.","publicly":"Recounting it publicly was uncomfortable, but candour seemed more instructive than an unblemished but fictitious portrait of integrity.","instructive":"Recounting it publicly was uncomfortable, but candour seemed more instructive than an unblemished but fictitious portrait of integrity.","unblemished":"Recounting it publicly was uncomfortable, but candour seemed more instructive than an unblemished but fictitious portrait of integrity.","fictitious":"Recounting it publicly was uncomfortable, but candour seemed more instructive than an unblemished but fictitious portrait of integrity.","portrait":"Recounting it publicly was uncomfortable, but candour seemed more instructive than an unblemished but fictitious portrait of integrity."},"fm":{"pose":"posed","unsettle":"unsettled"}},{"id":231,"lv":"C2","n":32,"title":"Moral Compromise","tr":"Ahlaki uzlaşma","text":"The student's question prompted me to think more carefully about moral compromise. Absolute purity is rarely attainable for those who act in the world; abstention, too, has consequences. Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial. The danger, I concluded, lies less in any single decision than in the imperceptible drift of habit.","words":["absolute","purity","attainable","abstention","meaningful","distinction","principled","undertake","transparently","gradual","erosion","concession","trivial","lie","imperceptible","drift"],"ex":{"absolute":"Absolute purity is rarely attainable for those who act in the world; abstention, too, has consequences.","purity":"Absolute purity is rarely attainable for those who act in the world; abstention, too, has consequences.","attainable":"Absolute purity is rarely attainable for those who act in the world; abstention, too, has consequences.","abstention":"Absolute purity is rarely attainable for those who act in the world; abstention, too, has consequences.","meaningful":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","distinction":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","principled":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","undertake":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","transparently":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","gradual":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","erosion":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","concession":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","trivial":"Yet there is a meaningful distinction between principled compromise, undertaken transparently and with clear limits, and gradual erosion, in which each concession makes the next seem trivial.","lie":"The danger, I concluded, lies less in any single decision than in the imperceptible drift of habit.","imperceptible":"The danger, I concluded, lies less in any single decision than in the imperceptible drift of habit.","drift":"The danger, I concluded, lies less in any single decision than in the imperceptible drift of habit."},"fm":{"undertake":"undertaken","lie":"lies"}},{"id":232,"lv":"C2","n":33,"title":"Language and Thought","tr":"Dil ve düşünce","text":"Living much of my life in two languages had subtly altered how I think. Certain ideas seemed to come more readily in English, others only in Turkish. Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis. I came to regard bilingualism not as a mere skill but as a kind of double vision, enabling me to perceive the assumptions embedded in each language.","words":["subtly","alter","readily","expression","steep","communal","satisfactory","equivalent","afford","detachment","bilingualism","mere","double","perceive"],"ex":{"subtly":"Living much of my life in two languages had subtly altered how I think.","alter":"Living much of my life in two languages had subtly altered how I think.","readily":"Certain ideas seemed to come more readily in English, others only in Turkish.","expression":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","steep":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","communal":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","satisfactory":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","equivalent":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","afford":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","detachment":"Some Turkish expressions, steeped in communal warmth, have no satisfactory English equivalent, while English afforded me a certain detachment useful in analysis.","bilingualism":"I came to regard bilingualism not as a mere skill but as a kind of double vision, enabling me to perceive the assumptions embedded in each language.","mere":"I came to regard bilingualism not as a mere skill but as a kind of double vision, enabling me to perceive the assumptions embedded in each language.","double":"I came to regard bilingualism not as a mere skill but as a kind of double vision, enabling me to perceive the assumptions embedded in each language.","perceive":"I came to regard bilingualism not as a mere skill but as a kind of double vision, enabling me to perceive the assumptions embedded in each language."},"fm":{"alter":"altered","expression":"expressions","steep":"steeped","afford":"afforded"}},{"id":233,"lv":"C2","n":34,"title":"My Father Retires","tr":"Babamın emekliliği","text":"My father retired after forty years of teaching. At his farewell ceremony, former pupils, some now grey-haired, spoke of the enduring influence of his patience and integrity. Listening to them, I recognised how profoundly his quiet example had shaped my own conduct. He had never lectured me on ethics; he had simply lived consistently with his convictions. I realised that the most enduring forms of teaching are often unspoken.","words":["retire","pupil","enduring","influence","profoundly","consistently","unspoken"],"ex":{"retire":"My father retired after forty years of teaching.","pupil":"At his farewell ceremony, former pupils, some now grey-haired, spoke of the enduring influence of his patience and integrity.","enduring":"At his farewell ceremony, former pupils, some now grey-haired, spoke of the enduring influence of his patience and integrity.","influence":"At his farewell ceremony, former pupils, some now grey-haired, spoke of the enduring influence of his patience and integrity.","profoundly":"Listening to them, I recognised how profoundly his quiet example had shaped my own conduct.","consistently":"He had never lectured me on ethics; he had simply lived consistently with his convictions.","unspoken":"I realised that the most enduring forms of teaching are often unspoken."},"fm":{"retire":"retired","pupil":"pupils"}},{"id":234,"lv":"C2","n":35,"title":"The Meaning of Legacy","tr":"Mirasın anlamı","text":"His retirement prompted me to contemplate the elusive notion of legacy. I had once imagined it as some monumental achievement bearing one's name. Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged. My grandmother had left no monument, yet her influence permeated an entire enterprise and the lives of dozens of technicians she never met.","words":["retirement","contemplate","elusive","imagine","monumental","diffuse","sustain","kindness","ripple","outward","unacknowledged","monument","permeate"],"ex":{"retirement":"His retirement prompted me to contemplate the elusive notion of legacy.","contemplate":"His retirement prompted me to contemplate the elusive notion of legacy.","elusive":"His retirement prompted me to contemplate the elusive notion of legacy.","imagine":"I had once imagined it as some monumental achievement bearing one's name.","monumental":"I had once imagined it as some monumental achievement bearing one's name.","diffuse":"Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged.","sustain":"Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged.","kindness":"Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged.","ripple":"Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged.","outward":"Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged.","unacknowledged":"Increasingly, I suspected that legacy is more diffuse: the habits we instil in others, the institutions we help sustain, the kindnesses that ripple outward unacknowledged.","monument":"My grandmother had left no monument, yet her influence permeated an entire enterprise and the lives of dozens of technicians she never met.","permeate":"My grandmother had left no monument, yet her influence permeated an entire enterprise and the lives of dozens of technicians she never met."},"fm":{"imagine":"imagined","kindness":"kindnesses","permeate":"permeated"}},{"id":235,"lv":"C2","n":36,"title":"Return to London","tr":"Londra'ya dönüş","text":"Decades after my first trip, I returned to London for a conference. On impulse, I visited the street where the Wilsons had lived. The house had been repainted, and strangers now occupied it. Lucy, I knew, was a teacher in Manchester, and Jack, astonishingly, had become a robotics engineer who credited my youthful enthusiasm with sparking his vocation. Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","words":["impulse","repaint","stranger","occupy","astonishingly","youthful","spark","vocation","stand","pavement","familiar","drizzle","vertigo","fold","upon"],"ex":{"impulse":"On impulse, I visited the street where the Wilsons had lived.","repaint":"The house had been repainted, and strangers now occupied it.","stranger":"The house had been repainted, and strangers now occupied it.","occupy":"The house had been repainted, and strangers now occupied it.","astonishingly":"Lucy, I knew, was a teacher in Manchester, and Jack, astonishingly, had become a robotics engineer who credited my youthful enthusiasm with sparking his vocation.","youthful":"Lucy, I knew, was a teacher in Manchester, and Jack, astonishingly, had become a robotics engineer who credited my youthful enthusiasm with sparking his vocation.","spark":"Lucy, I knew, was a teacher in Manchester, and Jack, astonishingly, had become a robotics engineer who credited my youthful enthusiasm with sparking his vocation.","vocation":"Lucy, I knew, was a teacher in Manchester, and Jack, astonishingly, had become a robotics engineer who credited my youthful enthusiasm with sparking his vocation.","stand":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","pavement":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","familiar":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","drizzle":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","vertigo":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","fold":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself.","upon":"Standing on that pavement in the familiar drizzle, I felt the strange vertigo of time folding back upon itself."},"fm":{"repaint":"repainted","stranger":"strangers","occupy":"occupied","spark":"sparking","stand":"standing","fold":"folding"}},{"id":236,"lv":"C2","n":37,"title":"The Science Museum Revisited","tr":"Bilim Müzesi","text":"I also revisited the Science Museum, where I had once marvelled at steam engines. The exhibitions had been transformed, now foregrounding climate, energy transitions and the ethical quandaries of technology. In one gallery, I paused before a display questioning whether progress is always beneficial. My younger self would have found the question perplexing, even faintly heretical. Now it struck me as the most important question an engineering museum could pose.","words":["revisit","marvel","exhibition","foreground","quandary","gallery","beneficial","perplexing","faintly","heretical"],"ex":{"revisit":"I also revisited the Science Museum, where I had once marvelled at steam engines.","marvel":"I also revisited the Science Museum, where I had once marvelled at steam engines.","exhibition":"The exhibitions had been transformed, now foregrounding climate, energy transitions and the ethical quandaries of technology.","foreground":"The exhibitions had been transformed, now foregrounding climate, energy transitions and the ethical quandaries of technology.","quandary":"The exhibitions had been transformed, now foregrounding climate, energy transitions and the ethical quandaries of technology.","gallery":"In one gallery, I paused before a display questioning whether progress is always beneficial.","beneficial":"In one gallery, I paused before a display questioning whether progress is always beneficial.","perplexing":"My younger self would have found the question perplexing, even faintly heretical.","faintly":"My younger self would have found the question perplexing, even faintly heretical.","heretical":"My younger self would have found the question perplexing, even faintly heretical."},"fm":{"revisit":"revisited","marvel":"marvelled","exhibition":"exhibitions","foreground":"foregrounding","quandary":"quandaries"}},{"id":237,"lv":"C2","n":38,"title":"Drafting a Speech","tr":"Bir konuşmanın taslağı","text":"Back in Ankara, I was asked to deliver the commencement address at my old university. Drafting it proved unexpectedly daunting. I wanted to avoid both hollow inspiration and world-weary cynicism. Eventually, I settled on a simple structure: three things I wished I had understood at their age. That competence is collective, not solitary. That doubt is a professional virtue. And that the purpose of engineering is not machines but the flourishing of the people they serve.","words":["commencement","daunting","hollow","inspiration","weary","cynicism","settle","collective","solitary","virtue","serve"],"ex":{"commencement":"Back in Ankara, I was asked to deliver the commencement address at my old university.","daunting":"Drafting it proved unexpectedly daunting.","hollow":"I wanted to avoid both hollow inspiration and world-weary cynicism.","inspiration":"I wanted to avoid both hollow inspiration and world-weary cynicism.","weary":"I wanted to avoid both hollow inspiration and world-weary cynicism.","cynicism":"I wanted to avoid both hollow inspiration and world-weary cynicism.","settle":"Eventually, I settled on a simple structure: three things I wished I had understood at their age.","collective":"That competence is collective, not solitary.","solitary":"That competence is collective, not solitary.","virtue":"That doubt is a professional virtue.","serve":"And that the purpose of engineering is not machines but the flourishing of the people they serve."},"fm":{"settle":"settled"}},{"id":238,"lv":"C2","n":39,"title":"The Commencement Address","tr":"Mezuniyet konuşması","text":"Standing at the lectern, I gazed at the sea of young faces and remembered my own graduation, my grandmother cradling my diploma as though it were made of glass. I told the graduates that they would inherit problems my generation had failed to solve, and that I offered not an apology but an invitation. \"Be rigorous, be humble, and be kind,\" I concluded. The applause was warm, but it was the faces of the anxious, hopeful few that stayed with me.","words":["lectern","gaze","cradle","inherit","apology","invitation","humble","applause","hopeful"],"ex":{"lectern":"Standing at the lectern, I gazed at the sea of young faces and remembered my own graduation, my grandmother cradling my diploma as though it were made of glass.","gaze":"Standing at the lectern, I gazed at the sea of young faces and remembered my own graduation, my grandmother cradling my diploma as though it were made of glass.","cradle":"Standing at the lectern, I gazed at the sea of young faces and remembered my own graduation, my grandmother cradling my diploma as though it were made of glass.","inherit":"I told the graduates that they would inherit problems my generation had failed to solve, and that I offered not an apology but an invitation.","apology":"I told the graduates that they would inherit problems my generation had failed to solve, and that I offered not an apology but an invitation.","invitation":"I told the graduates that they would inherit problems my generation had failed to solve, and that I offered not an apology but an invitation.","humble":"\"Be rigorous, be humble, and be kind,\" I concluded.","applause":"The applause was warm, but it was the faces of the anxious, hopeful few that stayed with me.","hopeful":"The applause was warm, but it was the faces of the anxious, hopeful few that stayed with me."},"fm":{"gaze":"gazed","cradle":"cradling"}},{"id":239,"lv":"C2","n":40,"title":"The Unfinished Journey","tr":"Bitmeyen yolculuk","text":"Tonight, as I write these lines, an old notebook lies open beside me. On its first page, in my clumsy adolescent handwriting, are the words: \"My name is Deniz. I am a student.\" I have learned two languages, built an enterprise, endured loss and made innumerable mistakes. Yet those first sentences remain, in the deepest sense, true. Learning is not a stage of life one completes but a way of living one chooses, again and again.","words":["tonight","clumsy","adolescent","handwriting","endure"],"ex":{"tonight":"Tonight, as I write these lines, an old notebook lies open beside me.","clumsy":"On its first page, in my clumsy adolescent handwriting, are the words: \"My name is Deniz.","adolescent":"On its first page, in my clumsy adolescent handwriting, are the words: \"My name is Deniz.","handwriting":"On its first page, in my clumsy adolescent handwriting, are the words: \"My name is Deniz.","endure":"I have learned two languages, built an enterprise, endured loss and made innumerable mistakes."},"fm":{"endure":"endured"}}];
